window.LANG_PACKS.zh.builder = [{"id":1,"vi":"không","note":"不 đứng trước động từ hoặc tính từ để phủ định (không làm gì, không như thế nào); với 有 và việc trong quá khứ thì dùng 没 (没有). 不 đọc thành \"bú\" khi đứng trước thanh 4.","pivot":{"t":"不","ph":"bù","vph":"pu"},"branches":[{"steps":[{"t":"说","ph":"shuō","vph":"sua","vi":"nói","hl":[]},{"t":"不说","ph":"bù shuō","vph":"pu sua","vi":"không nói","hl":["不"]},{"t":"我不说。","ph":"Wǒ bù shuō.","vph":"Ủa pu sua.","vi":"Tôi không nói.","hl":["不"],"tokens":["我","不","说"]}]},{"steps":[{"t":"去","ph":"qù","vph":"chuy","vi":"đi","hl":[]},{"t":"不去","ph":"bú qù","vph":"pú chuy","vi":"không đi","hl":["不"]},{"t":"我今天不去。","ph":"Wǒ jīntiān bú qù.","vph":"Ủa chin thiên pú chuy.","vi":"Hôm nay tôi không đi.","hl":["不"],"tokens":["我","今天","不","去"]}]},{"steps":[{"t":"辣","ph":"là","vph":"la","vi":"cay","hl":[]},{"t":"不辣","ph":"bú là","vph":"pú la","vi":"không cay","hl":["不"]},{"t":"这个菜不辣。","ph":"Zhège cài bú là.","vph":"Chưa cưa chai pú la.","vi":"Món này không cay.","hl":["不"],"tokens":["这个","菜","不","辣"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"不"},{"k":"V","t":"Động từ / Tính từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["不 đứng ngay trước động từ hoặc tính từ để phủ định (\"不去\" - không đi, \"不辣\" - không cay).","不 dùng cho hiện tại, tương lai, thói quen và ý muốn; việc đã xảy ra trong quá khứ thì dùng 没 (\"我昨天没去\").","Riêng 有 không bao giờ đi với 不: \"không có\" luôn là 没有.","不 vốn đọc thanh 4 (bù), nhưng đứng trước một chữ thanh 4 thì đổi thành thanh 2 (bú): \"不去 bú qù\", \"不贵 bú guì\"."],"mistakes":[{"wrong":"我不有钱。","right":"我没有钱。","why":"有 chỉ phủ định bằng 没, không bao giờ nói 不有."},{"wrong":"我昨天不去。","right":"我昨天没去。","why":"Việc đã qua (hôm qua không đi) phải dùng 没, 不 dùng cho hiện tại và tương lai."}],"compare":"Giống tiếng Việt: 不 đứng trước động từ/tính từ như chữ \"không\" (不去 = không đi, 不辣 = không cay). Khác: tiếng Việt dùng \"không\" cho cả quá khứ, còn tiếng Trung việc đã xảy ra phải đổi sang 没.","tip":"不 gặp thanh 4 thì \"bú\" lên thanh 2: 不去 bú qù, 不是 bú shì, 不要 bú yào.","how":["Lấy động từ 说 (nói), thêm 不 phía trước → 不说, rồi đặt chủ ngữ 我 lên đầu → 我不说。","Thêm 不 trước 去 → 不去 (不 đọc bú vì 去 thanh 4), rồi đặt chủ ngữ 我 và thời gian 今天 phía trước → 我今天不去。","Thêm 不 trước tính từ 辣 → 不辣, rồi đặt chủ ngữ 这个菜 lên đầu (không cần 是) → 这个菜不辣。"],"dialog":[{"who":"A","t":"你喝酒吗？","ph":"Nǐ hē jiǔ ma?","vph":"Nỉ khưa chiểu ma?","vi":"Bạn có uống rượu không?","hl":[]},{"who":"B","t":"我不喝酒。","ph":"Wǒ bù hē jiǔ.","vph":"Ủa pu khưa chiểu.","vi":"Tôi không uống rượu.","hl":["不"]},{"who":"A","t":"那喝茶吧？","ph":"Nà hē chá ba?","vph":"Na khưa chá pa?","vi":"Vậy uống trà nhé?","hl":[]},{"who":"B","t":"好，我不要糖。","ph":"Hǎo, wǒ bú yào táng.","vph":"Hảo, ủa pú dao tháng.","vi":"Được, tôi không cần đường.","hl":["不"]}],"more":[{"t":"今天不冷。","ph":"Jīntiān bù lěng.","vph":"Chin thiên pu lẩng.","vi":"Hôm nay không lạnh.","hl":["不"],"tokens":["今天","不","冷"]},{"t":"这个不贵。","ph":"Zhège bú guì.","vph":"Chưa cưa pú quây.","vi":"Cái này không đắt.","hl":["不"],"tokens":["这个","不","贵"]},{"t":"我不吃肉。","ph":"Wǒ bù chī ròu.","vph":"Ủa pu chư râu.","vi":"Tôi không ăn thịt.","hl":["不"],"tokens":["我","不","吃","肉"]},{"t":"我不会说英语。","ph":"Wǒ bú huì shuō Yīngyǔ.","vph":"Ủa pú huây sua Inh dủy.","vi":"Tôi không biết nói tiếng Anh.","hl":["不"],"tokens":["我","不","会","说","英语"]},{"t":"他不喜欢喝咖啡。","ph":"Tā bù xǐhuan hē kāfēi.","vph":"Tha pu xỉ hoan khưa kha phây.","vi":"Anh ấy không thích uống cà phê.","hl":["不"],"tokens":["他","不","喜欢","喝","咖啡"]},{"t":"这家酒店的房间不太大。","ph":"Zhè jiā jiǔdiàn de fángjiān bú tài dà.","vph":"Chưa chia chiểu tiên tơ pháng chiên pú thai ta.","vi":"Phòng của khách sạn này không lớn lắm.","hl":["不"],"tokens":["这","家","酒店","的","房间","不","太","大"]}]},{"id":2,"vi":"có","note":"有 + danh từ diễn tả sở hữu hoặc tồn tại (có cái gì). Phủ định của 有 luôn là 没有, không dùng 不有.","pivot":{"t":"有","ph":"yǒu","vph":"dẩu"},"branches":[{"steps":[{"t":"护照","ph":"hùzhào","vph":"hu chao","vi":"hộ chiếu","hl":[]},{"t":"有护照","ph":"yǒu hùzhào","vph":"dẩu hu chao","vi":"có hộ chiếu","hl":["有"]},{"t":"我有护照。","ph":"Wǒ yǒu hùzhào.","vph":"Ủa dẩu hu chao.","vi":"Tôi có hộ chiếu.","hl":["有"],"tokens":["我","有","护照"]}]},{"steps":[{"t":"时间","ph":"shíjiān","vph":"sứ chiên","vi":"thời gian","hl":[]},{"t":"有时间","ph":"yǒu shíjiān","vph":"dẩu sứ chiên","vi":"có thời gian","hl":["有"]},{"t":"你明天有时间吗？","ph":"Nǐ míngtiān yǒu shíjiān ma?","vph":"Nỉ mính thiên dẩu sứ chiên ma?","vi":"Ngày mai bạn có rảnh không?","hl":["有"],"tokens":["你","明天","有","时间","吗"]}]},{"steps":[{"t":"房间","ph":"fángjiān","vph":"pháng chiên","vi":"phòng","hl":[]},{"t":"有房间","ph":"yǒu fángjiān","vph":"dẩu pháng chiên","vi":"có phòng","hl":["有"]},{"t":"今天还有房间吗？","ph":"Jīntiān hái yǒu fángjiān ma?","vph":"Chin thiên hái dẩu pháng chiên ma?","vi":"Hôm nay còn phòng không?","hl":["有"],"tokens":["今天","还","有","房间","吗"]}]}],"formula":[{"k":"S","t":"Chủ ngữ / Nơi chốn"},{"k":"P","t":"有"},{"k":"O","t":"Danh từ"},{"k":"Q","t":"(吗)"}],"points":["有 + danh từ diễn tả sở hữu: ai có cái gì (\"我有护照\" - tôi có hộ chiếu).","Nơi chốn/thời gian + 有 + vật diễn tả sự tồn tại: ở đâu có gì (\"这儿有超市\" - ở đây có siêu thị).","Phủ định của 有 luôn là 没有 (hoặc nói gọn 没), không bao giờ là 不有.","Muốn hỏi thì thêm 吗 cuối câu hoặc dùng 有没有 (\"你有没有时间？\")."],"mistakes":[{"wrong":"我不有时间。","right":"我没有时间。","why":"有 chỉ phủ định bằng 没, nói 不有 là sai."},{"wrong":"在这儿有银行吗？","right":"这儿有银行吗？","why":"Câu tồn tại bắt đầu thẳng bằng nơi chốn, không dịch chữ \"ở\" thành 在 ở đầu câu."}],"compare":"Giống tiếng Việt: 有 = \"có\", đứng trước danh từ, và \"nơi chốn + có + vật\" cũng cùng trật tự (这儿有… = ở đây có…). Khác: \"không có\" là 没有 chứ không phải 不有, và đầu câu không cần chữ \"ở\" (在).","tip":"有 chỉ \"chơi\" với 没: không có = 没有, đừng bao giờ ghép 不有.","how":["Đặt 有 trước danh từ 护照 → 有护照, rồi thêm chủ ngữ 我 lên đầu → 我有护照。","Ghép 有 + 时间 → 有时间 (có thời gian = rảnh), thêm 你明天 phía trước và 吗 cuối câu để hỏi → 你明天有时间吗？","Ghép 有 + 房间 → 有房间, thêm 还 (còn) trước 有, 今天 lên đầu và 吗 cuối câu → 今天还有房间吗？"],"dialog":[{"who":"A","t":"请问，附近有银行吗？","ph":"Qǐngwèn, fùjìn yǒu yínháng ma?","vph":"Chỉnh uân, phu chin dẩu dín háng ma?","vi":"Xin hỏi, gần đây có ngân hàng không?","hl":["有"]},{"who":"B","t":"有，前面就有一个。","ph":"Yǒu, qiánmiàn jiù yǒu yí ge.","vph":"Dẩu, chiến miên chiêu dẩu í cưa.","vi":"Có, ngay phía trước có một cái.","hl":["有"]},{"who":"A","t":"那儿可以换钱吗？","ph":"Nàr kěyǐ huàn qián ma?","vph":"Na khửa ỷ hoan chién ma?","vi":"Ở đó đổi tiền được không?","hl":[]},{"who":"B","t":"可以，不过今天人很多。","ph":"Kěyǐ, búguò jīntiān rén hěn duō.","vph":"Khửa ỷ, pú cua chin thiên rấn hẩn tua.","vi":"Được, nhưng hôm nay đông người lắm.","hl":[]}],"more":[{"t":"你有微信吗？","ph":"Nǐ yǒu Wēixìn ma?","vph":"Nỉ dẩu Uây xin ma?","vi":"Bạn có WeChat không?","hl":["有"],"tokens":["你","有","微信","吗"]},{"t":"我没有零钱。","ph":"Wǒ méiyǒu língqián.","vph":"Ủa mấy dẩu lính chién.","vi":"Tôi không có tiền lẻ.","hl":["有"],"tokens":["我","没有","零钱"]},{"t":"我有一个哥哥。","ph":"Wǒ yǒu yí ge gēge.","vph":"Ủa dẩu í cưa cưa cưa.","vi":"Tôi có một anh trai.","hl":["有"],"tokens":["我","有","一","个","哥哥"]},{"t":"这儿有洗手间吗？","ph":"Zhèr yǒu xǐshǒujiān ma?","vph":"Chưa dẩu xỉ sẩu chiên ma?","vi":"Ở đây có nhà vệ sinh không?","hl":["有"],"tokens":["这儿","有","洗手间","吗"]},{"t":"酒店附近有超市吗？","ph":"Jiǔdiàn fùjìn yǒu chāoshì ma?","vph":"Chiểu tiên phu chin dẩu chao sư ma?","vi":"Gần khách sạn có siêu thị không?","hl":["有"],"tokens":["酒店","附近","有","超市","吗"]},{"t":"你们有没有大一点的房间？","ph":"Nǐmen yǒu méiyǒu dà yìdiǎn de fángjiān?","vph":"Nỉ mân dẩu mấy dẩu ta i tiẻn tơ pháng chiên?","vi":"Các bạn có phòng rộng hơn một chút không?","hl":["有没有"],"tokens":["你们","有","没有","大","一点","的","房间"]}]},{"id":3,"vi":"là","note":"是 nối hai danh từ theo mẫu A 是 B (A là B). Phủ định là 不是; không dùng 是 trước tính từ (nói 我很忙, không nói 我是忙).","pivot":{"t":"是","ph":"shì","vph":"sư"},"branches":[{"steps":[{"t":"学生","ph":"xuésheng","vph":"xuế sâng","vi":"học sinh","hl":[]},{"t":"是学生","ph":"shì xuésheng","vph":"sư xuế sâng","vi":"là học sinh","hl":["是"]},{"t":"我是学生。","ph":"Wǒ shì xuésheng.","vph":"Ủa sư xuế sâng.","vi":"Tôi là học sinh.","hl":["是"],"tokens":["我","是","学生"]}]},{"steps":[{"t":"朋友","ph":"péngyou","vph":"pấng dâu","vi":"bạn bè","hl":[]},{"t":"是朋友","ph":"shì péngyou","vph":"sư pấng dâu","vi":"là bạn","hl":["是"]},{"t":"我们是朋友。","ph":"Wǒmen shì péngyou.","vph":"Ủa mân sư pấng dâu.","vi":"Chúng ta là bạn.","hl":["是"],"tokens":["我们","是","朋友"]}]},{"steps":[{"t":"中国人","ph":"Zhōngguórén","vph":"Chung cúa rấn","vi":"người Trung Quốc","hl":[]},{"t":"是中国人","ph":"shì Zhōngguórén","vph":"sư Chung cúa rấn","vi":"là người Trung Quốc","hl":["是"]},{"t":"你是中国人吗？","ph":"Nǐ shì Zhōngguórén ma?","vph":"Nỉ sư Chung cúa rấn ma?","vi":"Bạn là người Trung Quốc phải không?","hl":["是"],"tokens":["你","是","中国人","吗"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"是"},{"k":"O","t":"Danh từ"},{"k":"Q","t":"(吗)"}],"points":["是 nối hai danh từ theo mẫu A 是 B (\"我是学生\" - tôi là học sinh).","Không dùng 是 trước tính từ; với tính từ thì dùng 很 (\"我很忙\", không nói \"我是忙\").","Phủ định của 是 luôn là 不是 (đọc bú shì), không dùng 没是.","Muốn hỏi thì thêm 吗 cuối câu, hoặc dùng 是不是 (\"你是不是老师？\")."],"mistakes":[{"wrong":"我是很忙。","right":"我很忙。","why":"Trước tính từ không dùng 是; tiếng Việt nói \"tôi bận\" thì tiếng Trung cũng chỉ cần 很 + tính từ."},{"wrong":"我没是老师。","right":"我不是老师。","why":"是 luôn phủ định bằng 不, không dùng 没."}],"compare":"Giống tiếng Việt: 是 = \"là\", mẫu A 是 B cùng trật tự (我是学生 = tôi là học sinh). Khác: tiếng Việt đôi khi nói \"tôi là bận\" cho nhấn mạnh, còn tiếng Trung tuyệt đối không đặt 是 trước tính từ.","tip":"是 chỉ làm \"dấu bằng\" giữa hai danh từ: danh từ = danh từ; gặp tính từ thì đổi 是 thành 很.","how":["Đặt 是 trước danh từ 学生 → 是学生, rồi thêm chủ ngữ 我 lên đầu → 我是学生。","Ghép 是 + 朋友 → 是朋友, rồi đặt chủ ngữ số nhiều 我们 lên đầu → 我们是朋友。","Ghép 是 + 中国人 → 是中国人, thêm 你 phía trước và 吗 cuối câu để hỏi → 你是中国人吗？"],"dialog":[{"who":"A","t":"你好，你是新同事吗？","ph":"Nǐ hǎo, nǐ shì xīn tóngshì ma?","vph":"Nỉ hảo, nỉ sư xin thúng sư ma?","vi":"Chào bạn, bạn là đồng nghiệp mới phải không?","hl":["是"]},{"who":"B","t":"是，我是越南人。","ph":"Shì, wǒ shì Yuènánrén.","vph":"Sư, ủa sư Duê nán rấn.","vi":"Vâng, tôi là người Việt Nam.","hl":["是"]},{"who":"A","t":"欢迎！我是你的经理。","ph":"Huānyíng! Wǒ shì nǐ de jīnglǐ.","vph":"Hoan dính! Ủa sư nỉ tơ chinh lỉ.","vi":"Chào mừng! Tôi là quản lý của bạn.","hl":["是"]}],"more":[{"t":"他是老师。","ph":"Tā shì lǎoshī.","vph":"Tha sư lảo sư.","vi":"Anh ấy là giáo viên.","hl":["是"],"tokens":["他","是","老师"]},{"t":"今天是星期五。","ph":"Jīntiān shì xīngqīwǔ.","vph":"Chin thiên sư xinh chi ủ.","vi":"Hôm nay là thứ Sáu.","hl":["是"],"tokens":["今天","是","星期五"]},{"t":"我不是日本人。","ph":"Wǒ bú shì Rìběnrén.","vph":"Ủa pú sư Rư pẩn rấn.","vi":"Tôi không phải người Nhật.","hl":["是"],"tokens":["我","不","是","日本人"]},{"t":"这是我的护照。","ph":"Zhè shì wǒ de hùzhào.","vph":"Chưa sư ủa tơ hu chao.","vi":"Đây là hộ chiếu của tôi.","hl":["是"],"tokens":["这","是","我","的","护照"]},{"t":"那是你的行李吗？","ph":"Nà shì nǐ de xíngli ma?","vph":"Na sư nỉ tơ xính lỉ ma?","vi":"Kia là hành lý của bạn phải không?","hl":["是"],"tokens":["那","是","你","的","行李","吗"]},{"t":"她是我们公司的经理。","ph":"Tā shì wǒmen gōngsī de jīnglǐ.","vph":"Tha sư ủa mân cung xư tơ chinh lỉ.","vi":"Chị ấy là quản lý công ty chúng tôi.","hl":["是"],"tokens":["她","是","我们","公司","的","经理"]}]},{"id":4,"vi":"muốn","note":"想 + động từ diễn tả mong muốn (muốn làm gì). 要 mạnh hơn, mang nghĩa \"muốn/cần\" và cũng dùng với danh từ (我要这个 - tôi lấy cái này).","pivot":{"t":"想","ph":"xiǎng","vph":"xẻng"},"branches":[{"steps":[{"t":"吃","ph":"chī","vph":"chư","vi":"ăn","hl":[]},{"t":"想吃","ph":"xiǎng chī","vph":"xẻng chư","vi":"muốn ăn","hl":["想"]},{"t":"我想吃饭。","ph":"Wǒ xiǎng chī fàn.","vph":"Ủa xẻng chư phan.","vi":"Tôi muốn ăn cơm.","hl":["想"],"tokens":["我","想","吃饭"]}]},{"steps":[{"t":"喝","ph":"hē","vph":"khưa","vi":"uống","hl":[]},{"t":"想喝","ph":"xiǎng hē","vph":"xẻng khưa","vi":"muốn uống","hl":["想"]},{"t":"我想喝咖啡。","ph":"Wǒ xiǎng hē kāfēi.","vph":"Ủa xẻng khưa kha phây.","vi":"Tôi muốn uống cà phê.","hl":["想"],"tokens":["我","想","喝","咖啡"]}]},{"steps":[{"t":"回家","ph":"huí jiā","vph":"khuấy chia","vi":"về nhà","hl":[]},{"t":"想回家","ph":"xiǎng huí jiā","vph":"xẻng khuấy chia","vi":"muốn về nhà","hl":["想"]},{"t":"我现在想回家。","ph":"Wǒ xiànzài xiǎng huí jiā.","vph":"Ủa xiên chai xẻng khuấy chia.","vi":"Bây giờ tôi muốn về nhà.","hl":["想"],"tokens":["我","现在","想","回家"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"X","t":"(Thời gian)"},{"k":"P","t":"想"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["想 + động từ diễn tả mong muốn: muốn làm gì (\"我想喝咖啡\" - tôi muốn uống cà phê).","Từ chỉ thời gian đặt sau chủ ngữ, trước 想 (\"我现在想回家\").","Phủ định là 不想 (không muốn), không dùng 没想.","想 + người hoặc nơi chốn còn có nghĩa \"nhớ\" (\"我想你\" - anh nhớ em, \"我想家\" - tôi nhớ nhà)."],"mistakes":[{"wrong":"我想咖啡。","right":"我想喝咖啡。","why":"想 (muốn) cần một động từ phía sau; muốn gọi món thì dùng 要: 我要咖啡."},{"wrong":"我没想去。","right":"我不想去。","why":"\"Không muốn\" là 不想; 没想 nghĩa là \"đã không nghĩ tới\"."}],"compare":"Giống tiếng Việt: 想 đứng trước động từ như \"muốn\" (想吃 = muốn ăn). Khác: tiếng Việt nói \"muốn cà phê\" được, còn tiếng Trung phải nói 想喝咖啡 hoặc 要咖啡.","tip":"想 vốn là \"nghĩ\": muốn làm gì thì phải \"nghĩ tới\" một hành động — nên 想 luôn kéo theo một động từ.","how":["Đặt 想 trước động từ 吃 → 想吃, rồi thêm chủ ngữ 我 phía trước và tân ngữ 饭 phía sau → 我想吃饭。","Ghép 想 + 喝 → 想喝, rồi đặt 我 lên đầu và thứ muốn uống 咖啡 ở cuối → 我想喝咖啡。","Ghép 想 + 回家 → 想回家, rồi thêm 我 và từ chỉ thời gian 现在 trước 想 → 我现在想回家。"],"dialog":[{"who":"A","t":"晚上你想去哪儿？","ph":"Wǎnshang nǐ xiǎng qù nǎr?","vph":"Oản sang nỉ xẻng chuy nả?","vi":"Tối nay bạn muốn đi đâu?","hl":["想"]},{"who":"B","t":"我想去吃火锅。","ph":"Wǒ xiǎng qù chī huǒguō.","vph":"Ủa xẻng chuy chư hủa cua.","vi":"Tôi muốn đi ăn lẩu.","hl":["想"]},{"who":"A","t":"好啊，我也想去！","ph":"Hǎo a, wǒ yě xiǎng qù!","vph":"Hảo a, ủa dể xẻng chuy!","vi":"Hay đấy, tôi cũng muốn đi!","hl":["想"]}],"more":[{"t":"我想睡觉。","ph":"Wǒ xiǎng shuìjiào.","vph":"Ủa xẻng suây cheo.","vi":"Tôi muốn đi ngủ.","hl":["想"],"tokens":["我","想","睡觉"]},{"t":"你想喝什么？","ph":"Nǐ xiǎng hē shénme?","vph":"Nỉ xẻng khưa sấn mơ?","vi":"Bạn muốn uống gì?","hl":["想"],"tokens":["你","想","喝","什么"]},{"t":"我不想等了。","ph":"Wǒ bù xiǎng děng le.","vph":"Ủa pu xẻng tẩng lơ.","vi":"Tôi không muốn đợi nữa.","hl":["想"],"tokens":["我","不","想","等","了"]},{"t":"我想买一张地图。","ph":"Wǒ xiǎng mǎi yì zhāng dìtú.","vph":"Ủa xẻng mải i chang ti thú.","vi":"Tôi muốn mua một tấm bản đồ.","hl":["想"],"tokens":["我","想","买","一","张","地图"]},{"t":"我们想去长城看看。","ph":"Wǒmen xiǎng qù Chángchéng kànkan.","vph":"Ủa mân xẻng chuy Cháng chấng khan khan.","vi":"Chúng tôi muốn đi Vạn Lý Trường Thành xem thử.","hl":["想"],"tokens":["我们","想","去","长城","看看"]},{"t":"明年我想去中国工作。","ph":"Míngnián wǒ xiǎng qù Zhōngguó gōngzuò.","vph":"Mính niên ủa xẻng chuy Chung cúa cung chua.","vi":"Năm sau tôi muốn sang Trung Quốc làm việc.","hl":["想"],"tokens":["明年","我","想","去","中国","工作"]}]},{"id":5,"vi":"thích","note":"喜欢 đứng trước danh từ hoặc động từ (thích cái gì / thích làm gì). Thêm 很 để nhấn mạnh: 很喜欢 (rất thích); phủ định là 不喜欢.","pivot":{"t":"喜欢","ph":"xǐhuan","vph":"xỉ hoan"},"branches":[{"steps":[{"t":"喝茶","ph":"hē chá","vph":"khưa chá","vi":"uống trà","hl":[]},{"t":"喜欢喝茶","ph":"xǐhuan hē chá","vph":"xỉ hoan khưa chá","vi":"thích uống trà","hl":["喜欢"]},{"t":"我喜欢喝茶。","ph":"Wǒ xǐhuan hē chá.","vph":"Ủa xỉ hoan khưa chá.","vi":"Tôi thích uống trà.","hl":["喜欢"],"tokens":["我","喜欢","喝","茶"]}]},{"steps":[{"t":"中国菜","ph":"Zhōngguó cài","vph":"Chung cúa chai","vi":"món ăn Trung Quốc","hl":[]},{"t":"喜欢中国菜","ph":"xǐhuan Zhōngguó cài","vph":"xỉ hoan Chung cúa chai","vi":"thích món Trung Quốc","hl":["喜欢"]},{"t":"你喜欢中国菜吗？","ph":"Nǐ xǐhuan Zhōngguó cài ma?","vph":"Nỉ xỉ hoan Chung cúa chai ma?","vi":"Bạn có thích món Trung Quốc không?","hl":["喜欢"],"tokens":["你","喜欢","中国菜","吗"]}]},{"steps":[{"t":"旅游","ph":"lǚyóu","vph":"lủy dấu","vi":"du lịch","hl":[]},{"t":"喜欢旅游","ph":"xǐhuan lǚyóu","vph":"xỉ hoan lủy dấu","vi":"thích du lịch","hl":["喜欢"]},{"t":"我很喜欢旅游。","ph":"Wǒ hěn xǐhuan lǚyóu.","vph":"Ủa hẩn xỉ hoan lủy dấu.","vi":"Tôi rất thích du lịch.","hl":["喜欢"],"tokens":["我","很","喜欢","旅游"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"A","t":"(很 / 非常)"},{"k":"P","t":"喜欢"},{"k":"O","t":"Danh từ / Động từ"}],"points":["喜欢 đứng trước thứ được thích, có thể là danh từ hoặc động từ (\"喜欢猫\" - thích mèo, \"喜欢旅游\" - thích du lịch).","Từ chỉ mức độ như 很, 非常, 最 đặt ngay trước 喜欢 (\"我很喜欢\").","Phủ định là 不喜欢; sở thích là trạng thái nên không dùng 没.","Hỏi bằng 喜欢…吗？ hoặc 喜不喜欢…？ (\"你喜不喜欢喝茶？\")."],"mistakes":[{"wrong":"我喜欢中国菜很多。","right":"我很喜欢中国菜。","why":"\"Thích … lắm\" không dịch thành 很多 ở cuối câu; mức độ 很/非常 phải đứng trước 喜欢."},{"wrong":"我没喜欢吃辣。","right":"我不喜欢吃辣。","why":"Sở thích là trạng thái, phủ định bằng 不 chứ không dùng 没."}],"compare":"Giống tiếng Việt: 喜欢 đứng trước thứ mình thích (喜欢旅游 = thích du lịch). Khác: tiếng Việt hay đặt \"lắm/quá\" cuối câu, còn tiếng Trung 很/非常 phải đứng ngay trước 喜欢.","tip":"Nhớ thứ tự \"mức độ → 喜欢 → thứ được thích\": 很喜欢 + X, giống \"rất thích X\".","how":["Đặt 喜欢 trước cụm động từ 喝茶 → 喜欢喝茶, rồi thêm chủ ngữ 我 lên đầu → 我喜欢喝茶。","Ghép 喜欢 + danh từ 中国菜 → 喜欢中国菜, thêm 你 ở đầu và 吗 ở cuối để hỏi → 你喜欢中国菜吗？","Ghép 喜欢 + 旅游 → 喜欢旅游, rồi thêm 很 trước 喜欢 để nhấn mạnh và chủ ngữ 我 lên đầu → 我很喜欢旅游。"],"dialog":[{"who":"A","t":"你喜欢北京吗？","ph":"Nǐ xǐhuan Běijīng ma?","vph":"Nỉ xỉ hoan Pẩy chinh ma?","vi":"Bạn có thích Bắc Kinh không?","hl":["喜欢"]},{"who":"B","t":"很喜欢！我最喜欢这儿的烤鸭。","ph":"Hěn xǐhuan! Wǒ zuì xǐhuan zhèr de kǎoyā.","vph":"Hẩn xỉ hoan! Ủa chuây xỉ hoan chưa tơ khảo da.","vi":"Thích lắm! Tôi thích nhất là vịt quay ở đây.","hl":["喜欢"]},{"who":"A","t":"我也喜欢，明天一起去吃吧。","ph":"Wǒ yě xǐhuan, míngtiān yìqǐ qù chī ba.","vph":"Ủa dể xỉ hoan, mính thiên i chỉ chuy chư pa.","vi":"Tôi cũng thích, mai cùng đi ăn nhé.","hl":["喜欢"]}],"more":[{"t":"我喜欢猫。","ph":"Wǒ xǐhuan māo.","vph":"Ủa xỉ hoan mao.","vi":"Tôi thích mèo.","hl":["喜欢"],"tokens":["我","喜欢","猫"]},{"t":"你喜欢什么颜色？","ph":"Nǐ xǐhuan shénme yánsè?","vph":"Nỉ xỉ hoan sấn mơ dán xưa?","vi":"Bạn thích màu gì?","hl":["喜欢"],"tokens":["你","喜欢","什么","颜色"]},{"t":"她不喜欢吃辣。","ph":"Tā bù xǐhuan chī là.","vph":"Tha pu xỉ hoan chư la.","vi":"Cô ấy không thích ăn cay.","hl":["喜欢"],"tokens":["她","不","喜欢","吃","辣"]},{"t":"我非常喜欢这个城市。","ph":"Wǒ fēicháng xǐhuan zhège chéngshì.","vph":"Ủa phây cháng xỉ hoan chưa cưa chấng sư.","vi":"Tôi cực kỳ thích thành phố này.","hl":["喜欢"],"tokens":["我","非常","喜欢","这个","城市"]},{"t":"我爸爸喜欢早上跑步。","ph":"Wǒ bàba xǐhuan zǎoshang pǎobù.","vph":"Ủa pa pa xỉ hoan chảo sang pảo pu.","vi":"Bố tôi thích chạy bộ buổi sáng.","hl":["喜欢"],"tokens":["我","爸爸","喜欢","早上","跑步"]},{"t":"周末你喜欢在家看电影吗？","ph":"Zhōumò nǐ xǐhuan zài jiā kàn diànyǐng ma?","vph":"Châu mua nỉ xỉ hoan chai chia khan tiên dỉnh ma?","vi":"Cuối tuần bạn có thích ở nhà xem phim không?","hl":["喜欢"],"tokens":["周末","你","喜欢","在","家","看","电影","吗"]}]},{"id":6,"vi":"cần","note":"需要 + danh từ/động từ diễn tả nhu cầu (cần cái gì / cần làm gì). Phủ định là 不需要 hoặc 不用 (không cần).","pivot":{"t":"需要","ph":"xūyào","vph":"xuy dao"},"branches":[{"steps":[{"t":"换钱","ph":"huàn qián","vph":"hoan chién","vi":"đổi tiền","hl":[]},{"t":"需要换钱","ph":"xūyào huàn qián","vph":"xuy dao hoan chién","vi":"cần đổi tiền","hl":["需要"]},{"t":"我需要换钱。","ph":"Wǒ xūyào huàn qián.","vph":"Ủa xuy dao hoan chién.","vi":"Tôi cần đổi tiền.","hl":["需要"],"tokens":["我","需要","换钱"]}]},{"steps":[{"t":"帮助","ph":"bāngzhù","vph":"pang chu","vi":"sự giúp đỡ","hl":[]},{"t":"需要帮助","ph":"xūyào bāngzhù","vph":"xuy dao pang chu","vi":"cần giúp đỡ","hl":["需要"]},{"t":"你需要帮助吗？","ph":"Nǐ xūyào bāngzhù ma?","vph":"Nỉ xuy dao pang chu ma?","vi":"Bạn có cần giúp không?","hl":["需要"],"tokens":["你","需要","帮助","吗"]}]},{"steps":[{"t":"休息","ph":"xiūxi","vph":"xiêu xi","vi":"nghỉ ngơi","hl":[]},{"t":"需要休息","ph":"xūyào xiūxi","vph":"xuy dao xiêu xi","vi":"cần nghỉ ngơi","hl":["需要"]},{"t":"你需要休息一下。","ph":"Nǐ xūyào xiūxi yíxià.","vph":"Nỉ xuy dao xiêu xi í xa.","vi":"Bạn cần nghỉ ngơi một chút.","hl":["需要"],"tokens":["你","需要","休息","一下"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"需要"},{"k":"O","t":"Danh từ / Động từ"},{"k":"Q","t":"(吗)"}],"points":["需要 + danh từ hoặc động từ diễn tả nhu cầu: cần cái gì, cần làm gì (\"需要帮助\", \"需要换钱\").","Phủ định là 不需要; trong giao tiếp người ta hay nói gọn 不用 hoặc 不用了 (không cần đâu).","Hỏi bằng 需要…吗？ hoặc 需要不需要…？ (\"你需要发票吗？\").","需要 + thời gian/tiền còn dùng để nói \"mất bao lâu, tốn bao nhiêu\" (\"需要两个小时\" - mất hai tiếng)."],"mistakes":[{"wrong":"我没需要帮助。","right":"我不需要帮助。","why":"Nhu cầu hiện tại phủ định bằng 不 (hoặc nói gọn 不用了), không dùng 没."}],"compare":"Giống tiếng Việt: 需要 = \"cần\", đứng trước danh từ hoặc động từ (需要换钱 = cần đổi tiền). Khác: khi từ chối lời mời giúp, người Trung hay nói gọn 不用了 thay vì 不需要.","tip":"Nhân viên hỏi 需要…吗？ — cần thì gật \"需要\", không cần thì cười \"不用了，谢谢！\".","how":["Đặt 需要 trước cụm động từ 换钱 → 需要换钱, rồi thêm chủ ngữ 我 lên đầu → 我需要换钱。","Ghép 需要 + danh từ 帮助 → 需要帮助, thêm 你 ở đầu và 吗 ở cuối để hỏi → 你需要帮助吗？","Ghép 需要 + 休息 → 需要休息, thêm 你 phía trước và 一下 (một chút) sau động từ → 你需要休息一下。"],"dialog":[{"who":"A","t":"您好，需要帮忙吗？","ph":"Nín hǎo, xūyào bāngmáng ma?","vph":"Nín hảo, xuy dao pang máng ma?","vi":"Chào anh, anh có cần giúp gì không?","hl":["需要"]},{"who":"B","t":"我需要一张地铁地图。","ph":"Wǒ xūyào yì zhāng dìtiě dìtú.","vph":"Ủa xuy dao i chang ti thiể ti thú.","vi":"Tôi cần một tấm bản đồ tàu điện ngầm.","hl":["需要"]},{"who":"A","t":"给您。还需要别的吗？","ph":"Gěi nín. Hái xūyào bié de ma?","vph":"Cẩy nín. Hái xuy dao piế tơ ma?","vi":"Của anh đây. Anh còn cần gì nữa không?","hl":["需要"]},{"who":"B","t":"不用了，谢谢！","ph":"Búyòng le, xièxie!","vph":"Pú dung lơ, xiê xiê!","vi":"Không cần nữa, cảm ơn!","hl":[]}],"more":[{"t":"你需要发票吗？","ph":"Nǐ xūyào fāpiào ma?","vph":"Nỉ xuy dao pha peo ma?","vi":"Bạn có cần hóa đơn không?","hl":["需要"],"tokens":["你","需要","发票","吗"]},{"t":"我需要一杯水。","ph":"Wǒ xūyào yì bēi shuǐ.","vph":"Ủa xuy dao i pây suẩy.","vi":"Tôi cần một cốc nước.","hl":["需要"],"tokens":["我","需要","一","杯","水"]},{"t":"我们不需要导游。","ph":"Wǒmen bù xūyào dǎoyóu.","vph":"Ủa mân pu xuy dao tảo dấu.","vi":"Chúng tôi không cần hướng dẫn viên.","hl":["需要"],"tokens":["我们","不","需要","导游"]},{"t":"办签证需要什么？","ph":"Bàn qiānzhèng xūyào shénme?","vph":"Pan chiên châng xuy dao sấn mơ?","vi":"Làm visa cần những gì?","hl":["需要"],"tokens":["办","签证","需要","什么"]},{"t":"去机场需要多长时间？","ph":"Qù jīchǎng xūyào duō cháng shíjiān?","vph":"Chuy chi chảng xuy dao tua cháng sứ chiên?","vi":"Đi sân bay mất bao lâu?","hl":["需要"],"tokens":["去","机场","需要","多","长","时间"]},{"t":"这个药需要每天吃两次。","ph":"Zhège yào xūyào měi tiān chī liǎng cì.","vph":"Chưa cưa dao xuy dao mẩy thiên chư lẻng chư.","vi":"Thuốc này cần uống mỗi ngày hai lần.","hl":["需要"],"tokens":["这个","药","需要","每","天","吃","两","次"]}]},{"id":7,"vi":"có thể","note":"可以 + động từ diễn tả sự cho phép hoặc khả năng (có thể làm gì, được không). 能 thiên về năng lực/điều kiện, 会 là kỹ năng học được (biết làm).","pivot":{"t":"可以","ph":"kěyǐ","vph":"khửa ỷ"},"branches":[{"steps":[{"t":"进来","ph":"jìnlái","vph":"chin lái","vi":"vào","hl":[]},{"t":"可以进来","ph":"kěyǐ jìnlái","vph":"khửa ỷ chin lái","vi":"có thể vào","hl":["可以"]},{"t":"我可以进来吗？","ph":"Wǒ kěyǐ jìnlái ma?","vph":"Ủa khửa ỷ chin lái ma?","vi":"Tôi vào được không?","hl":["可以"],"tokens":["我","可以","进来","吗"]}]},{"steps":[{"t":"拍照","ph":"pāizhào","vph":"pai chao","vi":"chụp ảnh","hl":[]},{"t":"可以拍照","ph":"kěyǐ pāizhào","vph":"khửa ỷ pai chao","vi":"có thể chụp ảnh","hl":["可以"]},{"t":"这里可以拍照吗？","ph":"Zhèlǐ kěyǐ pāizhào ma?","vph":"Chưa lỉ khửa ỷ pai chao ma?","vi":"Ở đây có được chụp ảnh không?","hl":["可以"],"tokens":["这里","可以","拍照","吗"]}]},{"steps":[{"t":"刷卡","ph":"shuākǎ","vph":"soa khả","vi":"quẹt thẻ","hl":[]},{"t":"可以刷卡","ph":"kěyǐ shuākǎ","vph":"khửa ỷ soa khả","vi":"có thể quẹt thẻ","hl":["可以"]},{"t":"请问可以刷卡吗？","ph":"Qǐngwèn kěyǐ shuākǎ ma?","vph":"Chỉnh uân khửa ỷ soa khả ma?","vi":"Xin hỏi có quẹt thẻ được không?","hl":["可以"],"tokens":["请问","可以","刷卡","吗"]}]}],"formula":[{"k":"S","t":"Chủ ngữ / Nơi chốn"},{"k":"P","t":"可以"},{"k":"V","t":"Động từ"},{"k":"Q","t":"(吗)"}],"points":["可以 + động từ diễn tả sự cho phép hoặc khả năng: được làm gì, có thể làm gì (\"可以拍照\").","Xin phép theo mẫu: (Chủ ngữ) + 可以 + động từ + 吗？; trả lời đồng ý là 可以, từ chối là 不行 hoặc 不可以.","Biển cấm thường dùng 不可以 / 不能 + động từ (\"这里不可以抽烟\").","Kỹ năng học được (biết bơi, biết nói tiếng Trung) dùng 会, không dùng 可以."],"mistakes":[{"wrong":"我可以游泳，我学过。","right":"我会游泳，我学过。","why":"\"Biết bơi\" là kỹ năng học được nên dùng 会; 可以 chỉ sự cho phép hoặc điều kiện."},{"wrong":"可以我坐这儿吗？","right":"我可以坐这儿吗？","why":"Chủ ngữ đứng trước 可以, không đưa 可以 lên đầu câu."}],"compare":"Giống tiếng Việt: 可以 + động từ như \"có thể/được\" (可以拍照 = được chụp ảnh). Khác: tiếng Việt hay để \"được không\" cuối câu, còn tiếng Trung đặt 可以 trước động từ rồi thêm 吗 ở cuối.","tip":"Công thức xin phép vạn năng: 我可以 + việc muốn làm + 吗？ — đi đâu cũng dùng được.","how":["Đặt 可以 trước 进来 → 可以进来, thêm 我 lên đầu và 吗 cuối câu để xin phép → 我可以进来吗？","Ghép 可以 + 拍照 → 可以拍照, đặt nơi chốn 这里 lên đầu và 吗 cuối câu → 这里可以拍照吗？","Ghép 可以 + 刷卡 → 可以刷卡, mở đầu lịch sự bằng 请问 và kết bằng 吗 → 请问可以刷卡吗？"],"dialog":[{"who":"A","t":"服务员，可以点菜吗？","ph":"Fúwùyuán, kěyǐ diǎn cài ma?","vph":"Phú u doén, khửa ỷ tiẻn chai ma?","vi":"Phục vụ ơi, gọi món được chưa?","hl":["可以"]},{"who":"B","t":"可以，这是菜单。","ph":"Kěyǐ, zhè shì càidān.","vph":"Khửa ỷ, chưa sư chai tan.","vi":"Được ạ, đây là thực đơn.","hl":["可以"]},{"who":"A","t":"我可以用微信付钱吗？","ph":"Wǒ kěyǐ yòng Wēixìn fù qián ma?","vph":"Ủa khửa ỷ dung Uây xin phu chién ma?","vi":"Tôi trả bằng WeChat được không?","hl":["可以"]},{"who":"B","t":"当然可以。","ph":"Dāngrán kěyǐ.","vph":"Tang rán khửa ỷ.","vi":"Tất nhiên là được.","hl":["可以"]}],"more":[{"t":"我可以试试吗？","ph":"Wǒ kěyǐ shìshi ma?","vph":"Ủa khửa ỷ sư sư ma?","vi":"Tôi thử được không?","hl":["可以"],"tokens":["我","可以","试试","吗"]},{"t":"我们可以坐这儿吗？","ph":"Wǒmen kěyǐ zuò zhèr ma?","vph":"Ủa mân khửa ỷ chua chưa ma?","vi":"Chúng tôi ngồi đây được không?","hl":["可以"],"tokens":["我们","可以","坐","这儿","吗"]},{"t":"这里不可以抽烟。","ph":"Zhèlǐ bù kěyǐ chōuyān.","vph":"Chưa lỉ pu khửa ỷ châu dan.","vi":"Ở đây không được hút thuốc.","hl":["可以"],"tokens":["这里","不","可以","抽烟"]},{"t":"你可以说慢一点吗？","ph":"Nǐ kěyǐ shuō màn yìdiǎn ma?","vph":"Nỉ khửa ỷ sua man i tiẻn ma?","vi":"Bạn nói chậm một chút được không?","hl":["可以"],"tokens":["你","可以","说","慢","一点","吗"]},{"t":"行李可以放在前台吗？","ph":"Xíngli kěyǐ fàng zài qiántái ma?","vph":"Xính lỉ khửa ỷ phang chai chiến thái ma?","vi":"Hành lý có thể gửi ở quầy lễ tân không?","hl":["可以"],"tokens":["行李","可以","放","在","前台","吗"]},{"t":"明天早上可以晚一点退房吗？","ph":"Míngtiān zǎoshang kěyǐ wǎn yìdiǎn tuìfáng ma?","vph":"Mính thiên chảo sang khửa ỷ oản i tiẻn thuây pháng ma?","vi":"Sáng mai có thể trả phòng muộn một chút không?","hl":["可以"],"tokens":["明天","早上","可以","晚","一点","退房","吗"]}]},{"id":8,"vi":"đi","note":"去 + địa điểm (đi đâu). Muốn nói đi bằng gì thì đặt phương tiện trước: 坐/骑 + phương tiện + 去 (坐地铁去 - đi bằng tàu điện ngầm).","pivot":{"t":"去","ph":"qù","vph":"chuy"},"branches":[{"steps":[{"t":"北京","ph":"Běijīng","vph":"Pẩy chinh","vi":"Bắc Kinh","hl":[]},{"t":"去北京","ph":"qù Běijīng","vph":"chuy Pẩy chinh","vi":"đi Bắc Kinh","hl":["去"]},{"t":"我明天去北京。","ph":"Wǒ míngtiān qù Běijīng.","vph":"Ủa mính thiên chuy Pẩy chinh.","vi":"Ngày mai tôi đi Bắc Kinh.","hl":["去"],"tokens":["我","明天","去","北京"]}]},{"steps":[{"t":"机场","ph":"jīchǎng","vph":"chi chảng","vi":"sân bay","hl":[]},{"t":"去机场","ph":"qù jīchǎng","vph":"chuy chi chảng","vi":"đi sân bay","hl":["去"]},{"t":"我要去机场。","ph":"Wǒ yào qù jīchǎng.","vph":"Ủa dao chuy chi chảng.","vi":"Tôi muốn đi sân bay.","hl":["去"],"tokens":["我","要","去","机场"]}]},{"steps":[{"t":"地铁","ph":"dìtiě","vph":"ti thiể","vi":"tàu điện ngầm","hl":[]},{"t":"坐地铁去","ph":"zuò dìtiě qù","vph":"chua ti thiể chuy","vi":"đi bằng tàu điện ngầm","hl":["去"]},{"t":"我们坐地铁去吧。","ph":"Wǒmen zuò dìtiě qù ba.","vph":"Ủa mân chua ti thiể chuy pa.","vi":"Chúng ta đi bằng tàu điện ngầm nhé.","hl":["去"],"tokens":["我们","坐","地铁","去","吧"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"X","t":"(Thời gian)"},{"k":"X","t":"(坐 + Phương tiện)"},{"k":"P","t":"去"},{"k":"O","t":"Nơi chốn"}],"points":["去 + nơi chốn trực tiếp, không cần thêm \"đến\" (\"去北京\" - đi Bắc Kinh).","Thời gian đặt sau chủ ngữ, trước 去 (\"我明天去北京\").","Phương tiện đặt trước 去: 坐/骑 + phương tiện + 去 (\"坐地铁去\" - đi bằng tàu điện ngầm).","Đi đâu để làm gì: 去 + nơi chốn + động từ (\"去超市买东西\" - đi siêu thị mua đồ)."],"mistakes":[{"wrong":"我去北京明天。","right":"我明天去北京。","why":"Thời gian phải đứng trước động từ, không để cuối câu như \"Tôi đi Bắc Kinh ngày mai\"."},{"wrong":"我去北京坐飞机。","right":"我坐飞机去北京。","why":"Phương tiện đứng trước 去 (坐飞机去…), ngược với tiếng Việt \"đi … bằng máy bay\"."}],"compare":"Giống tiếng Việt: 去 + địa điểm như \"đi + nơi\" (去北京 = đi Bắc Kinh). Khác: thời gian và phương tiện phải đứng TRƯỚC 去, không để cuối câu như tiếng Việt.","tip":"Thứ tự vàng: Ai – Khi nào – Bằng gì – 去 – Đâu: 我明天坐飞机去北京。","how":["Đặt 去 trước địa danh 北京 → 去北京, rồi thêm 我 và thời gian 明天 trước 去 → 我明天去北京。","Ghép 去 + 机场 → 去机场, thêm 要 (muốn/sắp) trước 去 và chủ ngữ 我 lên đầu → 我要去机场。","Từ 地铁, thêm 坐 phía trước và 去 phía sau → 坐地铁去 (đi bằng tàu điện ngầm), rồi thêm 我们 ở đầu và 吧 ở cuối để rủ → 我们坐地铁去吧。"],"dialog":[{"who":"A","t":"你周末去哪儿？","ph":"Nǐ zhōumò qù nǎr?","vph":"Nỉ châu mua chuy nả?","vi":"Cuối tuần bạn đi đâu?","hl":["去"]},{"who":"B","t":"我去上海看朋友。","ph":"Wǒ qù Shànghǎi kàn péngyou.","vph":"Ủa chuy Sang hải khan pấng dâu.","vi":"Tôi đi Thượng Hải thăm bạn.","hl":["去"]},{"who":"A","t":"你怎么去？","ph":"Nǐ zěnme qù?","vph":"Nỉ chẩn mơ chuy?","vi":"Bạn đi bằng gì?","hl":["去"]},{"who":"B","t":"坐高铁去，很快。","ph":"Zuò gāotiě qù, hěn kuài.","vph":"Chua cao thiể chuy, hẩn khoai.","vi":"Đi tàu cao tốc, nhanh lắm.","hl":["去"]}],"more":[{"t":"他去银行了。","ph":"Tā qù yínháng le.","vph":"Tha chuy dín háng lơ.","vi":"Anh ấy đi ngân hàng rồi.","hl":["去"],"tokens":["他","去","银行","了"]},{"t":"我们去吃饭吧。","ph":"Wǒmen qù chī fàn ba.","vph":"Ủa mân chuy chư phan pa.","vi":"Chúng ta đi ăn cơm nhé.","hl":["去"],"tokens":["我们","去","吃饭","吧"]},{"t":"你去过越南吗？","ph":"Nǐ qù guo Yuènán ma?","vph":"Nỉ chuy cua Duê nán ma?","vi":"Bạn đã từng đến Việt Nam chưa?","hl":["去"],"tokens":["你","去","过","越南","吗"]},{"t":"我下午打车去酒店。","ph":"Wǒ xiàwǔ dǎchē qù jiǔdiàn.","vph":"Ủa xa ủ tả chưa chuy chiểu tiên.","vi":"Chiều nay tôi đi taxi về khách sạn.","hl":["去"],"tokens":["我","下午","打车","去","酒店"]},{"t":"我想去超市买水果。","ph":"Wǒ xiǎng qù chāoshì mǎi shuǐguǒ.","vph":"Ủa xẻng chuy chao sư mải suẩy của.","vi":"Tôi muốn đi siêu thị mua trái cây.","hl":["去"],"tokens":["我","想","去","超市","买","水果"]},{"t":"明天我们一起坐火车去西安。","ph":"Míngtiān wǒmen yìqǐ zuò huǒchē qù Xī'ān.","vph":"Mính thiên ủa mân i chỉ chua hủa chưa chuy Xi an.","vi":"Ngày mai chúng ta cùng đi tàu hỏa đến Tây An.","hl":["去"],"tokens":["明天","我们","一起","坐","火车","去","西安"]}]},{"id":9,"vi":"ở đâu","note":"Mẫu câu: X + 在哪儿？(X ở đâu?). 哪儿 là cách nói miền Bắc; miền Nam và Đài Loan hay nói 在哪里 (zài nǎlǐ).","pivot":{"t":"在哪儿","ph":"zài nǎr","vph":"chai nả"},"branches":[{"steps":[{"t":"厕所","ph":"cèsuǒ","vph":"xưa sủa","vi":"nhà vệ sinh","hl":[]},{"t":"厕所在哪儿","ph":"cèsuǒ zài nǎr","vph":"xưa sủa chai nả","vi":"nhà vệ sinh ở đâu","hl":["在哪儿"]},{"t":"请问厕所在哪儿？","ph":"Qǐngwèn cèsuǒ zài nǎr?","vph":"Chỉnh uân xưa sủa chai nả?","vi":"Xin hỏi nhà vệ sinh ở đâu?","hl":["在哪儿"],"tokens":["请问","厕所","在","哪儿"]}]},{"steps":[{"t":"地铁站","ph":"dìtiězhàn","vph":"ti thiể chan","vi":"ga tàu điện ngầm","hl":[]},{"t":"地铁站在哪儿","ph":"dìtiězhàn zài nǎr","vph":"ti thiể chan chai nả","vi":"ga tàu điện ngầm ở đâu","hl":["在哪儿"]},{"t":"最近的地铁站在哪儿？","ph":"Zuì jìn de dìtiězhàn zài nǎr?","vph":"Chuây chin tơ ti thiể chan chai nả?","vi":"Ga tàu điện ngầm gần nhất ở đâu?","hl":["在哪儿"],"tokens":["最","近","的","地铁站","在","哪儿"]}]},{"steps":[{"t":"现在","ph":"xiànzài","vph":"xiên chai","vi":"bây giờ","hl":[]},{"t":"现在在哪儿","ph":"xiànzài zài nǎr","vph":"xiên chai chai nả","vi":"bây giờ ở đâu","hl":["在哪儿"]},{"t":"你现在在哪儿？","ph":"Nǐ xiànzài zài nǎr?","vph":"Nỉ xiên chai chai nả?","vi":"Bây giờ bạn đang ở đâu?","hl":["在哪儿"],"tokens":["你","现在","在","哪儿"]}]}],"formula":[{"k":"X","t":"(请问)"},{"k":"S","t":"Người / Đồ vật / Địa điểm"},{"k":"P","t":"在哪儿"}],"points":["Mẫu câu: X + 在哪儿？ để hỏi người/vật/nơi nào đó ở đâu (\"厕所在哪儿？\").","在哪儿 nằm cuối câu, không đảo lên đầu và không cần thêm 是.","Câu đã có 哪儿 là câu hỏi rồi, không thêm 吗 ở cuối.","Hỏi làm gì ở đâu thì 在哪儿 đứng trước động từ (\"你在哪儿工作？\" - bạn làm việc ở đâu)."],"mistakes":[{"wrong":"在哪儿是厕所？","right":"厕所在哪儿？","why":"Không đảo \"ở đâu\" lên đầu như tiếng Anh và không thêm 是; chỉ cần X + 在哪儿."},{"wrong":"厕所在哪儿吗？","right":"厕所在哪儿？","why":"Đã có từ để hỏi 哪儿 thì không thêm 吗 nữa."}],"compare":"Giống hệt tiếng Việt: \"Nhà vệ sinh ở đâu?\" = 厕所在哪儿？, 在 = ở, 哪儿 = đâu, cùng trật tự. Khác: hỏi \"làm gì ở đâu\" thì 在哪儿 đứng TRƯỚC động từ (在哪儿买 = mua ở đâu), ngược với tiếng Việt.","tip":"Dịch từng chữ là đúng: \"… ở đâu?\" = …在哪儿？ — chỉ cần nhớ đừng thêm 吗.","how":["Đặt 在哪儿 ngay sau 厕所 → 厕所在哪儿, rồi mở đầu lịch sự bằng 请问 → 请问厕所在哪儿？","Ghép 地铁站 + 在哪儿 → 地铁站在哪儿, rồi thêm 最近的 (gần nhất) trước danh từ → 最近的地铁站在哪儿？","Ghép 现在 + 在哪儿 → 现在在哪儿, rồi đặt chủ ngữ 你 lên đầu → 你现在在哪儿？"],"dialog":[{"who":"A","t":"不好意思，出租车站在哪儿？","ph":"Bù hǎoyìsi, chūzūchē zhàn zài nǎr?","vph":"Pu hảo i xư, chu chu chưa chan chai nả?","vi":"Xin lỗi, bến taxi ở đâu ạ?","hl":["在哪儿"]},{"who":"B","t":"在一号门外面。","ph":"Zài yī hào mén wàimian.","vph":"Chai i hao mấn oai miên.","vi":"Ở bên ngoài cổng số 1.","hl":[]},{"who":"A","t":"换钱的地方在哪儿？","ph":"Huàn qián de dìfang zài nǎr?","vph":"Hoan chién tơ ti phang chai nả?","vi":"Chỗ đổi tiền ở đâu?","hl":["在哪儿"]},{"who":"B","t":"就在二楼。","ph":"Jiù zài èr lóu.","vph":"Chiêu chai ơ lấu.","vi":"Ngay trên tầng hai.","hl":[]}],"more":[{"t":"出口在哪儿？","ph":"Chūkǒu zài nǎr?","vph":"Chu khẩu chai nả?","vi":"Lối ra ở đâu?","hl":["在哪儿"],"tokens":["出口","在","哪儿"]},{"t":"你家在哪儿？","ph":"Nǐ jiā zài nǎr?","vph":"Nỉ chia chai nả?","vi":"Nhà bạn ở đâu?","hl":["在哪儿"],"tokens":["你","家","在","哪儿"]},{"t":"我的手机在哪儿？","ph":"Wǒ de shǒujī zài nǎr?","vph":"Ủa tơ sẩu chi chai nả?","vi":"Điện thoại của tôi đâu rồi?","hl":["在哪儿"],"tokens":["我","的","手机","在","哪儿"]},{"t":"你在哪儿工作？","ph":"Nǐ zài nǎr gōngzuò?","vph":"Nỉ chai nả cung chua?","vi":"Bạn làm việc ở đâu?","hl":["在哪儿"],"tokens":["你","在","哪儿","工作"]},{"t":"请问售票处在哪儿？","ph":"Qǐngwèn shòupiàochù zài nǎr?","vph":"Chỉnh uân sâu peo chu chai nả?","vi":"Xin hỏi quầy bán vé ở đâu?","hl":["在哪儿"],"tokens":["请问","售票处","在","哪儿"]},{"t":"这个周末的音乐会在哪儿举行？","ph":"Zhège zhōumò de yīnyuèhuì zài nǎr jǔxíng?","vph":"Chưa cưa châu mua tơ in duê huây chai nả chủy xính?","vi":"Buổi hòa nhạc cuối tuần này tổ chức ở đâu?","hl":["在哪儿"],"tokens":["这个","周末","的","音乐会","在","哪儿","举行"]}]},{"id":10,"vi":"bao nhiêu","note":"多少 hỏi số lượng hoặc giá (多少钱 - bao nhiêu tiền). Với số nhỏ (thường dưới 10) dùng 几 + lượng từ: 几个人 (mấy người).","pivot":{"t":"多少","ph":"duōshao","vph":"tua sảo"},"branches":[{"steps":[{"t":"钱","ph":"qián","vph":"chién","vi":"tiền","hl":[]},{"t":"多少钱","ph":"duōshao qián","vph":"tua sảo chién","vi":"bao nhiêu tiền","hl":["多少"]},{"t":"这个多少钱？","ph":"Zhège duōshao qián?","vph":"Chưa cưa tua sảo chién?","vi":"Cái này bao nhiêu tiền?","hl":["多少"],"tokens":["这个","多少","钱"]}]},{"steps":[{"t":"人","ph":"rén","vph":"rấn","vi":"người","hl":[]},{"t":"多少人","ph":"duōshao rén","vph":"tua sảo rấn","vi":"bao nhiêu người","hl":["多少"]},{"t":"你们有多少人？","ph":"Nǐmen yǒu duōshao rén?","vph":"Nỉ mân dẩu tua sảo rấn?","vi":"Các bạn có bao nhiêu người?","hl":["多少"],"tokens":["你们","有","多少","人"]}]},{"steps":[{"t":"一斤","ph":"yì jīn","vph":"i chin","vi":"một cân (nửa ký)","hl":[]},{"t":"一斤多少钱","ph":"yì jīn duōshao qián","vph":"i chin tua sảo chién","vi":"bao nhiêu tiền một cân","hl":["多少"]},{"t":"苹果一斤多少钱？","ph":"Píngguǒ yì jīn duōshao qián?","vph":"Pính của i chin tua sảo chién?","vi":"Táo bao nhiêu tiền một cân?","hl":["多少"],"tokens":["苹果","一","斤","多少","钱"]}]}],"formula":[{"k":"S","t":"Món hàng / Chủ ngữ"},{"k":"X","t":"(Đơn vị)"},{"k":"P","t":"多少"},{"k":"O","t":"Danh từ (钱, 人…)"}],"points":["多少 + danh từ để hỏi số lượng hoặc giá, không cần lượng từ ở giữa (\"多少钱\", \"多少人\").","Hỏi giá theo mẫu: Món hàng + (đơn vị) + 多少钱？ (\"苹果一斤多少钱？\").","Với số nhỏ (thường dưới 10) người ta hay dùng 几 + lượng từ (\"几个人\" - mấy người).","Câu đã có 多少 là câu hỏi, không thêm 吗 và không cần 是 khi hỏi giá."],"mistakes":[{"wrong":"这个是多少钱吗？","right":"这个多少钱？","why":"Hỏi giá không cần 是, và đã có 多少 thì không thêm 吗."},{"wrong":"多少钱这个？","right":"这个多少钱？","why":"Món hàng đứng trước, 多少钱 ở cuối, giống \"Cái này bao nhiêu tiền?\"."}],"compare":"Giống tiếng Việt: 这个多少钱 = \"cái này bao nhiêu tiền\", cùng trật tự. Khác: tiếng Việt hay nói \"bao nhiêu một cân\", còn tiếng Trung đưa đơn vị lên trước: 一斤多少钱.","tip":"多少 = 多 (nhiều) + 少 (ít): hỏi \"nhiều hay ít?\" chính là hỏi \"bao nhiêu?\".","how":["Đặt 多少 trước 钱 → 多少钱, rồi thêm 这个 lên đầu để hỏi giá → 这个多少钱？","Ghép 多少 + 人 → 多少人, rồi thêm 你们有 phía trước → 你们有多少人？","Đặt đơn vị 一斤 trước 多少钱 → 一斤多少钱, rồi thêm tên hàng 苹果 lên đầu → 苹果一斤多少钱？"],"dialog":[{"who":"A","t":"老板，这件衣服多少钱？","ph":"Lǎobǎn, zhè jiàn yīfu duōshao qián?","vph":"Lảo pản, chưa chiên i phu tua sảo chién?","vi":"Ông chủ ơi, cái áo này bao nhiêu tiền?","hl":["多少"]},{"who":"B","t":"两百块。你要多少件？","ph":"Liǎng bǎi kuài. Nǐ yào duōshao jiàn?","vph":"Lẻng pải khoai. Nỉ dao tua sảo chiên?","vi":"Hai trăm tệ. Anh lấy bao nhiêu cái?","hl":["多少"]},{"who":"A","t":"我要三件，便宜一点吧？","ph":"Wǒ yào sān jiàn, piányi yìdiǎn ba?","vph":"Ủa dao xan chiên, pién i i tiẻn pa?","vi":"Tôi lấy ba cái, bớt chút nhé?","hl":[]},{"who":"B","t":"好，一共五百块。","ph":"Hǎo, yígòng wǔbǎi kuài.","vph":"Hảo, í cung ủ pải khoai.","vi":"Được, tổng cộng năm trăm tệ.","hl":[]}],"more":[{"t":"一共多少钱？","ph":"Yígòng duōshao qián?","vph":"Í cung tua sảo chién?","vi":"Tổng cộng bao nhiêu tiền?","hl":["多少"],"tokens":["一共","多少","钱"]},{"t":"这本书多少钱？","ph":"Zhè běn shū duōshao qián?","vph":"Chưa pẩn su tua sảo chién?","vi":"Quyển sách này bao nhiêu tiền?","hl":["多少"],"tokens":["这","本","书","多少","钱"]},{"t":"房费一晚多少钱？","ph":"Fángfèi yì wǎn duōshao qián?","vph":"Pháng phây i oản tua sảo chién?","vi":"Tiền phòng một đêm bao nhiêu?","hl":["多少"],"tokens":["房费","一","晚","多少","钱"]},{"t":"你的电话号码是多少？","ph":"Nǐ de diànhuà hàomǎ shì duōshao?","vph":"Nỉ tơ tiên hoa hao mả sư tua sảo?","vi":"Số điện thoại của bạn là bao nhiêu?","hl":["多少"],"tokens":["你","的","电话","号码","是","多少"]},{"t":"你们公司有多少员工？","ph":"Nǐmen gōngsī yǒu duōshao yuángōng?","vph":"Nỉ mân cung xư dẩu tua sảo doén cung?","vi":"Công ty các bạn có bao nhiêu nhân viên?","hl":["多少"],"tokens":["你们","公司","有","多少","员工"]},{"t":"坐出租车到机场要多少钱？","ph":"Zuò chūzūchē dào jīchǎng yào duōshao qián?","vph":"Chua chu chu chưa tao chi chảng dao tua sảo chién?","vi":"Đi taxi ra sân bay hết bao nhiêu tiền?","hl":["多少"],"tokens":["坐","出租车","到","机场","要","多少","钱"]}]},{"id":11,"vi":"cái gì","note":"什么 đứng đúng vị trí của thứ được hỏi, không đảo lên đầu câu như tiếng Anh (你吃什么 - bạn ăn gì). Có thể đứng trước danh từ: 什么名字 (tên gì).","pivot":{"t":"什么","ph":"shénme","vph":"sấn mơ"},"branches":[{"steps":[{"t":"是","ph":"shì","vph":"sư","vi":"là","hl":[]},{"t":"是什么","ph":"shì shénme","vph":"sư sấn mơ","vi":"là gì","hl":["什么"]},{"t":"这是什么？","ph":"Zhè shì shénme?","vph":"Chưa sư sấn mơ?","vi":"Đây là cái gì?","hl":["什么"],"tokens":["这","是","什么"]}]},{"steps":[{"t":"吃","ph":"chī","vph":"chư","vi":"ăn","hl":[]},{"t":"吃什么","ph":"chī shénme","vph":"chư sấn mơ","vi":"ăn gì","hl":["什么"]},{"t":"你想吃什么？","ph":"Nǐ xiǎng chī shénme?","vph":"Nỉ xẻng chư sấn mơ?","vi":"Bạn muốn ăn gì?","hl":["什么"],"tokens":["你","想","吃","什么"]}]},{"steps":[{"t":"名字","ph":"míngzi","vph":"mính chư","vi":"tên","hl":[]},{"t":"什么名字","ph":"shénme míngzi","vph":"sấn mơ mính chư","vi":"tên gì","hl":["什么"]},{"t":"你叫什么名字？","ph":"Nǐ jiào shénme míngzi?","vph":"Nỉ cheo sấn mơ mính chư?","vi":"Bạn tên là gì?","hl":["什么"],"tokens":["你","叫","什么","名字"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"什么"},{"k":"O","t":"(Danh từ)"}],"points":["什么 đứng đúng vị trí của thứ được hỏi, không đảo lên đầu câu (\"你吃什么？\" - bạn ăn gì?).","什么 + danh từ nghĩa là \"… gì\": 什么名字 (tên gì), 什么颜色 (màu gì).","Câu đã có 什么 là câu hỏi, không thêm 吗 ở cuối.","Trả lời chỉ cần thay 什么 bằng thông tin, giữ nguyên phần còn lại (\"你吃什么？\" → \"我吃面条。\")."],"mistakes":[{"wrong":"你想吃什么吗？","right":"你想吃什么？","why":"Đã có 什么 là câu hỏi rồi, thêm 吗 là thừa và sai."},{"wrong":"什么你想喝？","right":"你想喝什么？","why":"什么 không đảo lên đầu như \"What\" tiếng Anh; giữ đúng chỗ như chữ \"gì\" trong tiếng Việt."}],"compare":"Giống tiếng Việt: 什么 đứng đúng chỗ chữ \"gì\" (你吃什么 = bạn ăn gì). Khác: \"tên gì, màu gì\" thì 什么 lại đứng TRƯỚC danh từ (什么名字), ngược với tiếng Việt.","tip":"Hỏi \"gì\" thì thay đúng chữ \"gì\" bằng 什么, câu giữ nguyên — chỉ nhớ: \"… gì\" đi với danh từ thì lật 什么 lên trước.","how":["Đặt 什么 sau động từ 是 → 是什么, rồi thêm 这 lên đầu → 这是什么？","Ghép 吃 + 什么 → 吃什么, rồi thêm 你想 phía trước → 你想吃什么？","Đặt 什么 trước danh từ 名字 → 什么名字, rồi thêm 你叫 phía trước → 你叫什么名字？"],"dialog":[{"who":"A","t":"你在看什么？","ph":"Nǐ zài kàn shénme?","vph":"Nỉ chai khan sấn mơ?","vi":"Bạn đang xem gì vậy?","hl":["什么"]},{"who":"B","t":"菜单。这个菜叫什么？","ph":"Càidān. Zhège cài jiào shénme?","vph":"Chai tan. Chưa cưa chai cheo sấn mơ?","vi":"Thực đơn. Món này tên là gì?","hl":["什么"]},{"who":"A","t":"宫保鸡丁，很好吃。","ph":"Gōngbǎo jīdīng, hěn hǎochī.","vph":"Cung pảo chi tinh, hẩn hảo chư.","vi":"Gà xào Cung Bảo, ngon lắm.","hl":[]}],"more":[{"t":"那是什么？","ph":"Nà shì shénme?","vph":"Na sư sấn mơ?","vi":"Kia là cái gì?","hl":["什么"],"tokens":["那","是","什么"]},{"t":"你说什么？","ph":"Nǐ shuō shénme?","vph":"Nỉ sua sấn mơ?","vi":"Bạn nói gì cơ?","hl":["什么"],"tokens":["你","说","什么"]},{"t":"你买了什么？","ph":"Nǐ mǎi le shénme?","vph":"Nỉ mải lơ sấn mơ?","vi":"Bạn đã mua gì?","hl":["什么"],"tokens":["你","买","了","什么"]},{"t":"你做什么工作？","ph":"Nǐ zuò shénme gōngzuò?","vph":"Nỉ chua sấn mơ cung chua?","vi":"Bạn làm nghề gì?","hl":["什么"],"tokens":["你","做","什么","工作"]},{"t":"今天是什么日子？","ph":"Jīntiān shì shénme rìzi?","vph":"Chin thiên sư sấn mơ rư chư?","vi":"Hôm nay là ngày gì vậy?","hl":["什么"],"tokens":["今天","是","什么","日子"]},{"t":"你周末喜欢做什么？","ph":"Nǐ zhōumò xǐhuan zuò shénme?","vph":"Nỉ châu mua xỉ hoan chua sấn mơ?","vi":"Cuối tuần bạn thích làm gì?","hl":["什么"],"tokens":["你","周末","喜欢","做","什么"]}]},{"id":12,"vi":"ai","note":"谁 đứng ở vị trí của người được hỏi (他是谁 - anh ấy là ai; 谁去 - ai đi). 谁的 + danh từ = của ai. Có thể đọc shéi hoặc shuí.","pivot":{"t":"谁","ph":"shéi","vph":"suấy"},"branches":[{"steps":[{"t":"是","ph":"shì","vph":"sư","vi":"là","hl":[]},{"t":"是谁","ph":"shì shéi","vph":"sư suấy","vi":"là ai","hl":["谁"]},{"t":"他是谁？","ph":"Tā shì shéi?","vph":"Tha sư suấy?","vi":"Anh ấy là ai?","hl":["谁"],"tokens":["他","是","谁"]}]},{"steps":[{"t":"找","ph":"zhǎo","vph":"chảo","vi":"tìm","hl":[]},{"t":"找谁","ph":"zhǎo shéi","vph":"chảo suấy","vi":"tìm ai","hl":["谁"]},{"t":"请问您找谁？","ph":"Qǐngwèn nín zhǎo shéi?","vph":"Chỉnh uân nín chảo suấy?","vi":"Xin hỏi ông/bà tìm ai?","hl":["谁"],"tokens":["请问","您","找","谁"]}]},{"steps":[{"t":"包","ph":"bāo","vph":"pao","vi":"cái túi","hl":[]},{"t":"谁的包","ph":"shéi de bāo","vph":"suấy tơ pao","vi":"túi của ai","hl":["谁"]},{"t":"这是谁的包？","ph":"Zhè shì shéi de bāo?","vph":"Chưa sư suấy tơ pao?","vi":"Đây là túi của ai?","hl":["谁"],"tokens":["这","是","谁","的","包"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"谁"},{"k":"O","t":"(的 + Danh từ)"}],"points":["谁 thay đúng vào vị trí của người được hỏi, làm chủ ngữ hoặc tân ngữ đều được (\"谁去？\" - ai đi?, \"你找谁？\" - bạn tìm ai?).","\"Của ai\" là 谁的 + danh từ, 谁的 đứng TRƯỚC đồ vật (\"谁的包\").","Câu đã có 谁 là câu hỏi, không thêm 吗.","谁 có hai cách đọc: shéi (khẩu ngữ, phổ biến) và shuí."],"mistakes":[{"wrong":"这是包谁的？","right":"这是谁的包？","why":"Tiếng Việt nói \"túi của ai\", nhưng tiếng Trung 谁的 phải đứng trước danh từ."},{"wrong":"他是谁吗？","right":"他是谁？","why":"Đã có 谁 thì không thêm 吗."}],"compare":"Giống tiếng Việt: 谁 nằm đúng chỗ chữ \"ai\" (他是谁 = anh ấy là ai, 谁去 = ai đi). Khác: \"túi của ai\" phải đảo thành 谁的包 (của ai + túi).","tip":"\"Của ai\" lật ngược thành \"ai của\": 谁的 + đồ vật — người luôn đứng trước, đồ vật theo sau.","how":["Đặt 谁 sau động từ 是 → 是谁, rồi thêm chủ ngữ 他 lên đầu → 他是谁？","Ghép 找 + 谁 → 找谁, thêm 您 phía trước và 请问 mở đầu cho lịch sự → 请问您找谁？","Ghép 谁 + 的 + 包 → 谁的包 (túi của ai), rồi thêm 这是 lên đầu → 这是谁的包？"],"dialog":[{"who":"A","t":"门口那个人是谁？","ph":"Ménkǒu nàge rén shì shéi?","vph":"Mấn khẩu na cưa rấn sư suấy?","vi":"Người đứng ở cửa kia là ai vậy?","hl":["谁"]},{"who":"B","t":"他是新来的经理。","ph":"Tā shì xīn lái de jīnglǐ.","vph":"Tha sư xin lái tơ chinh lỉ.","vi":"Anh ấy là quản lý mới đến.","hl":[]},{"who":"A","t":"这把伞是谁的？","ph":"Zhè bǎ sǎn shì shéi de?","vph":"Chưa pá xản sư suấy tơ?","vi":"Cái ô này của ai?","hl":["谁"]},{"who":"B","t":"好像是他的。","ph":"Hǎoxiàng shì tā de.","vph":"Hảo xeng sư tha tơ.","vi":"Hình như là của anh ấy.","hl":[]}],"more":[{"t":"谁来了？","ph":"Shéi lái le?","vph":"Suấy lái lơ?","vi":"Ai đến vậy?","hl":["谁"],"tokens":["谁","来","了"]},{"t":"你在等谁？","ph":"Nǐ zài děng shéi?","vph":"Nỉ chai tẩng suấy?","vi":"Bạn đang đợi ai?","hl":["谁"],"tokens":["你","在","等","谁"]},{"t":"谁会说英语？","ph":"Shéi huì shuō Yīngyǔ?","vph":"Suấy huây sua Inh dủy?","vi":"Ai biết nói tiếng Anh?","hl":["谁"],"tokens":["谁","会","说","英语"]},{"t":"你和谁一起去？","ph":"Nǐ hé shéi yìqǐ qù?","vph":"Nỉ khứa suấy i chỉ chuy?","vi":"Bạn đi cùng với ai?","hl":["谁"],"tokens":["你","和","谁","一起","去"]},{"t":"那辆车是谁的？","ph":"Nà liàng chē shì shéi de?","vph":"Na leng chưa sư suấy tơ?","vi":"Chiếc xe kia là của ai?","hl":["谁"],"tokens":["那","辆","车","是","谁","的"]},{"t":"昨天谁给你打电话了？","ph":"Zuótiān shéi gěi nǐ dǎ diànhuà le?","vph":"Chúa thiên suấy cấy nỉ tả tiên hoa lơ?","vi":"Hôm qua ai gọi điện cho bạn vậy?","hl":["谁"],"tokens":["昨天","谁","给","你","打","电话","了"]}]},{"id":13,"vi":"khi nào","note":"什么时候 đặt sau chủ ngữ, trước động từ (你什么时候来 - khi nào bạn đến). Hỏi giờ cụ thể dùng 几点 (mấy giờ).","pivot":{"t":"什么时候","ph":"shénme shíhou","vph":"sấn mơ sứ hâu"},"branches":[{"steps":[{"t":"来","ph":"lái","vph":"lái","vi":"đến","hl":[]},{"t":"什么时候来","ph":"shénme shíhou lái","vph":"sấn mơ sứ hâu lái","vi":"khi nào đến","hl":["什么时候"]},{"t":"你什么时候来？","ph":"Nǐ shénme shíhou lái?","vph":"Nỉ sấn mơ sứ hâu lái?","vi":"Khi nào bạn đến?","hl":["什么时候"],"tokens":["你","什么时候","来"]}]},{"steps":[{"t":"出发","ph":"chūfā","vph":"chu pha","vi":"xuất phát","hl":[]},{"t":"什么时候出发","ph":"shénme shíhou chūfā","vph":"sấn mơ sứ hâu chu pha","vi":"khi nào xuất phát","hl":["什么时候"]},{"t":"我们什么时候出发？","ph":"Wǒmen shénme shíhou chūfā?","vph":"Ủa mân sấn mơ sứ hâu chu pha?","vi":"Khi nào chúng ta xuất phát?","hl":["什么时候"],"tokens":["我们","什么时候","出发"]}]},{"steps":[{"t":"开门","ph":"kāimén","vph":"khai mấn","vi":"mở cửa","hl":[]},{"t":"几点开门","ph":"jǐ diǎn kāimén","vph":"chí tiẻn khai mấn","vi":"mấy giờ mở cửa","hl":["几点"]},{"t":"博物馆几点开门？","ph":"Bówùguǎn jǐ diǎn kāimén?","vph":"Púa u quản chí tiẻn khai mấn?","vi":"Bảo tàng mấy giờ mở cửa?","hl":["几点"],"tokens":["博物馆","几点","开门"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"什么时候"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["什么时候 (khi nào) đặt sau chủ ngữ, trước động từ (\"你什么时候来？\").","Không đặt 什么时候 ở cuối câu như kiểu \"đến khi nào\".","Hỏi giờ cụ thể thì dùng 几点 (mấy giờ), cũng đặt trước động từ (\"几点开门？\").","Câu đã có 什么时候 không thêm 吗; trả lời chỉ cần thay thời gian vào đúng chỗ đó (\"我明天来\")."],"mistakes":[{"wrong":"你来什么时候？","right":"你什么时候来？","why":"Tiếng Việt có thể nói \"bạn đến khi nào\", nhưng tiếng Trung từ hỏi thời gian phải đứng trước động từ."},{"wrong":"你什么时候来吗？","right":"你什么时候来？","why":"Đã có từ để hỏi 什么时候 thì không thêm 吗."}],"compare":"Giống tiếng Việt \"Khi nào bạn đến?\" — từ hỏi đứng trước hành động. Khác: tiếng Việt có thể đẩy \"khi nào\" xuống cuối (\"đến khi nào\"), còn tiếng Trung 什么时候 luôn đứng sau chủ ngữ, trước động từ.","tip":"什么时候 = 什么 (gì) + 时候 (lúc) = \"lúc nào\"; và \"lúc nào\" luôn chen ngay trước hành động.","how":["Đặt 什么时候 trước động từ 来 → 什么时候来, rồi thêm chủ ngữ 你 lên đầu → 你什么时候来？","Ghép 什么时候 + 出发 → 什么时候出发, rồi đặt chủ ngữ 我们 lên đầu → 我们什么时候出发？","Hỏi giờ cụ thể thì dùng 几点: ghép 几点 + 开门 → 几点开门, rồi thêm 博物馆 lên đầu → 博物馆几点开门？"],"dialog":[{"who":"A","t":"你什么时候回国？","ph":"Nǐ shénme shíhou huí guó?","vph":"Nỉ sấn mơ sứ hâu khuấy cúa?","vi":"Khi nào bạn về nước?","hl":["什么时候"]},{"who":"B","t":"下个星期五。你什么时候有空？","ph":"Xià ge xīngqīwǔ. Nǐ shénme shíhou yǒu kòng?","vph":"Xa cưa xinh chi ủ. Nỉ sấn mơ sứ hâu dẩu khung?","vi":"Thứ Sáu tuần sau. Khi nào bạn rảnh?","hl":["什么时候"]},{"who":"A","t":"明天晚上，我请你吃饭！","ph":"Míngtiān wǎnshang, wǒ qǐng nǐ chī fàn!","vph":"Mính thiên oản sang, ủa chỉnh nỉ chư phan!","vi":"Tối mai, mình mời bạn ăn cơm!","hl":[]}],"more":[{"t":"他什么时候回来？","ph":"Tā shénme shíhou huílai?","vph":"Tha sấn mơ sứ hâu khuấy lai?","vi":"Khi nào anh ấy quay lại?","hl":["什么时候"],"tokens":["他","什么时候","回来"]},{"t":"你什么时候下班？","ph":"Nǐ shénme shíhou xiàbān?","vph":"Nỉ sấn mơ sứ hâu xa pan?","vi":"Khi nào bạn tan làm?","hl":["什么时候"],"tokens":["你","什么时候","下班"]},{"t":"我们什么时候吃饭？","ph":"Wǒmen shénme shíhou chī fàn?","vph":"Ủa mân sấn mơ sứ hâu chư phan?","vi":"Khi nào chúng ta ăn cơm?","hl":["什么时候"],"tokens":["我们","什么时候","吃饭"]},{"t":"你是什么时候到的？","ph":"Nǐ shì shénme shíhou dào de?","vph":"Nỉ sư sấn mơ sứ hâu tao tơ?","vi":"Bạn đến lúc nào vậy?","hl":["什么时候"],"tokens":["你","是","什么时候","到","的"]},{"t":"下一班火车什么时候出发？","ph":"Xià yì bān huǒchē shénme shíhou chūfā?","vph":"Xa i pan hủa chưa sấn mơ sứ hâu chu pha?","vi":"Chuyến tàu tiếp theo khi nào khởi hành?","hl":["什么时候"],"tokens":["下","一","班","火车","什么时候","出发"]},{"t":"你什么时候开始学中文的？","ph":"Nǐ shénme shíhou kāishǐ xué Zhōngwén de?","vph":"Nỉ sấn mơ sứ hâu khai sử xuế Chung uấn tơ?","vi":"Bạn bắt đầu học tiếng Trung từ khi nào?","hl":["什么时候"],"tokens":["你","什么时候","开始","学","中文","的"]}]},{"id":14,"vi":"tại sao / vì","note":"为什么 hỏi lý do, đặt sau chủ ngữ (你为什么… - tại sao bạn…). Trả lời bằng 因为 (vì), thường đi cặp 因为…所以… (vì… nên…).","pivot":{"t":"为什么","ph":"wèishénme","vph":"uây sấn mơ"},"branches":[{"steps":[{"t":"迟到","ph":"chídào","vph":"chứ tao","vi":"đến muộn","hl":[]},{"t":"为什么迟到","ph":"wèishénme chídào","vph":"uây sấn mơ chứ tao","vi":"tại sao đến muộn","hl":["为什么"]},{"t":"你为什么迟到？","ph":"Nǐ wèishénme chídào?","vph":"Nỉ uây sấn mơ chứ tao?","vi":"Tại sao bạn đến muộn?","hl":["为什么"],"tokens":["你","为什么","迟到"]}]},{"steps":[{"t":"学中文","ph":"xué Zhōngwén","vph":"xuế Chung uấn","vi":"học tiếng Trung","hl":[]},{"t":"为什么学中文","ph":"wèishénme xué Zhōngwén","vph":"uây sấn mơ xuế Chung uấn","vi":"tại sao học tiếng Trung","hl":["为什么"]},{"t":"你为什么学中文？","ph":"Nǐ wèishénme xué Zhōngwén?","vph":"Nỉ uây sấn mơ xuế Chung uấn?","vi":"Tại sao bạn học tiếng Trung?","hl":["为什么"],"tokens":["你","为什么","学","中文"]}]},{"steps":[{"t":"堵车","ph":"dǔchē","vph":"tủ chưa","vi":"kẹt xe","hl":[]},{"t":"因为堵车","ph":"yīnwèi dǔchē","vph":"in uây tủ chưa","vi":"vì kẹt xe","hl":["因为"]},{"t":"因为堵车，所以我迟到了。","ph":"Yīnwèi dǔchē, suǒyǐ wǒ chídào le.","vph":"In uây tủ chưa, súa ỷ ủa chứ tao lơ.","vi":"Vì kẹt xe nên tôi đến muộn.","hl":["因为"],"tokens":["因为","堵车","所以","我","迟到","了"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"为什么"},{"k":"V","t":"Động từ / Tính từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["为什么 (tại sao) thường đặt sau chủ ngữ, trước động từ (\"你为什么迟到？\").","Trả lời lý do bằng 因为 (vì), thường đi cặp 因为…所以… (vì… nên…).","所以 đứng đầu vế sau, trước chủ ngữ của vế đó (\"因为下雨，所以我们不去\").","为什么不 + động từ còn dùng để gợi ý nhẹ nhàng (\"为什么不打车？\" - sao không đi taxi?)."],"mistakes":[{"wrong":"你迟到为什么？","right":"你为什么迟到？","why":"为什么 phải đứng trước động từ, không để cuối câu như \"bạn đến muộn tại sao\"."},{"wrong":"因为下雨，我们所以不去。","right":"因为下雨，所以我们不去。","why":"所以 đứng đầu vế sau, trước chủ ngữ, giống chữ \"nên\" trong tiếng Việt."}],"compare":"Giống tiếng Việt: 为什么 = \"tại sao\", 因为…所以… = \"vì… nên…\". Khác: tiếng Việt hay đặt \"tại sao\" đầu câu, còn tiếng Trung thường để 为什么 sau chủ ngữ (你为什么…).","tip":"Hỏi 为什么 \"uây sấn mơ\" — đáp 因为 \"in uây\": hai từ cùng có chữ 为 (uây) như một cặp hỏi – đáp.","how":["Đặt 为什么 trước động từ 迟到 → 为什么迟到, rồi thêm chủ ngữ 你 lên đầu → 你为什么迟到？","Ghép 为什么 + 学中文 → 为什么学中文, rồi thêm chủ ngữ 你 lên đầu → 你为什么学中文？","Trả lời lý do bằng 因为: ghép 因为 + 堵车 → 因为堵车, rồi nối vế kết quả bằng 所以我迟到了 → 因为堵车，所以我迟到了。"],"dialog":[{"who":"A","t":"你为什么不吃？","ph":"Nǐ wèishénme bù chī?","vph":"Nỉ uây sấn mơ pu chư?","vi":"Sao bạn không ăn?","hl":["为什么"]},{"who":"B","t":"因为太辣了。","ph":"Yīnwèi tài là le.","vph":"In uây thai la lơ.","vi":"Vì cay quá.","hl":["因为"]},{"who":"A","t":"那为什么不换一个菜？","ph":"Nà wèishénme bú huàn yí ge cài?","vph":"Na uây sấn mơ pú hoan í cưa chai?","vi":"Vậy sao không đổi món khác?","hl":["为什么"]},{"who":"B","t":"好主意！","ph":"Hǎo zhǔyi!","vph":"Hảo chủ i!","vi":"Ý hay đấy!","hl":[]}],"more":[{"t":"为什么不去？","ph":"Wèishénme bú qù?","vph":"Uây sấn mơ pú chuy?","vi":"Tại sao không đi?","hl":["为什么"],"tokens":["为什么","不","去"]},{"t":"你为什么笑？","ph":"Nǐ wèishénme xiào?","vph":"Nỉ uây sấn mơ xeo?","vi":"Sao bạn cười?","hl":["为什么"],"tokens":["你","为什么","笑"]},{"t":"你为什么这么累？","ph":"Nǐ wèishénme zhème lèi?","vph":"Nỉ uây sấn mơ chưa mơ lây?","vi":"Sao bạn mệt thế?","hl":["为什么"],"tokens":["你","为什么","这么","累"]},{"t":"他为什么没来上班？","ph":"Tā wèishénme méi lái shàngbān?","vph":"Tha uây sấn mơ mấy lái sang pan?","vi":"Tại sao anh ấy không đến làm?","hl":["为什么"],"tokens":["他","为什么","没","来","上班"]},{"t":"为什么今天地铁这么挤？","ph":"Wèishénme jīntiān dìtiě zhème jǐ?","vph":"Uây sấn mơ chin thiên ti thiể chưa mơ chỉ?","vi":"Sao hôm nay tàu điện ngầm đông thế?","hl":["为什么"],"tokens":["为什么","今天","地铁","这么","挤"]},{"t":"你为什么不早点告诉我？","ph":"Nǐ wèishénme bù zǎo diǎn gàosu wǒ?","vph":"Nỉ uây sấn mơ pu chảo tiẻn cao xu ủa?","vi":"Sao bạn không nói với tôi sớm hơn?","hl":["为什么"],"tokens":["你","为什么","不","早","点","告诉","我"]}]},{"id":15,"vi":"làm ơn","note":"请 + động từ dùng để mời hoặc nhờ lịch sự (mời…, làm ơn…). Khi hỏi đường, hỏi thông tin thì mở đầu bằng 请问 (xin hỏi).","pivot":{"t":"请","ph":"qǐng","vph":"chỉnh"},"branches":[{"steps":[{"t":"进","ph":"jìn","vph":"chin","vi":"vào","hl":[]},{"t":"请进","ph":"qǐng jìn","vph":"chỉnh chin","vi":"mời vào","hl":["请"]},{"t":"请进来坐吧。","ph":"Qǐng jìnlái zuò ba.","vph":"Chỉnh chin lái chua pa.","vi":"Mời vào ngồi đi.","hl":["请"],"tokens":["请","进来","坐","吧"]}]},{"steps":[{"t":"写","ph":"xiě","vph":"xỉa","vi":"viết","hl":[]},{"t":"请写","ph":"qǐng xiě","vph":"chỉnh xỉa","vi":"làm ơn viết","hl":["请"]},{"t":"请写在这儿。","ph":"Qǐng xiě zài zhèr.","vph":"Chỉnh xỉa chai chưa.","vi":"Làm ơn viết vào đây.","hl":["请"],"tokens":["请","写","在","这儿"]}]},{"steps":[{"t":"帮我","ph":"bāng wǒ","vph":"pang ủa","vi":"giúp tôi","hl":[]},{"t":"请帮我","ph":"qǐng bāng wǒ","vph":"chỉnh pang ủa","vi":"làm ơn giúp tôi","hl":["请"]},{"t":"请帮我拍张照。","ph":"Qǐng bāng wǒ pāi zhāng zhào.","vph":"Chỉnh pang ủa pai chang chao.","vi":"Làm ơn chụp giúp tôi một tấm ảnh.","hl":["请"],"tokens":["请","帮","我","拍","张","照"]}]}],"formula":[{"k":"P","t":"请"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ / Nơi chốn)"},{"k":"Q","t":"(吧)"}],"points":["请 + động từ đặt đầu câu để mời hoặc nhờ một cách lịch sự (\"请坐\" - mời ngồi, \"请等一下\" - xin đợi một chút).","Khi hỏi đường, hỏi thông tin thì mở đầu bằng 请问 (xin hỏi), không dùng 请问 để nhờ làm việc.","请 + người + động từ còn nghĩa là \"mời ai làm gì\", thường là mình trả tiền (\"我请你吃饭\" - tôi mời bạn ăn cơm).","Thêm 请 vào trước một mệnh lệnh làm câu nói nhẹ nhàng, lịch sự hơn hẳn."],"mistakes":[{"wrong":"请问帮我拍照。","right":"请帮我拍照。","why":"请问 chỉ dùng để mở đầu câu hỏi; nhờ ai làm gì thì dùng 请 + động từ."},{"wrong":"帮我请拍照。","right":"请帮我拍照。","why":"请 đứng đầu câu, trước cả cụm 帮我."}],"compare":"Giống tiếng Việt: 请 đứng đầu câu như \"mời/làm ơn\" (请进 = mời vào). Khác: 请 còn nghĩa là \"khao, đãi\": 我请你 = tôi mời (tôi trả tiền), điều mà chữ \"làm ơn\" không có.","tip":"Muốn lịch sự thì gắn 请 lên đầu: 坐 → 请坐, 等 → 请等, 进 → 请进.","how":["Đặt 请 trước 进 → 请进 (mời vào), rồi mở rộng thành 进来 và thêm 坐吧 phía sau → 请进来坐吧。","Ghép 请 + 写 → 请写, rồi thêm nơi chốn 在这儿 phía sau → 请写在这儿。","Ghép 请 + 帮我 → 请帮我, rồi thêm việc cần giúp 拍张照 phía sau → 请帮我拍张照。"],"dialog":[{"who":"A","t":"您好，请坐。","ph":"Nín hǎo, qǐng zuò.","vph":"Nín hảo, chỉnh chua.","vi":"Xin chào, mời ngồi.","hl":["请"]},{"who":"B","t":"谢谢。请问，这里可以换钱吗？","ph":"Xièxie. Qǐngwèn, zhèlǐ kěyǐ huàn qián ma?","vph":"Xiê xiê. Chỉnh uân, chưa lỉ khửa ỷ hoan chién ma?","vi":"Cảm ơn. Xin hỏi, ở đây đổi tiền được không?","hl":["请"]},{"who":"A","t":"可以，请给我看一下护照。","ph":"Kěyǐ, qǐng gěi wǒ kàn yíxià hùzhào.","vph":"Khửa ỷ, chỉnh cẩy ủa khan í xa hu chao.","vi":"Được, làm ơn cho tôi xem hộ chiếu.","hl":["请"]}],"more":[{"t":"请慢用。","ph":"Qǐng màn yòng.","vph":"Chỉnh man dung.","vi":"Mời quý khách dùng bữa ngon miệng.","hl":["请"],"tokens":["请","慢","用"]},{"t":"请等一下。","ph":"Qǐng děng yíxià.","vph":"Chỉnh tẩng í xa.","vi":"Xin đợi một chút.","hl":["请"],"tokens":["请","等","一下"]},{"t":"请说慢一点。","ph":"Qǐng shuō màn yìdiǎn.","vph":"Chỉnh sua man i tiẻn.","vi":"Làm ơn nói chậm một chút.","hl":["请"],"tokens":["请","说","慢","一点"]},{"t":"请给我一杯水。","ph":"Qǐng gěi wǒ yì bēi shuǐ.","vph":"Chỉnh cẩy ủa i pây suẩy.","vi":"Làm ơn cho tôi một cốc nước.","hl":["请"],"tokens":["请","给","我","一","杯","水"]},{"t":"请把行李放在门口。","ph":"Qǐng bǎ xíngli fàng zài ménkǒu.","vph":"Chỉnh pả xính lỉ phang chai mấn khẩu.","vi":"Làm ơn để hành lý ở cửa.","hl":["请"],"tokens":["请","把","行李","放","在","门口"]},{"t":"今天晚上我请你吃饭。","ph":"Jīntiān wǎnshang wǒ qǐng nǐ chī fàn.","vph":"Chin thiên oản sang ủa chỉnh nỉ chư phan.","vi":"Tối nay tôi mời bạn ăn cơm.","hl":["请"],"tokens":["今天","晚上","我","请","你","吃饭"]}]},{"id":16,"vi":"đừng","note":"别 + động từ là mệnh lệnh phủ định (đừng làm gì). 不要 có nghĩa tương tự nhưng trang trọng hơn một chút.","pivot":{"t":"别","ph":"bié","vph":"piế"},"branches":[{"steps":[{"t":"担心","ph":"dānxīn","vph":"tan xin","vi":"lo lắng","hl":[]},{"t":"别担心","ph":"bié dānxīn","vph":"piế tan xin","vi":"đừng lo","hl":["别"]},{"t":"你别担心。","ph":"Nǐ bié dānxīn.","vph":"Nỉ piế tan xin.","vi":"Bạn đừng lo.","hl":["别"],"tokens":["你","别","担心"]}]},{"steps":[{"t":"走","ph":"zǒu","vph":"chẩu","vi":"đi","hl":[]},{"t":"别走","ph":"bié zǒu","vph":"piế chẩu","vi":"đừng đi","hl":["别"]},{"t":"你先别走。","ph":"Nǐ xiān bié zǒu.","vph":"Nỉ xiên piế chẩu.","vi":"Bạn khoan hãy đi.","hl":["别"],"tokens":["你","先","别","走"]}]},{"steps":[{"t":"忘","ph":"wàng","vph":"oang","vi":"quên","hl":[]},{"t":"别忘","ph":"bié wàng","vph":"piế oang","vi":"đừng quên","hl":["别"]},{"t":"别忘了带护照。","ph":"Bié wàng le dài hùzhào.","vph":"Piế oang lơ tai hu chao.","vi":"Đừng quên mang hộ chiếu.","hl":["别"],"tokens":["别","忘","了","带","护照"]}]}],"formula":[{"k":"S","t":"(Chủ ngữ)"},{"k":"P","t":"别"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"},{"k":"Q","t":"(了)"}],"points":["别 + động từ là lời khuyên hoặc mệnh lệnh phủ định: đừng làm gì (\"别担心\" - đừng lo).","别 + động từ + 了 nghĩa là \"đừng … nữa\", nghe mềm và tự nhiên hơn (\"别哭了\" - đừng khóc nữa).","别忘了 + việc cần làm là cách nhắc nhở rất hay dùng (\"别忘了带护照\").","不要 + động từ có nghĩa tương tự 别 nhưng trang trọng hơn, hay gặp trên biển báo."],"mistakes":[{"wrong":"你不担心。","right":"你别担心。","why":"Khuyên \"đừng lo\" phải dùng 别; 不担心 chỉ là nêu sự thật \"(bạn) không lo\"."}],"compare":"Giống tiếng Việt: 别 đứng trước động từ như \"đừng\" (别走 = đừng đi). Khác: tiếng Trung hay thêm 了 cuối câu (别哭了 = đừng khóc nữa) để lời khuyên mềm và tự nhiên hơn.","tip":"别 đọc \"piế\" nghe na ná \"biết\": \"Biết rồi, đừng nói nữa!\" = 别说了！","how":["Đặt 别 trước động từ 担心 → 别担心, rồi thêm chủ ngữ 你 lên đầu → 你别担心。","Ghép 别 + 走 → 别走, rồi thêm 你 và 先 (khoan đã) trước 别 → 你先别走。","Ghép 别 + 忘 → 别忘, thêm 了 sau 忘 rồi nối việc cần nhớ 带护照 → 别忘了带护照。"],"dialog":[{"who":"A","t":"快点，飞机要起飞了！","ph":"Kuài diǎn, fēijī yào qǐfēi le!","vph":"Khoai tiẻn, phây chi dao chỉ phây lơ!","vi":"Nhanh lên, máy bay sắp cất cánh rồi!","hl":[]},{"who":"B","t":"别着急，还有一个小时。","ph":"Bié zháojí, hái yǒu yí ge xiǎoshí.","vph":"Piế cháo chí, hái dẩu í cưa xẻo sứ.","vi":"Đừng vội, còn một tiếng nữa mà.","hl":["别"]},{"who":"A","t":"好吧。别忘了拿行李！","ph":"Hǎo ba. Bié wàng le ná xíngli!","vph":"Hảo pa. Piế oang lơ ná xính lỉ!","vi":"Thôi được. Đừng quên lấy hành lý nhé!","hl":["别"]}],"more":[{"t":"你别客气。","ph":"Nǐ bié kèqi.","vph":"Nỉ piế khưa chi.","vi":"Bạn đừng khách sáo.","hl":["别"],"tokens":["你","别","客气"]},{"t":"别说话了。","ph":"Bié shuōhuà le.","vph":"Piế sua hoa lơ.","vi":"Đừng nói chuyện nữa.","hl":["别"],"tokens":["别","说话","了"]},{"t":"你别生气了。","ph":"Nǐ bié shēngqì le.","vph":"Nỉ piế sâng chi lơ.","vi":"Bạn đừng giận nữa.","hl":["别"],"tokens":["你","别","生气","了"]},{"t":"别在这儿抽烟。","ph":"Bié zài zhèr chōuyān.","vph":"Piế chai chưa châu dan.","vi":"Đừng hút thuốc ở đây.","hl":["别"],"tokens":["别","在","这儿","抽烟"]},{"t":"别喝太多酒。","ph":"Bié hē tài duō jiǔ.","vph":"Piế khưa thai tua chiểu.","vi":"Đừng uống quá nhiều rượu.","hl":["别"],"tokens":["别","喝","太","多","酒"]},{"t":"晚上别一个人出去。","ph":"Wǎnshang bié yí ge rén chūqu.","vph":"Oản sang piế í cưa rấn chu chuy.","vi":"Buổi tối đừng ra ngoài một mình.","hl":["别"],"tokens":["晚上","别","一","个","人","出去"]}]},{"id":17,"vi":"đã","note":"了 đặt sau động từ hoặc cuối câu để chỉ hành động đã xảy ra/đã hoàn thành; thường đi với 已经 (đã). Phủ định quá khứ dùng 没 + động từ và bỏ 了; 过 diễn tả trải nghiệm (đã từng).","pivot":{"t":"了","ph":"le","vph":"lơ"},"branches":[{"steps":[{"t":"吃","ph":"chī","vph":"chư","vi":"ăn","hl":[]},{"t":"吃了","ph":"chī le","vph":"chư lơ","vi":"đã ăn","hl":["了"]},{"t":"我已经吃了。","ph":"Wǒ yǐjīng chī le.","vph":"Ủa ỷ chinh chư lơ.","vi":"Tôi đã ăn rồi.","hl":["了"],"tokens":["我","已经","吃","了"]}]},{"steps":[{"t":"到","ph":"dào","vph":"tao","vi":"đến","hl":[]},{"t":"到了","ph":"dào le","vph":"tao lơ","vi":"đã đến","hl":["了"]},{"t":"飞机到了。","ph":"Fēijī dào le.","vph":"Phây chi tao lơ.","vi":"Máy bay đã đến rồi.","hl":["了"],"tokens":["飞机","到","了"]}]},{"steps":[{"t":"买","ph":"mǎi","vph":"mải","vi":"mua","hl":[]},{"t":"买了","ph":"mǎi le","vph":"mải lơ","vi":"đã mua","hl":["了"]},{"t":"我买了两张票。","ph":"Wǒ mǎi le liǎng zhāng piào.","vph":"Ủa mải lơ lẻng chang peo.","vi":"Tôi đã mua hai vé.","hl":["了"],"tokens":["我","买","了","两","张","票"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"A","t":"(已经)"},{"k":"V","t":"Động từ"},{"k":"P","t":"了"},{"k":"O","t":"(Số lượng + Tân ngữ)"}],"points":["了 đặt sau động từ hoặc cuối câu để chỉ hành động đã xảy ra, đã hoàn thành (\"他回家了\" - anh ấy về nhà rồi).","Tân ngữ có số lượng thì dùng mẫu: Động từ + 了 + số lượng + tân ngữ (\"买了两张票\").","Có 已经 (đã) thì cuối câu vẫn cần 了 (\"我已经吃了\").","Phủ định việc đã qua dùng 没 + động từ và bỏ 了 (\"我没吃\" - tôi chưa ăn)."],"mistakes":[{"wrong":"我没吃了。","right":"我没吃。","why":"Phủ định quá khứ dùng 没 + động từ và phải bỏ 了."},{"wrong":"我已经吃。","right":"我已经吃了。","why":"Tiếng Việt chỉ cần \"đã\", nhưng tiếng Trung có 已经 vẫn phải thêm 了."}],"compare":"Giống tiếng Việt: 了 giống chữ \"rồi\" (吃了 = ăn rồi). Khác: 了 đứng SAU động từ hoặc cuối câu chứ không đứng trước như \"đã\", và câu phủ định (没…) thì phải bỏ 了.","tip":"了 = \"rồi\": việc xong rồi thì gắn 了 sau động từ; còn \"chưa\" thì đổi sang 没 và vứt 了 đi.","how":["Thêm 了 sau động từ 吃 → 吃了, rồi đặt chủ ngữ 我 và 已经 (đã) trước động từ → 我已经吃了。","Ghép 到 + 了 → 到了 (đến rồi), rồi đặt chủ ngữ 飞机 lên đầu → 飞机到了。","Ghép 买 + 了 → 买了, thêm 我 phía trước và số lượng + tân ngữ 两张票 phía sau → 我买了两张票。"],"dialog":[{"who":"A","t":"你到了吗？","ph":"Nǐ dào le ma?","vph":"Nỉ tao lơ ma?","vi":"Bạn đến chưa?","hl":["了"]},{"who":"B","t":"我到了，在酒店门口。","ph":"Wǒ dào le, zài jiǔdiàn ménkǒu.","vph":"Ủa tao lơ, chai chiểu tiên mấn khẩu.","vi":"Tôi đến rồi, ở cửa khách sạn.","hl":["了"]},{"who":"A","t":"好，我马上下来。你吃饭了吗？","ph":"Hǎo, wǒ mǎshàng xiàlai. Nǐ chī fàn le ma?","vph":"Hảo, ủa mả sang xa lai. Nỉ chư phan lơ ma?","vi":"Được, tôi xuống ngay. Bạn ăn cơm chưa?","hl":["了"]},{"who":"B","t":"还没吃，我们一起去吧。","ph":"Hái méi chī, wǒmen yìqǐ qù ba.","vph":"Hái mấy chư, ủa mân i chỉ chuy pa.","vi":"Chưa ăn, chúng ta cùng đi nhé.","hl":[]}],"more":[{"t":"外面下雨了。","ph":"Wàimian xià yǔ le.","vph":"Oai miên xa dủy lơ.","vi":"Ngoài trời mưa rồi.","hl":["了"],"tokens":["外面","下雨","了"]},{"t":"他回家了。","ph":"Tā huí jiā le.","vph":"Tha khuấy chia lơ.","vi":"Anh ấy về nhà rồi.","hl":["了"],"tokens":["他","回家","了"]},{"t":"我们到酒店了。","ph":"Wǒmen dào jiǔdiàn le.","vph":"Ủa mân tao chiểu tiên lơ.","vi":"Chúng tôi đến khách sạn rồi.","hl":["了"],"tokens":["我们","到","酒店","了"]},{"t":"我喝了一杯咖啡。","ph":"Wǒ hē le yì bēi kāfēi.","vph":"Ủa khưa lơ i pây kha phây.","vi":"Tôi đã uống một cốc cà phê.","hl":["了"],"tokens":["我","喝","了","一","杯","咖啡"]},{"t":"我已经订好房间了。","ph":"Wǒ yǐjīng dìng hǎo fángjiān le.","vph":"Ủa ỷ chinh tinh hảo pháng chiên lơ.","vi":"Tôi đã đặt phòng xong rồi.","hl":["了"],"tokens":["我","已经","订","好","房间","了"]},{"t":"昨天我们看了一个电影。","ph":"Zuótiān wǒmen kàn le yí ge diànyǐng.","vph":"Chúa thiên ủa mân khan lơ í cưa tiên dỉnh.","vi":"Hôm qua chúng tôi đã xem một bộ phim.","hl":["了"],"tokens":["昨天","我们","看","了","一","个","电影"]}]},{"id":18,"vi":"sẽ","note":"会 + động từ diễn tả dự đoán hoặc việc sẽ xảy ra (sẽ làm gì). 要 nhấn mạnh dự định sắp làm, 将 dùng trong văn viết trang trọng.","pivot":{"t":"会","ph":"huì","vph":"huây"},"branches":[{"steps":[{"t":"来","ph":"lái","vph":"lái","vi":"đến","hl":[]},{"t":"会来","ph":"huì lái","vph":"huây lái","vi":"sẽ đến","hl":["会"]},{"t":"他明天会来。","ph":"Tā míngtiān huì lái.","vph":"Tha mính thiên huây lái.","vi":"Ngày mai anh ấy sẽ đến.","hl":["会"],"tokens":["他","明天","会","来"]}]},{"steps":[{"t":"下雨","ph":"xià yǔ","vph":"xa dủy","vi":"mưa","hl":[]},{"t":"会下雨","ph":"huì xià yǔ","vph":"huây xa dủy","vi":"sẽ mưa","hl":["会"]},{"t":"明天会下雨吗？","ph":"Míngtiān huì xià yǔ ma?","vph":"Mính thiên huây xa dủy ma?","vi":"Ngày mai trời có mưa không?","hl":["会"],"tokens":["明天","会","下雨","吗"]}]},{"steps":[{"t":"回来","ph":"huílai","vph":"khuấy lai","vi":"quay lại","hl":[]},{"t":"会回来","ph":"huì huílai","vph":"huây khuấy lai","vi":"sẽ quay lại","hl":["会"]},{"t":"我很快就会回来。","ph":"Wǒ hěn kuài jiù huì huílai.","vph":"Ủa hẩn khoai chiêu huây khuấy lai.","vi":"Tôi sẽ quay lại ngay.","hl":["会"],"tokens":["我","很快","就","会","回来"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"X","t":"(Thời gian)"},{"k":"P","t":"会"},{"k":"V","t":"Động từ"}],"points":["会 + động từ diễn tả dự đoán hoặc việc sẽ xảy ra (\"明天会下雨\" - mai trời sẽ mưa).","Từ chỉ thời gian đặt sau chủ ngữ, trước 会 (\"他明天会来\").","Phủ định là 不会 (sẽ không), không dùng 没会; hỏi bằng …会…吗？ hoặc 会不会…？","会 còn nghĩa là \"biết\" (kỹ năng học được): \"我会游泳\" - tôi biết bơi; phân biệt nhờ ngữ cảnh."],"mistakes":[{"wrong":"我会明天去。","right":"我明天会去。","why":"Thời gian đặt sau chủ ngữ, trước 会, không chen giữa 会 và động từ."},{"wrong":"他没会来。","right":"他不会来。","why":"Phủ định của 会 luôn là 不会."}],"compare":"Giống tiếng Việt: 会 đứng trước động từ như \"sẽ\" (会来 = sẽ đến). Khác: 会 còn nghĩa \"biết làm\" (我会游泳 = tôi biết bơi), và thời gian luôn đứng trước 会 chứ không đứng sau.","tip":"会 \"huây\" có hai mặt: nói chuyện tương lai thì là \"sẽ\", nói chuyện kỹ năng thì là \"biết\".","how":["Đặt 会 trước động từ 来 → 会来, rồi thêm chủ ngữ 他 và thời gian 明天 trước 会 → 他明天会来。","Ghép 会 + 下雨 → 会下雨, thêm 明天 lên đầu và 吗 cuối câu để hỏi → 明天会下雨吗？","Ghép 会 + 回来 → 会回来, rồi thêm 我 và 很快就 (rất nhanh thôi) trước 会 → 我很快就会回来。"],"dialog":[{"who":"A","t":"明天会冷吗？","ph":"Míngtiān huì lěng ma?","vph":"Mính thiên huây lẩng ma?","vi":"Ngày mai trời có lạnh không?","hl":["会"]},{"who":"B","t":"会，听说会下雪。","ph":"Huì, tīngshuō huì xià xuě.","vph":"Huây, thinh sua huây xa xuể.","vi":"Có, nghe nói sẽ có tuyết.","hl":["会"]},{"who":"A","t":"那我会多穿一点。","ph":"Nà wǒ huì duō chuān yìdiǎn.","vph":"Na ủa huây tua choan i tiẻn.","vi":"Vậy tôi sẽ mặc thêm áo.","hl":["会"]}],"more":[{"t":"我会告诉他。","ph":"Wǒ huì gàosu tā.","vph":"Ủa huây cao xu tha.","vi":"Tôi sẽ nói với anh ấy.","hl":["会"],"tokens":["我","会","告诉","他"]},{"t":"你会喜欢的。","ph":"Nǐ huì xǐhuan de.","vph":"Nỉ huây xỉ hoan tơ.","vi":"Bạn sẽ thích cho xem.","hl":["会"],"tokens":["你","会","喜欢","的"]},{"t":"今天会很热。","ph":"Jīntiān huì hěn rè.","vph":"Chin thiên huây hẩn rưa.","vi":"Hôm nay sẽ rất nóng.","hl":["会"],"tokens":["今天","会","很","热"]},{"t":"她不会来了。","ph":"Tā bú huì lái le.","vph":"Tha pú huây lái lơ.","vi":"Cô ấy sẽ không đến nữa.","hl":["会"],"tokens":["她","不","会","来","了"]},{"t":"我们周末会去海边。","ph":"Wǒmen zhōumò huì qù hǎibiān.","vph":"Ủa mân châu mua huây chuy hải piên.","vi":"Cuối tuần chúng tôi sẽ đi biển.","hl":["会"],"tokens":["我们","周末","会","去","海边"]},{"t":"我下个月会去上海出差。","ph":"Wǒ xià ge yuè huì qù Shànghǎi chūchāi.","vph":"Ủa xa cưa duê huây chuy Sang hải chu chai.","vi":"Tháng sau tôi sẽ đi công tác Thượng Hải.","hl":["会"],"tokens":["我","下","个","月","会","去","上海","出差"]}]},{"id":19,"vi":"đang","note":"Đặt 在 (hoặc 正在) trước động từ để diễn tả hành động đang diễn ra: Chủ ngữ + 在 + động từ. Có thể thêm 呢 ở cuối câu cho tự nhiên hơn.","pivot":{"t":"在","ph":"zài","vph":"chai"},"branches":[{"steps":[{"t":"吃饭","ph":"chīfàn","vph":"chư phan","vi":"ăn cơm","hl":[]},{"t":"在吃饭","ph":"zài chīfàn","vph":"chai chư phan","vi":"đang ăn cơm","hl":["在"]},{"t":"我在吃饭。","ph":"Wǒ zài chīfàn.","vph":"Ủa chai chư phan.","vi":"Tôi đang ăn cơm.","hl":["在"],"tokens":["我","在","吃饭"]}]},{"steps":[{"t":"下雨","ph":"xiàyǔ","vph":"xa dủy","vi":"mưa","hl":[]},{"t":"在下雨","ph":"zài xiàyǔ","vph":"chai xa dủy","vi":"đang mưa","hl":["在"]},{"t":"外面在下雨。","ph":"Wàimiàn zài xiàyǔ.","vph":"Oai miên chai xa dủy.","vi":"Bên ngoài đang mưa.","hl":["在"],"tokens":["外面","在","下雨"]}]},{"steps":[{"t":"工作","ph":"gōngzuò","vph":"cung chua","vi":"làm việc","hl":[]},{"t":"在工作","ph":"zài gōngzuò","vph":"chai cung chua","vi":"đang làm việc","hl":["在"]},{"t":"他正在工作。","ph":"Tā zhèngzài gōngzuò.","vph":"Tha châng chai cung chua.","vi":"Anh ấy đang làm việc.","hl":["正在"],"tokens":["他","正在","工作"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"在"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["在 đứng sau chủ ngữ, ngay trước động từ: \"我在看书\" = Tôi đang đọc sách.","正在 nhấn mạnh \"đúng lúc này đang\"; thêm 呢 cuối câu cho tự nhiên: \"他在睡觉呢\".","Phủ định dùng 没(在), không dùng 不在: \"我没在看电视\" = Tôi đâu có đang xem TV.","Hỏi ai đó đang làm gì: \"你在干什么？\" = Bạn đang làm gì thế?"],"mistakes":[{"wrong":"我吃饭在。","right":"我在吃饭。","why":"在 (đang) phải đứng trước động từ, không đặt ở cuối câu."},{"wrong":"我不在看电视。","right":"我没在看电视。","why":"Phủ định hành động đang diễn ra dùng 没; 不在 nghĩa là \"không có ở đây\"."}],"compare":"Giống tiếng Việt: 在 đứng trước động từ đúng như chữ \"đang\". Khác: tiếng Trung hay thêm 呢 ở cuối câu cho mềm, và động từ không đổi dạng.","tip":"在 = \"đang\" — tiếng Việt có chữ \"đang\" ở đâu thì đặt 在 vào đúng chỗ đó!","how":["Thêm 在 trước động từ 吃饭 → 在吃饭 (đang ăn cơm), rồi đặt chủ ngữ 我 lên đầu → 我在吃饭。","Thêm 在 trước 下雨 → 在下雨 (đang mưa), rồi đặt 外面 (bên ngoài) làm chủ ngữ → 外面在下雨。","Thêm 在 trước 工作 → 在工作 (đang làm việc), rồi đặt chủ ngữ 他 lên đầu và đổi thành 正在 để nhấn mạnh \"đang đúng lúc này\" → 他正在工作。"],"dialog":[{"who":"A","t":"你在干什么？","ph":"Nǐ zài gàn shénme?","vph":"Nỉ chai can sấn mơ?","vi":"Bạn đang làm gì thế?","hl":["在"]},{"who":"B","t":"我在做饭呢。","ph":"Wǒ zài zuòfàn ne.","vph":"Ủa chai chua phan nơ.","vi":"Tôi đang nấu cơm đây.","hl":["在"]},{"who":"A","t":"你妈妈呢？","ph":"Nǐ māma ne?","vph":"Nỉ ma ma nơ?","vi":"Còn mẹ bạn?","hl":[]},{"who":"B","t":"她在看电视。","ph":"Tā zài kàn diànshì.","vph":"Tha chai khan tiên sư.","vi":"Mẹ đang xem TV.","hl":["在"]}],"more":[{"t":"我在看书。","ph":"Wǒ zài kàn shū.","vph":"Ủa chai khan su.","vi":"Tôi đang đọc sách.","hl":["在"],"tokens":["我","在","看书"]},{"t":"孩子在睡觉。","ph":"Háizi zài shuìjiào.","vph":"Hái chư chai suây cheo.","vi":"Đứa bé đang ngủ.","hl":["在"],"tokens":["孩子","在","睡觉"]},{"t":"你在等谁？","ph":"Nǐ zài děng shéi?","vph":"Nỉ chai tẩng suấy?","vi":"Bạn đang đợi ai?","hl":["在"],"tokens":["你","在","等","谁"]},{"t":"我们正在开会。","ph":"Wǒmen zhèngzài kāihuì.","vph":"Ủa mân châng chai khai huây.","vi":"Chúng tôi đang họp.","hl":["正在"],"tokens":["我们","正在","开会"]},{"t":"他在听音乐呢。","ph":"Tā zài tīng yīnyuè ne.","vph":"Tha chai thinh in duê nơ.","vi":"Anh ấy đang nghe nhạc.","hl":["在"],"tokens":["他","在","听","音乐","呢"]},{"t":"服务员正在准备你们的菜。","ph":"Fúwùyuán zhèngzài zhǔnbèi nǐmen de cài.","vph":"Phú u doén châng chai chuẩn pây nỉ mân tơ chai.","vi":"Nhân viên đang chuẩn bị món cho các bạn.","hl":["正在"],"tokens":["服务员","正在","准备","你们","的","菜"]}]},{"id":20,"vi":"rồi","note":"Đặt 了 sau động từ hoặc cuối câu để báo hành động đã xong hay tình huống đã thay đổi. Có thể thêm 已经 (đã) trước động từ để nhấn mạnh.","pivot":{"t":"了","ph":"le","vph":"lơ"},"branches":[{"steps":[{"t":"到","ph":"dào","vph":"tao","vi":"đến","hl":[]},{"t":"到了","ph":"dào le","vph":"tao lơ","vi":"đến rồi","hl":["了"]},{"t":"我们到了。","ph":"Wǒmen dào le.","vph":"Ủa mân tao lơ.","vi":"Chúng ta đến rồi.","hl":["了"],"tokens":["我们","到","了"]}]},{"steps":[{"t":"明白","ph":"míngbai","vph":"mính pai","vi":"hiểu","hl":[]},{"t":"明白了","ph":"míngbai le","vph":"mính pai lơ","vi":"hiểu rồi","hl":["了"]},{"t":"我明白了。","ph":"Wǒ míngbai le.","vph":"Ủa mính pai lơ.","vi":"Tôi hiểu rồi.","hl":["了"],"tokens":["我","明白","了"]}]},{"steps":[{"t":"走","ph":"zǒu","vph":"chẩu","vi":"đi","hl":[]},{"t":"走了","ph":"zǒu le","vph":"chẩu lơ","vi":"đi rồi","hl":["了"]},{"t":"他已经走了。","ph":"Tā yǐjīng zǒu le.","vph":"Tha ỷ chinh chẩu lơ.","vi":"Anh ấy đi rồi.","hl":["已经","了"],"tokens":["他","已经","走","了"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"A","t":"(Đã)"},{"k":"V","t":"Động từ"},{"k":"P","t":"了"}],"points":["了 đặt sau động từ hoặc cuối câu để báo việc đã xong: \"我吃了\" = Tôi ăn rồi.","了 cuối câu còn báo sự thay đổi: \"下雨了\" = Trời mưa rồi (lúc nãy chưa mưa).","Thêm 已经 (đã) trước động từ để nhấn mạnh \"đã ... rồi\": \"他已经走了\".","Câu phủ định dùng 没 + động từ và BỎ 了: nói \"我没吃\", không nói \"我没吃了\"."],"mistakes":[{"wrong":"我没去了。","right":"我没去。","why":"Phủ định việc đã qua dùng 没 và không giữ 了."},{"wrong":"我了吃饭。","right":"我吃饭了。","why":"了 đứng sau động từ hoặc cuối câu, không đứng trước động từ như chữ \"đã\"."}],"compare":"Giống chữ \"rồi\" tiếng Việt: đặt ở cuối để báo việc đã xong. Khác: chữ \"đã\" đứng trước động từ thì ứng với 已经, còn 了 luôn đứng sau.","tip":"了 = \"rồi\" — \"rồi\" nằm cuối câu, 了 cũng nằm cuối câu!","how":["Thêm 了 sau động từ 到 → 到了 (đến rồi), rồi đặt chủ ngữ 我们 lên đầu → 我们到了。","Thêm 了 sau 明白 → 明白了 (hiểu rồi), rồi đặt chủ ngữ 我 lên đầu → 我明白了。","Thêm 了 sau 走 → 走了 (đi rồi), rồi thêm chủ ngữ 他 và 已经 (đã) trước động từ → 他已经走了。"],"dialog":[{"who":"A","t":"你吃饭了吗？","ph":"Nǐ chīfàn le ma?","vph":"Nỉ chư phan lơ ma?","vi":"Bạn ăn cơm chưa?","hl":["了"]},{"who":"B","t":"吃了，你呢？","ph":"Chī le, nǐ ne?","vph":"Chư lơ, nỉ nơ?","vi":"Ăn rồi, còn bạn?","hl":["了"]},{"who":"A","t":"我还没吃，饿了。","ph":"Wǒ hái méi chī, è le.","vph":"Ủa hái mấy chư, ưa lơ.","vi":"Tôi chưa ăn, đói rồi.","hl":["了"]},{"who":"B","t":"走吧，一起去吃。","ph":"Zǒu ba, yìqǐ qù chī.","vph":"Chẩu pa, i chỉ chuy chư.","vi":"Đi thôi, cùng đi ăn nào.","hl":[]}],"more":[{"t":"天黑了。","ph":"Tiān hēi le.","vph":"Thiên hây lơ.","vi":"Trời tối rồi.","hl":["了"],"tokens":["天","黑","了"]},{"t":"我买票了。","ph":"Wǒ mǎi piào le.","vph":"Ủa mải p'eo lơ.","vi":"Tôi mua vé rồi.","hl":["了"],"tokens":["我","买","票","了"]},{"t":"咖啡喝完了。","ph":"Kāfēi hēwán le.","vph":"Kha phây hưa oán lơ.","vi":"Cà phê uống hết rồi.","hl":["了"],"tokens":["咖啡","喝完","了"]},{"t":"我已经吃饱了。","ph":"Wǒ yǐjīng chī bǎo le.","vph":"Ủa ỷ chinh chư pảo lơ.","vi":"Tôi đã ăn no rồi.","hl":["已经","了"],"tokens":["我","已经","吃","饱","了"]},{"t":"飞机已经起飞了。","ph":"Fēijī yǐjīng qǐfēi le.","vph":"Phây chi ỷ chinh chỉ phây lơ.","vi":"Máy bay đã cất cánh rồi.","hl":["已经","了"],"tokens":["飞机","已经","起飞","了"]},{"t":"我昨天买了两张票。","ph":"Wǒ zuótiān mǎi le liǎng zhāng piào.","vph":"Ủa chúa thiên mải lơ lẻng chang p'eo.","vi":"Hôm qua tôi đã mua hai vé.","hl":["了"],"tokens":["我","昨天","买","了","两","张","票"]}]},{"id":21,"vi":"chưa","note":"Dùng 还没 + động từ để nói 'chưa làm gì' (không dùng 了 trong câu phủ định này). Hỏi 'đã ... chưa?' bằng động từ + 了没有 / 了吗.","pivot":{"t":"还没","ph":"hái méi","vph":"hái mấy"},"branches":[{"steps":[{"t":"买","ph":"mǎi","vph":"mải","vi":"mua","hl":[]},{"t":"还没买","ph":"hái méi mǎi","vph":"hái mấy mải","vi":"chưa mua","hl":["还没"]},{"t":"我还没买票。","ph":"Wǒ hái méi mǎi piào.","vph":"Ủa hái mấy mải p'eo.","vi":"Tôi chưa mua vé.","hl":["还没"],"tokens":["我","还","没","买","票"]}]},{"steps":[{"t":"来","ph":"lái","vph":"lái","vi":"đến","hl":[]},{"t":"还没来","ph":"hái méi lái","vph":"hái mấy lái","vi":"chưa đến","hl":["还没"]},{"t":"车还没来。","ph":"Chē hái méi lái.","vph":"Chưa hái mấy lái.","vi":"Xe vẫn chưa đến.","hl":["还没"],"tokens":["车","还","没","来"]}]},{"steps":[{"t":"吃","ph":"chī","vph":"chư","vi":"ăn","hl":[]},{"t":"吃了没有","ph":"chī le méiyǒu","vph":"chư lơ mấy dẩu","vi":"ăn chưa","hl":["没有"]},{"t":"你吃了没有？","ph":"Nǐ chī le méiyǒu?","vph":"Nỉ chư lơ mấy dẩu?","vi":"Bạn ăn chưa?","hl":["没有"],"tokens":["你","吃","了","没有"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"还没"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["还没 + động từ = chưa làm gì: \"我还没吃\" = Tôi chưa ăn.","Câu có 还没 KHÔNG dùng 了: nói \"他还没来\", không nói \"他还没来了\".","Hỏi \"đã ... chưa?\" bằng động từ + 了没有 hoặc 了吗: \"你吃了没有？\".","Trả lời ngắn \"chưa\" là \"还没（呢）\", trả lời \"rồi\" là động từ + 了."],"mistakes":[{"wrong":"我还不吃。","right":"我还没吃。","why":"\"Chưa\" làm gì dùng 没; 不 nghĩa là \"không (muốn)\"."},{"wrong":"他还没来了。","right":"他还没来。","why":"Đã phủ định bằng 没 thì phải bỏ 了."}],"compare":"Giống tiếng Việt: 还没 đứng trước động từ như chữ \"chưa\". Khác: câu hỏi \"đã ... chưa?\" đặt 了没有 sau động từ, không có chữ \"đã\" đứng trước.","tip":"还没 = \"vẫn chưa\" — đã có 没 thì tạm biệt 了!","how":["Thêm 还没 trước động từ 买 → 还没买 (chưa mua), rồi thêm chủ ngữ 我 ở đầu và tân ngữ 票 ở cuối → 我还没买票。","Thêm 还没 trước 来 → 还没来 (chưa đến), rồi đặt chủ ngữ 车 lên đầu → 车还没来。","Để hỏi \"ăn chưa\", thêm 了没有 sau động từ 吃 → 吃了没有, rồi đặt chủ ngữ 你 lên đầu → 你吃了没有？"],"dialog":[{"who":"A","t":"你订酒店了没有？","ph":"Nǐ dìng jiǔdiàn le méiyǒu?","vph":"Nỉ tinh chiểu tiên lơ mấy dẩu?","vi":"Bạn đặt khách sạn chưa?","hl":["没有"]},{"who":"B","t":"还没，太忙了。","ph":"Hái méi, tài máng le.","vph":"Hái mấy, thai máng lơ.","vi":"Chưa, bận quá.","hl":["还没"]},{"who":"A","t":"机票呢？","ph":"Jīpiào ne?","vph":"Chi p'eo nơ?","vi":"Còn vé máy bay?","hl":[]},{"who":"B","t":"机票也还没买。","ph":"Jīpiào yě hái méi mǎi.","vph":"Chi p'eo dể hái mấy mải.","vi":"Vé máy bay cũng chưa mua.","hl":["还没"]}],"more":[{"t":"我还没吃。","ph":"Wǒ hái méi chī.","vph":"Ủa hái mấy chư.","vi":"Tôi chưa ăn.","hl":["还没"],"tokens":["我","还","没","吃"]},{"t":"菜还没上。","ph":"Cài hái méi shàng.","vph":"Chai hái mấy sang.","vi":"Món ăn chưa lên.","hl":["还没"],"tokens":["菜","还","没","上"]},{"t":"他还没起床。","ph":"Tā hái méi qǐchuáng.","vph":"Tha hái mấy chỉ choáng.","vi":"Anh ấy chưa dậy.","hl":["还没"],"tokens":["他","还","没","起床"]},{"t":"你到了没有？","ph":"Nǐ dào le méiyǒu?","vph":"Nỉ tao lơ mấy dẩu?","vi":"Bạn đến chưa?","hl":["没有"],"tokens":["你","到","了","没有"]},{"t":"我还没去过北京。","ph":"Wǒ hái méi qùguo Běijīng.","vph":"Ủa hái mấy chuy cua Pẩy chinh.","vi":"Tôi chưa từng đi Bắc Kinh.","hl":["还没"],"tokens":["我","还","没","去过","北京"]},{"t":"我们还没决定去哪儿。","ph":"Wǒmen hái méi juédìng qù nǎr.","vph":"Ủa mân hái mấy chuế tinh chuy nả.","vi":"Chúng tôi chưa quyết định đi đâu.","hl":["还没"],"tokens":["我们","还","没","决定","去","哪儿"]}]},{"id":22,"vi":"rất","note":"Đặt 很 trước tính từ: Chủ ngữ + 很 + tính từ, không cần động từ 是. Muốn nhấn mạnh hơn có thể dùng 非常 (vô cùng).","pivot":{"t":"很","ph":"hěn","vph":"hẩn"},"branches":[{"steps":[{"t":"好吃","ph":"hǎochī","vph":"hảo chư","vi":"ngon","hl":[]},{"t":"很好吃","ph":"hěn hǎochī","vph":"hẩn hảo chư","vi":"rất ngon","hl":["很"]},{"t":"这个菜很好吃。","ph":"Zhège cài hěn hǎochī.","vph":"Chưa cưa chai hẩn hảo chư.","vi":"Món này rất ngon.","hl":["很"],"tokens":["这个","菜","很","好吃"]}]},{"steps":[{"t":"忙","ph":"máng","vph":"máng","vi":"bận","hl":[]},{"t":"很忙","ph":"hěn máng","vph":"hẩn máng","vi":"rất bận","hl":["很"]},{"t":"我今天很忙。","ph":"Wǒ jīntiān hěn máng.","vph":"Ủa chin thiên hẩn máng.","vi":"Hôm nay tôi rất bận.","hl":["很"],"tokens":["我","今天","很","忙"]}]},{"steps":[{"t":"漂亮","ph":"piàoliang","vph":"p'eo leng","vi":"đẹp","hl":[]},{"t":"很漂亮","ph":"hěn piàoliang","vph":"hẩn p'eo leng","vi":"rất đẹp","hl":["很"]},{"t":"这里很漂亮。","ph":"Zhèlǐ hěn piàoliang.","vph":"Chưa lỉ hẩn p'eo leng.","vi":"Chỗ này rất đẹp.","hl":["很"],"tokens":["这里","很","漂亮"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"很"},{"k":"A","t":"Tính từ"}],"points":["Đặt 很 trước tính từ để miêu tả: \"我很忙\" = Tôi (rất) bận.","Không thêm 是 trước tính từ: nói \"她很漂亮\", không nói \"她是漂亮\".","Trong câu khẳng định, 很 nhiều khi chỉ giúp câu tròn nghĩa; muốn nhấn mạnh thật sự thì dùng 非常.","Phủ định bỏ 很, dùng 不 + tính từ: \"不忙\"; \"không ... lắm\" thì dùng 不太."],"mistakes":[{"wrong":"她是很漂亮。","right":"她很漂亮。","why":"Tính từ tự làm vị ngữ, không cần 是 như chữ \"là\" của tiếng Việt."},{"wrong":"我忙很。","right":"我很忙。","why":"很 luôn đứng trước tính từ, không đặt sau như kiểu \"bận lắm\"."}],"compare":"Giống chữ \"rất\" tiếng Việt: đứng trước tính từ. Khác: tiếng Việt hay nói \"bận lắm\" (lắm đứng sau), còn tiếng Trung luôn đặt 很 phía trước và không cần \"là\".","tip":"Câu miêu tả thiếu 很 nghe cụt lủn — cứ \"chủ ngữ + 很 + tính từ\" là chuẩn!","how":["Thêm 很 trước tính từ 好吃 → 很好吃 (rất ngon), rồi đặt chủ ngữ 这个菜 lên đầu → 这个菜很好吃。","Thêm 很 trước 忙 → 很忙 (rất bận), rồi đặt chủ ngữ 我 và thời gian 今天 lên trước → 我今天很忙。","Thêm 很 trước 漂亮 → 很漂亮 (rất đẹp), rồi đặt chủ ngữ 这里 (nơi này) lên đầu → 这里很漂亮。"],"dialog":[{"who":"A","t":"你好吗？","ph":"Nǐ hǎo ma?","vph":"Nỉ hảo ma?","vi":"Bạn khỏe không?","hl":[]},{"who":"B","t":"我很好，谢谢！","ph":"Wǒ hěn hǎo, xièxie!","vph":"Ủa hẩn hảo, xiê xiê!","vi":"Tôi khỏe, cảm ơn!","hl":["很"]},{"who":"A","t":"最近工作忙吗？","ph":"Zuìjìn gōngzuò máng ma?","vph":"Chuây chin cung chua máng ma?","vi":"Dạo này công việc bận không?","hl":[]},{"who":"B","t":"很忙，但是很有意思。","ph":"Hěn máng, dànshì hěn yǒu yìsi.","vph":"Hẩn máng, tan sư hẩn dẩu i sư.","vi":"Rất bận, nhưng rất thú vị.","hl":["很"]}],"more":[{"t":"我很累。","ph":"Wǒ hěn lèi.","vph":"Ủa hẩn lây.","vi":"Tôi rất mệt.","hl":["很"],"tokens":["我","很","累"]},{"t":"天气很好。","ph":"Tiānqì hěn hǎo.","vph":"Thiên chi hẩn hảo.","vi":"Thời tiết rất đẹp.","hl":["很"],"tokens":["天气","很","好"]},{"t":"这杯咖啡很好喝。","ph":"Zhè bēi kāfēi hěn hǎohē.","vph":"Chưa pây kha phây hẩn hảo hưa.","vi":"Ly cà phê này rất ngon.","hl":["很"],"tokens":["这","杯","咖啡","很","好喝"]},{"t":"他的中文很好。","ph":"Tā de Zhōngwén hěn hǎo.","vph":"Tha tơ Chung uấn hẩn hảo.","vi":"Tiếng Trung của anh ấy rất giỏi.","hl":["很"],"tokens":["他","的","中文","很","好"]},{"t":"酒店离机场很近。","ph":"Jiǔdiàn lí jīchǎng hěn jìn.","vph":"Chiểu tiên lí chi chảng hẩn chin.","vi":"Khách sạn rất gần sân bay.","hl":["很"],"tokens":["酒店","离","机场","很","近"]},{"t":"这里的东西都很便宜。","ph":"Zhèlǐ de dōngxi dōu hěn piányi.","vph":"Chưa lỉ tơ tung xi tâu hẩn p'ién i.","vi":"Đồ ở đây đều rất rẻ.","hl":["很"],"tokens":["这里","的","东西","都","很","便宜"]}]},{"id":23,"vi":"quá","note":"Dùng 太 + tính từ + 了 để nói 'quá ...' (thường mang ý than phiền hoặc cảm thán). Dạng phủ định 不太 + tính từ nghĩa là 'không ... lắm'.","pivot":{"t":"太","ph":"tài","vph":"thai"},"branches":[{"steps":[{"t":"贵","ph":"guì","vph":"quây","vi":"đắt","hl":[]},{"t":"太贵了","ph":"tài guì le","vph":"thai quây lơ","vi":"đắt quá","hl":["太","了"]},{"t":"这个太贵了。","ph":"Zhège tài guì le.","vph":"Chưa cưa thai quây lơ.","vi":"Cái này đắt quá.","hl":["太","了"],"tokens":["这个","太","贵","了"]}]},{"steps":[{"t":"热","ph":"rè","vph":"rưa","vi":"nóng","hl":[]},{"t":"太热了","ph":"tài rè le","vph":"thai rưa lơ","vi":"nóng quá","hl":["太","了"]},{"t":"今天太热了。","ph":"Jīntiān tài rè le.","vph":"Chin thiên thai rưa lơ.","vi":"Hôm nay nóng quá.","hl":["太","了"],"tokens":["今天","太","热","了"]}]},{"steps":[{"t":"辣","ph":"là","vph":"la","vi":"cay","hl":[]},{"t":"太辣了","ph":"tài là le","vph":"thai la lơ","vi":"cay quá","hl":["太","了"]},{"t":"这个菜太辣了。","ph":"Zhège cài tài là le.","vph":"Chưa cưa chai thai la lơ.","vi":"Món này cay quá.","hl":["太","了"],"tokens":["这个","菜","太","辣","了"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"太"},{"k":"A","t":"Tính từ"},{"k":"P","t":"了"}],"points":["太 + tính từ + 了 = \"quá ...\": \"太贵了\" = Đắt quá.","Thường mang ý than phiền (quá mức) hoặc cảm thán khen ngợi: \"太好了！\" = Tuyệt quá!","不太 + tính từ = \"không ... lắm\", nói giảm nhẹ, lịch sự: \"不太远\" = Không xa lắm.","Khi dùng 不太 thì KHÔNG thêm 了 ở cuối câu."],"mistakes":[{"wrong":"这个贵太。","right":"这个太贵了。","why":"Dịch theo \"đắt quá\" nên đặt 太 sau tính từ; tiếng Trung 太 phải đứng trước, 了 đứng cuối."},{"wrong":"今天不太热了。","right":"今天不太热。","why":"不太 (không ... lắm) không đi với 了 ở cuối câu."}],"compare":"Tiếng Việt nói \"đắt quá\" (quá đứng sau), tiếng Trung nói 太贵了 (太 đứng trước, 了 đứng cuối) — tính từ bị kẹp ở giữa.","tip":"Nhớ kiểu bánh mì kẹp: 太 + tính từ + 了 — tính từ là phần nhân ở giữa!","how":["Kẹp tính từ 贵 giữa 太 và 了 → 太贵了 (đắt quá), rồi đặt chủ ngữ 这个 lên đầu → 这个太贵了。","Kẹp 热 giữa 太...了 → 太热了 (nóng quá), rồi đặt 今天 (hôm nay) lên đầu → 今天太热了。","Kẹp 辣 giữa 太...了 → 太辣了 (cay quá), rồi đặt chủ ngữ 这个菜 lên đầu → 这个菜太辣了。"],"dialog":[{"who":"A","t":"这件衣服多少钱？","ph":"Zhè jiàn yīfu duōshao qián?","vph":"Chưa chiên i phu tua sảo chién?","vi":"Cái áo này bao nhiêu tiền?","hl":[]},{"who":"B","t":"五百块。","ph":"Wǔbǎi kuài.","vph":"Ủ pải khoai.","vi":"Năm trăm tệ.","hl":[]},{"who":"A","t":"太贵了！便宜一点吧。","ph":"Tài guì le! Piányi yìdiǎn ba.","vph":"Thai quây lơ! P'ién i i tẻn pa.","vi":"Đắt quá! Bớt chút đi.","hl":["太","了"]},{"who":"B","t":"四百，不太贵吧？","ph":"Sìbǎi, bú tài guì ba?","vph":"Sư pải, pú thai quây pa?","vi":"Bốn trăm, không đắt lắm chứ?","hl":["不太"]}],"more":[{"t":"太好了！","ph":"Tài hǎo le!","vph":"Thai hảo lơ!","vi":"Tuyệt quá!","hl":["太","了"],"tokens":["太","好","了"]},{"t":"我太累了。","ph":"Wǒ tài lèi le.","vph":"Ủa thai lây lơ.","vi":"Tôi mệt quá.","hl":["太","了"],"tokens":["我","太","累","了"]},{"t":"这里太远了。","ph":"Zhèlǐ tài yuǎn le.","vph":"Chưa lỉ thai doẻn lơ.","vi":"Chỗ này xa quá.","hl":["太","了"],"tokens":["这里","太","远","了"]},{"t":"这个菜不太辣。","ph":"Zhège cài bú tài là.","vph":"Chưa cưa chai pú thai la.","vi":"Món này không cay lắm.","hl":["不太"],"tokens":["这个","菜","不","太","辣"]},{"t":"今天的天气太冷了。","ph":"Jīntiān de tiānqì tài lěng le.","vph":"Chin thiên tơ thiên chi thai lẩng lơ.","vi":"Thời tiết hôm nay lạnh quá.","hl":["太","了"],"tokens":["今天","的","天气","太","冷","了"]},{"t":"你说得太快了。","ph":"Nǐ shuō de tài kuài le.","vph":"Nỉ sua tơ thai khoai lơ.","vi":"Bạn nói nhanh quá.","hl":["太","了"],"tokens":["你","说","得","太","快","了"]}]},{"id":24,"vi":"hơn","note":"Câu so sánh hơn: A + 比 + B + tính từ (tính từ đứng cuối, không dùng 很). Có thể thêm 一点 (một chút) hoặc 多了 (nhiều) sau tính từ.","pivot":{"t":"比","ph":"bǐ","vph":"pỉ"},"branches":[{"steps":[{"t":"高","ph":"gāo","vph":"cao","vi":"cao","hl":[]},{"t":"比我高","ph":"bǐ wǒ gāo","vph":"pỉ ủa cao","vi":"cao hơn tôi","hl":["比"]},{"t":"哥哥比我高。","ph":"Gēge bǐ wǒ gāo.","vph":"Cưa cơ pỉ ủa cao.","vi":"Anh trai cao hơn tôi.","hl":["比"],"tokens":["哥哥","比","我","高"]}]},{"steps":[{"t":"便宜","ph":"piányi","vph":"p'ién i","vi":"rẻ","hl":[]},{"t":"比这个便宜","ph":"bǐ zhège piányi","vph":"pỉ chưa cưa p'ién i","vi":"rẻ hơn cái này","hl":["比"]},{"t":"那个比这个便宜。","ph":"Nàge bǐ zhège piányi.","vph":"Na cưa pỉ chưa cưa p'ién i.","vi":"Cái kia rẻ hơn cái này.","hl":["比"],"tokens":["那个","比","这个","便宜"]}]},{"steps":[{"t":"热","ph":"rè","vph":"rưa","vi":"nóng","hl":[]},{"t":"比昨天热","ph":"bǐ zuótiān rè","vph":"pỉ chúa thiên rưa","vi":"nóng hơn hôm qua","hl":["比"]},{"t":"今天比昨天热。","ph":"Jīntiān bǐ zuótiān rè.","vph":"Chin thiên pỉ chúa thiên rưa.","vi":"Hôm nay nóng hơn hôm qua.","hl":["比"],"tokens":["今天","比","昨天","热"]}]}],"formula":[{"k":"S","t":"A (người/vật 1)"},{"k":"P","t":"比"},{"k":"O","t":"B (người/vật 2)"},{"k":"A","t":"Tính từ"}],"points":["Mẫu so sánh hơn: A + 比 + B + tính từ: \"他比我高\" = Anh ấy cao hơn tôi.","Không dùng 很 / 非常 trước tính từ trong câu 比: nói \"今天比昨天热\", không nói \"今天比昨天很热\".","Muốn nói hơn một chút / hơn nhiều thì thêm 一点 hoặc 多了 sau tính từ: \"贵一点\", \"贵多了\".","Phủ định thường dùng 没有: A + 没有 + B + tính từ = A không bằng B (\"我没有他高\")."],"mistakes":[{"wrong":"我高比他。","right":"我比他高。","why":"Dịch theo \"cao hơn anh ấy\" làm sai trật tự; 比 + B phải đứng trước tính từ."},{"wrong":"他比我很高。","right":"他比我高多了。","why":"Câu 比 không dùng 很; muốn nhấn mạnh thì thêm 多了 sau tính từ."}],"compare":"Tiếng Việt: A + tính từ + hơn + B (\"cao hơn tôi\"); tiếng Trung đưa \"比 + B\" lên TRƯỚC tính từ: A + 比 B + tính từ.","tip":"Hãy nghĩ 比 = \"so với\": \"anh ấy so với tôi thì cao\" = 他比我高 — thuận miệng ngay!","how":["Ghép 比 + 我 trước tính từ 高 → 比我高 (cao hơn tôi), rồi đặt 哥哥 lên đầu → 哥哥比我高。","Ghép 比 + 这个 trước 便宜 → 比这个便宜 (rẻ hơn cái này), rồi đặt 那个 lên đầu → 那个比这个便宜。","Ghép 比 + 昨天 trước 热 → 比昨天热 (nóng hơn hôm qua), rồi đặt 今天 lên đầu → 今天比昨天热。"],"dialog":[{"who":"A","t":"坐地铁还是坐出租车？","ph":"Zuò dìtiě háishi zuò chūzūchē?","vph":"Chua ti thiể hái sư chua chu chu chưa?","vi":"Đi tàu điện ngầm hay đi taxi?","hl":[]},{"who":"B","t":"地铁比出租车便宜。","ph":"Dìtiě bǐ chūzūchē piányi.","vph":"Ti thiể pỉ chu chu chưa p'ién i.","vi":"Tàu điện rẻ hơn taxi.","hl":["比"]},{"who":"A","t":"可是出租车比地铁快。","ph":"Kěshì chūzūchē bǐ dìtiě kuài.","vph":"Khửa sư chu chu chưa pỉ ti thiể khoai.","vi":"Nhưng taxi nhanh hơn tàu điện.","hl":["比"]},{"who":"B","t":"现在堵车，地铁快多了。","ph":"Xiànzài dǔchē, dìtiě kuài duō le.","vph":"Xiên chai tủ chưa, ti thiể khoai tua lơ.","vi":"Giờ đang tắc đường, tàu điện nhanh hơn nhiều.","hl":[]}],"more":[{"t":"我比他大。","ph":"Wǒ bǐ tā dà.","vph":"Ủa pỉ tha ta.","vi":"Tôi lớn tuổi hơn anh ấy.","hl":["比"],"tokens":["我","比","他","大"]},{"t":"这个比那个好。","ph":"Zhège bǐ nàge hǎo.","vph":"Chưa cưa pỉ na cưa hảo.","vi":"Cái này tốt hơn cái kia.","hl":["比"],"tokens":["这个","比","那个","好"]},{"t":"他比我高一点。","ph":"Tā bǐ wǒ gāo yìdiǎn.","vph":"Tha pỉ ủa cao i tẻn.","vi":"Anh ấy cao hơn tôi một chút.","hl":["比"],"tokens":["他","比","我","高","一点"]},{"t":"坐飞机比坐火车快。","ph":"Zuò fēijī bǐ zuò huǒchē kuài.","vph":"Chua phây chi pỉ chua hủa chưa khoai.","vi":"Đi máy bay nhanh hơn đi tàu hỏa.","hl":["比"],"tokens":["坐","飞机","比","坐","火车","快"]},{"t":"北京比河内冷多了。","ph":"Běijīng bǐ Hénèi lěng duō le.","vph":"Pẩy chinh pỉ Hứa nây lẩng tua lơ.","vi":"Bắc Kinh lạnh hơn Hà Nội nhiều.","hl":["比"],"tokens":["北京","比","河内","冷","多","了"]},{"t":"她的中文比我好多了。","ph":"Tā de Zhōngwén bǐ wǒ hǎo duō le.","vph":"Tha tơ Chung uấn pỉ ủa hảo tua lơ.","vi":"Tiếng Trung của cô ấy giỏi hơn tôi nhiều.","hl":["比"],"tokens":["她","的","中文","比","我","好","多","了"]}]},{"id":25,"vi":"nhất","note":"Đặt 最 trước tính từ hoặc động từ chỉ cảm xúc để diễn tả mức cao nhất: 最 + tính từ / 最喜欢.","pivot":{"t":"最","ph":"zuì","vph":"chuây"},"branches":[{"steps":[{"t":"好吃","ph":"hǎochī","vph":"hảo chư","vi":"ngon","hl":[]},{"t":"最好吃","ph":"zuì hǎochī","vph":"chuây hảo chư","vi":"ngon nhất","hl":["最"]},{"t":"这个菜最好吃。","ph":"Zhège cài zuì hǎochī.","vph":"Chưa cưa chai chuây hảo chư.","vi":"Món này ngon nhất.","hl":["最"],"tokens":["这个","菜","最","好吃"]}]},{"steps":[{"t":"喜欢","ph":"xǐhuan","vph":"xỉ hoan","vi":"thích","hl":[]},{"t":"最喜欢","ph":"zuì xǐhuan","vph":"chuây xỉ hoan","vi":"thích nhất","hl":["最"]},{"t":"我最喜欢喝茶。","ph":"Wǒ zuì xǐhuan hē chá.","vph":"Ủa chuây xỉ hoan hưa chá.","vi":"Tôi thích uống trà nhất.","hl":["最"],"tokens":["我","最","喜欢","喝","茶"]}]},{"steps":[{"t":"便宜","ph":"piányi","vph":"p'ién i","vi":"rẻ","hl":[]},{"t":"最便宜","ph":"zuì piányi","vph":"chuây p'ién i","vi":"rẻ nhất","hl":["最"]},{"t":"哪个最便宜？","ph":"Nǎge zuì piányi?","vph":"Nả cưa chuây p'ién i?","vi":"Cái nào rẻ nhất?","hl":["最"],"tokens":["哪个","最","便宜"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"最"},{"k":"A","t":"Tính từ / Động từ cảm xúc"}],"points":["最 đứng trước tính từ: \"最好\" = tốt nhất, \"最便宜\" = rẻ nhất.","最 cũng đứng trước động từ chỉ cảm xúc, sở thích: \"我最喜欢\", \"我最怕\".","Hỏi \"cái nào ... nhất\" dùng 哪个最 + tính từ: \"哪个最好吃？\".","Không đặt 最 sau tính từ và không thêm 很: nói \"最大\", không nói \"大最\" hay \"很最大\"."],"mistakes":[{"wrong":"这个好吃最。","right":"这个最好吃。","why":"Dịch theo \"ngon nhất\" nên đặt 最 phía sau; tiếng Trung 最 luôn đứng trước tính từ."},{"wrong":"我喜欢最喝茶。","right":"我最喜欢喝茶。","why":"最 phải đứng trước động từ 喜欢, không chen vào sau nó."}],"compare":"Tiếng Việt: tính từ + \"nhất\" (\"đẹp nhất\"); tiếng Trung: 最 + tính từ (最漂亮) — vị trí đảo ngược.","tip":"最 là \"số 1\" nên luôn đứng đầu — đứng TRƯỚC tính từ!","how":["Thêm 最 trước tính từ 好吃 → 最好吃 (ngon nhất), rồi đặt chủ ngữ 这个菜 lên đầu → 这个菜最好吃。","Thêm 最 trước động từ 喜欢 → 最喜欢 (thích nhất), rồi thêm chủ ngữ 我 ở đầu và việc thích 喝茶 ở sau → 我最喜欢喝茶。","Thêm 最 trước 便宜 → 最便宜 (rẻ nhất), rồi đặt từ hỏi 哪个 (cái nào) lên đầu → 哪个最便宜？"],"dialog":[{"who":"A","t":"这里什么菜最好吃？","ph":"Zhèlǐ shénme cài zuì hǎochī?","vph":"Chưa lỉ sấn mơ chai chuây hảo chư?","vi":"Ở đây món gì ngon nhất?","hl":["最"]},{"who":"B","t":"烤鸭最有名。","ph":"Kǎoyā zuì yǒumíng.","vph":"Khảo da chuây dẩu mính.","vi":"Vịt quay nổi tiếng nhất.","hl":["最"]},{"who":"A","t":"那就来一只吧。","ph":"Nà jiù lái yì zhī ba.","vph":"Na chiêu lái i chư pa.","vi":"Vậy cho một con nhé.","hl":[]}],"more":[{"t":"他最高。","ph":"Tā zuì gāo.","vph":"Tha chuây cao.","vi":"Anh ấy cao nhất.","hl":["最"],"tokens":["他","最","高"]},{"t":"我最喜欢夏天。","ph":"Wǒ zuì xǐhuan xiàtiān.","vph":"Ủa chuây xỉ hoan xa thiên.","vi":"Tôi thích mùa hè nhất.","hl":["最"],"tokens":["我","最","喜欢","夏天"]},{"t":"坐地铁最方便。","ph":"Zuò dìtiě zuì fāngbiàn.","vph":"Chua ti thiể chuây phang piên.","vi":"Đi tàu điện ngầm là tiện nhất.","hl":["最"],"tokens":["坐","地铁","最","方便"]},{"t":"你最想去哪儿？","ph":"Nǐ zuì xiǎng qù nǎr?","vph":"Nỉ chuây xẻng chuy nả?","vi":"Bạn muốn đi đâu nhất?","hl":["最"],"tokens":["你","最","想","去","哪儿"]},{"t":"这是最大的房间。","ph":"Zhè shì zuì dà de fángjiān.","vph":"Chưa sư chuây ta tơ pháng chiên.","vi":"Đây là phòng lớn nhất.","hl":["最"],"tokens":["这","是","最","大","的","房间"]},{"t":"这是我们店最好的茶。","ph":"Zhè shì wǒmen diàn zuì hǎo de chá.","vph":"Chưa sư ủa mân tiên chuây hảo tơ chá.","vi":"Đây là loại trà ngon nhất của tiệm chúng tôi.","hl":["最"],"tokens":["这","是","我们","店","最","好","的","茶"]}]},{"id":26,"vi":"cũng","note":"也 luôn đứng sau chủ ngữ và trước động từ/tính từ: Chủ ngữ + 也 + động từ. Phủ định là 也不 / 也没.","pivot":{"t":"也","ph":"yě","vph":"dể"},"branches":[{"steps":[{"t":"是","ph":"shì","vph":"sư","vi":"là","hl":[]},{"t":"也是","ph":"yě shì","vph":"dể sư","vi":"cũng là","hl":["也"]},{"t":"我也是越南人。","ph":"Wǒ yě shì Yuènánrén.","vph":"Ủa dể sư Duê nán rấn.","vi":"Tôi cũng là người Việt Nam.","hl":["也"],"tokens":["我","也","是","越南人"]}]},{"steps":[{"t":"去","ph":"qù","vph":"chuy","vi":"đi","hl":[]},{"t":"也去","ph":"yě qù","vph":"dể chuy","vi":"cũng đi","hl":["也"]},{"t":"我们也去吧。","ph":"Wǒmen yě qù ba.","vph":"Ủa mân dể chuy pa.","vi":"Chúng ta cũng đi nhé.","hl":["也"],"tokens":["我们","也","去","吧"]}]},{"steps":[{"t":"知道","ph":"zhīdào","vph":"chư tao","vi":"biết","hl":[]},{"t":"也不知道","ph":"yě bù zhīdào","vph":"dể pu chư tao","vi":"cũng không biết","hl":["也"]},{"t":"我也不知道。","ph":"Wǒ yě bù zhīdào.","vph":"Ủa dể pu chư tao.","vi":"Tôi cũng không biết.","hl":["也"],"tokens":["我","也","不","知道"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"也"},{"k":"V","t":"Động từ / Tính từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["也 đứng sau chủ ngữ, trước động từ hoặc tính từ: \"我也去\" = Tôi cũng đi.","Phủ định: 也不 / 也没 (也 đứng trước 不, 没): \"我也不知道\" = Tôi cũng không biết.","Trả lời nhanh \"tôi cũng vậy\" bằng \"我也是\".","Không đặt 也 ở cuối câu hay trước chủ ngữ: nói \"他也喝\", không nói \"他喝也\"."],"mistakes":[{"wrong":"我不也去。","right":"我也不去。","why":"也 phải đứng trước 不: \"cũng không\" = 也不, đúng thứ tự như tiếng Việt."},{"wrong":"我去也。","right":"我也去。","why":"Không đặt 也 ở cuối câu như \"nữa\"; 也 phải đứng trước động từ."}],"compare":"Rất giống tiếng Việt: \"Tôi cũng đi\" = 我也去, cùng vị trí. Khác: tiếng Việt có thể nói \"Tôi đi nữa\", còn tiếng Trung luôn dùng 也 trước động từ.","tip":"也 = \"cũng\" — đặt y như tiếng Việt: sau chủ ngữ, trước động từ, khỏi nghĩ!","how":["Thêm 也 trước động từ 是 → 也是 (cũng là), rồi thêm chủ ngữ 我 ở đầu và 越南人 ở cuối → 我也是越南人。","Thêm 也 trước 去 → 也去 (cũng đi), rồi đặt chủ ngữ 我们 lên đầu và thêm 吧 cuối câu để rủ rê → 我们也去吧。","Thêm 也不 trước 知道 → 也不知道 (cũng không biết), rồi đặt chủ ngữ 我 lên đầu → 我也不知道。"],"dialog":[{"who":"A","t":"我是越南人，你呢？","ph":"Wǒ shì Yuènánrén, nǐ ne?","vph":"Ủa sư Duê nán rấn, nỉ nơ?","vi":"Tôi là người Việt Nam, còn bạn?","hl":[]},{"who":"B","t":"我也是！你也来旅游吗？","ph":"Wǒ yě shì! Nǐ yě lái lǚyóu ma?","vph":"Ủa dể sư! Nỉ dể lái lủy dấu ma?","vi":"Tôi cũng vậy! Bạn cũng đến du lịch à?","hl":["也"]},{"who":"A","t":"不，我来出差。","ph":"Bù, wǒ lái chūchāi.","vph":"Pu, ủa lái chu chai.","vi":"Không, tôi đến công tác.","hl":[]},{"who":"B","t":"我也是来出差的。","ph":"Wǒ yě shì lái chūchāi de.","vph":"Ủa dể sư lái chu chai tơ.","vi":"Tôi cũng đến công tác.","hl":["也"]}],"more":[{"t":"他也喝咖啡。","ph":"Tā yě hē kāfēi.","vph":"Tha dể hưa kha phây.","vi":"Anh ấy cũng uống cà phê.","hl":["也"],"tokens":["他","也","喝","咖啡"]},{"t":"我也很忙。","ph":"Wǒ yě hěn máng.","vph":"Ủa dể hẩn máng.","vi":"Tôi cũng rất bận.","hl":["也"],"tokens":["我","也","很","忙"]},{"t":"她也没去。","ph":"Tā yě méi qù.","vph":"Tha dể mấy chuy.","vi":"Cô ấy cũng không đi.","hl":["也"],"tokens":["她","也","没","去"]},{"t":"我也想学中文。","ph":"Wǒ yě xiǎng xué Zhōngwén.","vph":"Ủa dể xẻng xuế Chung uấn.","vi":"Tôi cũng muốn học tiếng Trung.","hl":["也"],"tokens":["我","也","想","学","中文"]},{"t":"这家酒店也很好。","ph":"Zhè jiā jiǔdiàn yě hěn hǎo.","vph":"Chưa cha chiểu tiên dể hẩn hảo.","vi":"Khách sạn này cũng rất tốt.","hl":["也"],"tokens":["这","家","酒店","也","很","好"]},{"t":"明天我们也要早起。","ph":"Míngtiān wǒmen yě yào zǎo qǐ.","vph":"Mính thiên ủa mân dể dao chảo chỉ.","vi":"Ngày mai chúng ta cũng phải dậy sớm.","hl":["也"],"tokens":["明天","我们","也","要","早","起"]}]},{"id":27,"vi":"và","note":"和 nối hai danh từ hoặc đại từ: A 和 B. Không dùng 和 để nối hai mệnh đề; khi đó dùng 而且 hoặc 还. Văn nói cũng hay dùng 跟.","pivot":{"t":"和","ph":"hé","vph":"hứa"},"branches":[{"steps":[{"t":"茶","ph":"chá","vph":"chá","vi":"trà","hl":[]},{"t":"咖啡和茶","ph":"kāfēi hé chá","vph":"kha phây hứa chá","vi":"cà phê và trà","hl":["和"]},{"t":"我要咖啡和茶。","ph":"Wǒ yào kāfēi hé chá.","vph":"Ủa dao kha phây hứa chá.","vi":"Tôi muốn cà phê và trà.","hl":["和"],"tokens":["我","要","咖啡","和","茶"]}]},{"steps":[{"t":"妈妈","ph":"māma","vph":"ma ma","vi":"mẹ","hl":[]},{"t":"爸爸和妈妈","ph":"bàba hé māma","vph":"pa pa hứa ma ma","vi":"bố và mẹ","hl":["和"]},{"t":"爸爸和妈妈都在家。","ph":"Bàba hé māma dōu zài jiā.","vph":"Pa pa hứa ma ma tâu chai cha.","vi":"Bố và mẹ đều ở nhà.","hl":["和"],"tokens":["爸爸","和","妈妈","都","在","家"]}]},{"steps":[{"t":"机票","ph":"jīpiào","vph":"chi p'eo","vi":"vé máy bay","hl":[]},{"t":"护照和机票","ph":"hùzhào hé jīpiào","vph":"hu chao hứa chi p'eo","vi":"hộ chiếu và vé máy bay","hl":["和"]},{"t":"请给我护照和机票。","ph":"Qǐng gěi wǒ hùzhào hé jīpiào.","vph":"Chỉnh cẩy ủa hu chao hứa chi p'eo.","vi":"Vui lòng đưa tôi hộ chiếu và vé máy bay.","hl":["和"],"tokens":["请","给","我","护照","和","机票"]}]}],"formula":[{"k":"S","t":"(Chủ ngữ)"},{"k":"V","t":"(Động từ)"},{"k":"O","t":"Danh từ A"},{"k":"P","t":"和"},{"k":"O","t":"Danh từ B"}],"points":["和 nối hai danh từ hoặc đại từ: \"我和你\" = tôi và bạn, \"咖啡和茶\" = cà phê và trà.","Không dùng 和 nối hai tính từ hay hai câu: \"vừa mệt vừa đói\" nói \"又累又饿\", không nói \"累和饿\".","Liệt kê nhiều thứ thì chỉ đặt 和 trước món cuối, các món trước ngăn bằng dấu 、: \"苹果、香蕉和西瓜\".","Hai chủ ngữ nối bằng 和 hay đi với 都 (đều): \"我和他都是学生\"."],"mistakes":[{"wrong":"我很累和很饿。","right":"我又累又饿。","why":"和 không nối hai tính từ hay hai mệnh đề như chữ \"và\" tiếng Việt; dùng 又...又...."},{"wrong":"我和他是都学生。","right":"我和他都是学生。","why":"都 (đều) phải đứng trước động từ 是."}],"compare":"Giống tiếng Việt khi nối hai danh từ (\"bố và mẹ\" = 爸爸和妈妈). Khác: chữ \"và\" tiếng Việt nối được cả hai câu, còn 和 chỉ nối danh từ, đại từ.","tip":"和 chỉ \"nắm tay\" danh từ với danh từ — động từ và tính từ không chơi cùng!","how":["Nối 咖啡 với 茶 bằng 和 → 咖啡和茶 (cà phê và trà), rồi thêm 我要 (tôi muốn) phía trước → 我要咖啡和茶。","Nối 爸爸 với 妈妈 bằng 和 → 爸爸和妈妈 (bố và mẹ), rồi thêm 都在家 (đều ở nhà) phía sau → 爸爸和妈妈都在家。","Nối 护照 với 机票 bằng 和 → 护照和机票 (hộ chiếu và vé máy bay), rồi thêm 请给我 (xin đưa tôi) phía trước → 请给我护照和机票。"],"dialog":[{"who":"A","t":"你们几位？","ph":"Nǐmen jǐ wèi?","vph":"Nỉ mân chỉ uây?","vi":"Các bạn mấy người?","hl":[]},{"who":"B","t":"两位，我和我朋友。","ph":"Liǎng wèi, wǒ hé wǒ péngyou.","vph":"Lẻng uây, ủa hứa ủa p'ấng dâu.","vi":"Hai người, tôi và bạn tôi.","hl":["和"]},{"who":"A","t":"要喝什么？","ph":"Yào hē shénme?","vph":"Dao hưa sấn mơ?","vi":"Uống gì ạ?","hl":[]},{"who":"B","t":"一杯咖啡和一杯茶。","ph":"Yì bēi kāfēi hé yì bēi chá.","vph":"I pây kha phây hứa i pây chá.","vi":"Một ly cà phê và một ly trà.","hl":["和"]}],"more":[{"t":"我和你一起去。","ph":"Wǒ hé nǐ yìqǐ qù.","vph":"Ủa hứa nỉ i chỉ chuy.","vi":"Tôi và bạn cùng đi.","hl":["和"],"tokens":["我","和","你","一起","去"]},{"t":"我喜欢猫和狗。","ph":"Wǒ xǐhuan māo hé gǒu.","vph":"Ủa xỉ hoan mao hứa cẩu.","vi":"Tôi thích mèo và chó.","hl":["和"],"tokens":["我","喜欢","猫","和","狗"]},{"t":"我去过北京和上海。","ph":"Wǒ qùguo Běijīng hé Shànghǎi.","vph":"Ủa chuy cua Pẩy chinh hứa Sang hải.","vi":"Tôi từng đi Bắc Kinh và Thượng Hải.","hl":["和"],"tokens":["我","去过","北京","和","上海"]},{"t":"我和他都是学生。","ph":"Wǒ hé tā dōu shì xuésheng.","vph":"Ủa hứa tha tâu sư xuế sâng.","vi":"Tôi và anh ấy đều là sinh viên.","hl":["和"],"tokens":["我","和","他","都","是","学生"]},{"t":"老师和学生都来了。","ph":"Lǎoshī hé xuésheng dōu lái le.","vph":"Lảo sư hứa xuế sâng tâu lái lơ.","vi":"Thầy và trò đều đến rồi.","hl":["和"],"tokens":["老师","和","学生","都","来","了"]},{"t":"我要米饭和一碗汤。","ph":"Wǒ yào mǐfàn hé yì wǎn tāng.","vph":"Ủa dao mỉ phan hứa i oản thang.","vi":"Tôi muốn cơm trắng và một bát canh.","hl":["和"],"tokens":["我","要","米饭","和","一","碗","汤"]}]},{"id":28,"vi":"nhưng","note":"但是 (hoặc 可是, 不过) đứng đầu vế sau để nêu ý trái ngược: ..., 但是 .... Vế trước có thể dùng 虽然 (tuy).","pivot":{"t":"但是","ph":"dànshì","vph":"tan sư"},"branches":[{"steps":[{"t":"贵","ph":"guì","vph":"quây","vi":"đắt","hl":[]},{"t":"但是很贵","ph":"dànshì hěn guì","vph":"tan sư hẩn quây","vi":"nhưng rất đắt","hl":["但是"]},{"t":"这个很好，但是很贵。","ph":"Zhège hěn hǎo, dànshì hěn guì.","vph":"Chưa cưa hẩn hảo, tan sư hẩn quây.","vi":"Cái này tốt nhưng rất đắt.","hl":["但是"],"tokens":["这个","很","好","但是","很","贵"]}]},{"steps":[{"t":"时间","ph":"shíjiān","vph":"sứ chiên","vi":"thời gian","hl":[]},{"t":"但是没时间","ph":"dànshì méi shíjiān","vph":"tan sư mấy sứ chiên","vi":"nhưng không có thời gian","hl":["但是"]},{"t":"我想去，但是没时间。","ph":"Wǒ xiǎng qù, dànshì méi shíjiān.","vph":"Ủa xẻng chuy, tan sư mấy sứ chiên.","vi":"Tôi muốn đi nhưng không có thời gian.","hl":["但是"],"tokens":["我","想","去","但是","没","时间"]}]},{"steps":[{"t":"开心","ph":"kāixīn","vph":"khai xin","vi":"vui","hl":[]},{"t":"但是很开心","ph":"dànshì hěn kāixīn","vph":"tan sư hẩn khai xin","vi":"nhưng rất vui","hl":["但是"]},{"t":"很累，但是很开心。","ph":"Hěn lèi, dànshì hěn kāixīn.","vph":"Hẩn lây, tan sư hẩn khai xin.","vi":"Mệt nhưng rất vui.","hl":["但是"],"tokens":["很","累","但是","很","开心"]}]}],"formula":[{"k":"X","t":"(Tuy) Vế 1"},{"k":"P","t":"但是"},{"k":"X","t":"Vế 2 (ý trái ngược)"}],"points":["但是 đứng đầu vế sau để nêu ý trái ngược: \"很好吃，但是很贵\" = Ngon nhưng đắt.","Có thể dùng cặp 虽然...但是... = tuy... nhưng...: \"虽然很累，但是很开心\".","可是 và 不过 cũng nghĩa là \"nhưng\"; 不过 nhẹ nhàng hơn, hay dùng trong văn nói.","但是 đứng ĐẦU vế sau, trước cả chủ ngữ của vế đó: \"...，但是我没时间\"."],"mistakes":[{"wrong":"我想去，我但是没时间。","right":"我想去，但是我没时间。","why":"但是 đứng đầu vế, trước chủ ngữ — không chen vào giữa chủ ngữ và động từ."},{"wrong":"虽然很贵，很好吃。","right":"虽然很贵，但是很好吃。","why":"Đã có 虽然 (tuy) thì vế sau nên có 但是 / 可是 đi kèm cho trọn ý."}],"compare":"Giống hệt tiếng Việt: \"nhưng\" đứng đầu vế sau, cặp \"tuy... nhưng...\" = 虽然...但是.... Tiếng Trung cũng hay dùng cả cặp như tiếng Việt.","tip":"但是 = \"nhưng\" — cứ đặt y vị trí tiếng Việt, nhớ cặp đôi \"tuy – nhưng\" = 虽然 – 但是!","how":["Thêm 但是 trước 很贵 → 但是很贵 (nhưng rất đắt), rồi đặt vế khen 这个很好 lên trước, ngăn bằng dấu phẩy → 这个很好，但是很贵。","Thêm 但是 trước 没时间 → 但是没时间 (nhưng không có thời gian), rồi đặt vế 我想去 lên trước → 我想去，但是没时间。","Thêm 但是 trước 很开心 → 但是很开心 (nhưng rất vui), rồi đặt vế 很累 (rất mệt) lên trước → 很累，但是很开心。"],"dialog":[{"who":"A","t":"这家餐厅怎么样？","ph":"Zhè jiā cāntīng zěnmeyàng?","vph":"Chưa cha chan thinh chẩn mơ dang?","vi":"Nhà hàng này thế nào?","hl":[]},{"who":"B","t":"菜很好吃，但是有点儿贵。","ph":"Cài hěn hǎochī, dànshì yǒudiǎnr guì.","vph":"Chai hẩn hảo chư, tan sư dẩu tẻn quây.","vi":"Món ăn rất ngon nhưng hơi đắt.","hl":["但是"]},{"who":"A","t":"我想去，可是没订位。","ph":"Wǒ xiǎng qù, kěshì méi dìng wèi.","vph":"Ủa xẻng chuy, khửa sư mấy tinh uây.","vi":"Tôi muốn đi nhưng chưa đặt chỗ.","hl":["可是"]},{"who":"B","t":"不过晚上人不多。","ph":"Búguò wǎnshang rén bù duō.","vph":"Pú cua oản sang rấn pu tua.","vi":"Có điều buổi tối không đông người.","hl":["不过"]}],"more":[{"t":"我想买，但是没钱。","ph":"Wǒ xiǎng mǎi, dànshì méi qián.","vph":"Ủa xẻng mải, tan sư mấy chién.","vi":"Tôi muốn mua nhưng không có tiền.","hl":["但是"],"tokens":["我","想","买","但是","没","钱"]},{"t":"很便宜，但是不好吃。","ph":"Hěn piányi, dànshì bù hǎochī.","vph":"Hẩn p'ién i, tan sư pu hảo chư.","vi":"Rẻ nhưng không ngon.","hl":["但是"],"tokens":["很","便宜","但是","不","好吃"]},{"t":"我听懂了，可是不会说。","ph":"Wǒ tīngdǒng le, kěshì bú huì shuō.","vph":"Ủa thinh tủng lơ, khửa sư pú huây sua.","vi":"Tôi nghe hiểu rồi nhưng không biết nói.","hl":["可是"],"tokens":["我","听懂","了","可是","不","会","说"]},{"t":"外面很冷，但是屋里很暖和。","ph":"Wàimiàn hěn lěng, dànshì wūli hěn nuǎnhuo.","vph":"Oai miên hẩn lẩng, tan sư u li hẩn noản hua.","vi":"Bên ngoài lạnh nhưng trong nhà rất ấm.","hl":["但是"],"tokens":["外面","很","冷","但是","屋里","很","暖和"]},{"t":"虽然很远，但是很值得去。","ph":"Suīrán hěn yuǎn, dànshì hěn zhíde qù.","vph":"Xuây rán hẩn doẻn, tan sư hẩn chứ tơ chuy.","vi":"Tuy xa nhưng rất đáng đi.","hl":["虽然","但是"],"tokens":["虽然","很","远","但是","很","值得","去"]},{"t":"虽然下雨了，但是我们还是去了。","ph":"Suīrán xiàyǔ le, dànshì wǒmen háishi qù le.","vph":"Xuây rán xa dủy lơ, tan sư ủa mân hái sư chuy lơ.","vi":"Tuy trời mưa nhưng chúng tôi vẫn đi.","hl":["虽然","但是"],"tokens":["虽然","下雨","了","但是","我们","还是","去","了"]}]},{"id":29,"vi":"nếu","note":"Câu điều kiện: 如果 + điều kiện, (chủ ngữ) + 就 + kết quả; 就 đứng sau chủ ngữ của vế sau. Văn nói có thể dùng 要是 thay cho 如果.","pivot":{"t":"如果","ph":"rúguǒ","vph":"rú của"},"branches":[{"steps":[{"t":"下雨","ph":"xiàyǔ","vph":"xa dủy","vi":"mưa","hl":[]},{"t":"如果下雨","ph":"rúguǒ xiàyǔ","vph":"rú của xa dủy","vi":"nếu trời mưa","hl":["如果"]},{"t":"如果下雨，我就不去。","ph":"Rúguǒ xiàyǔ, wǒ jiù bú qù.","vph":"Rú của xa dủy, ủa chiêu pú chuy.","vi":"Nếu trời mưa thì tôi không đi.","hl":["如果","就"],"tokens":["如果","下雨","我","就","不","去"]}]},{"steps":[{"t":"有空","ph":"yǒukòng","vph":"dẩu khung","vi":"rảnh","hl":[]},{"t":"如果有空","ph":"rúguǒ yǒukòng","vph":"rú của dẩu khung","vi":"nếu rảnh","hl":["如果"]},{"t":"如果有空就来玩吧。","ph":"Rúguǒ yǒukòng jiù lái wán ba.","vph":"Rú của dẩu khung chiêu lái oán pa.","vi":"Nếu rảnh thì đến chơi nhé.","hl":["如果","就"],"tokens":["如果","有空","就","来","玩","吧"]}]},{"steps":[{"t":"需要","ph":"xūyào","vph":"xuy dao","vi":"cần","hl":[]},{"t":"如果需要","ph":"rúguǒ xūyào","vph":"rú của xuy dao","vi":"nếu cần","hl":["如果"]},{"t":"如果需要就叫我。","ph":"Rúguǒ xūyào jiù jiào wǒ.","vph":"Rú của xuy dao chiêu cheo ủa.","vi":"Nếu cần thì gọi tôi.","hl":["如果","就"],"tokens":["如果","需要","就","叫","我"]}]}],"formula":[{"k":"P","t":"如果"},{"k":"X","t":"Điều kiện"},{"k":"S","t":"(Chủ ngữ)"},{"k":"P","t":"就"},{"k":"X","t":"Kết quả"}],"points":["如果 đứng đầu vế điều kiện, vế sau dùng 就 để nêu kết quả: \"如果下雨，我就不去\".","就 đứng SAU chủ ngữ của vế sau, trước động từ: \"我就不去\", không nói \"就我不去\".","Văn nói hay dùng 要是 thay cho 如果: \"要是你累了，就休息吧\".","Có thể thêm 的话 ở cuối vế điều kiện cho tự nhiên: \"如果有空的话\"."],"mistakes":[{"wrong":"如果下雨，就我不去。","right":"如果下雨，我就不去。","why":"Tiếng Việt nói \"thì tôi không đi\" nên hay đặt 就 trước chủ ngữ; tiếng Trung 就 phải đứng sau chủ ngữ."},{"wrong":"我不去如果下雨。","right":"如果下雨，我就不去。","why":"Vế điều kiện có 如果 thường đứng trước, không đặt ở cuối câu."}],"compare":"Giống cặp \"nếu... thì...\" tiếng Việt: 如果 = nếu, 就 = thì. Khác: \"thì\" đứng trước chủ ngữ, còn 就 đứng sau chủ ngữ của vế kết quả.","tip":"如果...就... = \"nếu... thì...\" — nhưng 就 lịch sự \"nhường\" chủ ngữ đứng trước mình!","how":["Thêm 如果 trước 下雨 → 如果下雨 (nếu mưa), rồi nối vế kết quả 我就不去 (chủ ngữ 我 trước, 就 sau) → 如果下雨，我就不去。","Thêm 如果 trước 有空 → 如果有空 (nếu rảnh), rồi nối ngay 就来玩吧 (thì đến chơi nhé) → 如果有空就来玩吧。","Thêm 如果 trước 需要 → 如果需要 (nếu cần), rồi nối 就叫我 (thì gọi tôi) → 如果需要就叫我。"],"dialog":[{"who":"A","t":"明天去长城吗？","ph":"Míngtiān qù Chángchéng ma?","vph":"Mính thiên chuy Cháng chấng ma?","vi":"Mai đi Vạn Lý Trường Thành không?","hl":[]},{"who":"B","t":"如果天气好，我就去。","ph":"Rúguǒ tiānqì hǎo, wǒ jiù qù.","vph":"Rú của thiên chi hảo, ủa chiêu chuy.","vi":"Nếu trời đẹp thì tôi đi.","hl":["如果","就"]},{"who":"A","t":"要是下雨呢？","ph":"Yàoshi xiàyǔ ne?","vph":"Dao sư xa dủy nơ?","vi":"Nếu mưa thì sao?","hl":["要是"]},{"who":"B","t":"那就去博物馆吧。","ph":"Nà jiù qù bówùguǎn ba.","vph":"Na chiêu chuy púa u quản pa.","vi":"Thì đi bảo tàng vậy.","hl":["就"]}],"more":[{"t":"如果你去，我就去。","ph":"Rúguǒ nǐ qù, wǒ jiù qù.","vph":"Rú của nỉ chuy, ủa chiêu chuy.","vi":"Nếu bạn đi thì tôi đi.","hl":["如果","就"],"tokens":["如果","你","去","我","就","去"]},{"t":"如果有问题就问我。","ph":"Rúguǒ yǒu wèntí jiù wèn wǒ.","vph":"Rú của dẩu uân thí chiêu uân ủa.","vi":"Nếu có vấn đề thì hỏi tôi.","hl":["如果","就"],"tokens":["如果","有","问题","就","问","我"]},{"t":"要是太贵就别买了。","ph":"Yàoshi tài guì jiù bié mǎi le.","vph":"Dao sư thai quây chiêu pía mải lơ.","vi":"Nếu đắt quá thì đừng mua nữa.","hl":["要是","就"],"tokens":["要是","太","贵","就","别","买","了"]},{"t":"如果你累了就休息吧。","ph":"Rúguǒ nǐ lèi le jiù xiūxi ba.","vph":"Rú của nỉ lây lơ chiêu xiêu xi pa.","vi":"Nếu bạn mệt thì nghỉ đi.","hl":["如果","就"],"tokens":["如果","你","累","了","就","休息","吧"]},{"t":"如果迟到了就给我打电话。","ph":"Rúguǒ chídào le jiù gěi wǒ dǎ diànhuà.","vph":"Rú của chứ tao lơ chiêu cẩy ủa tả tiên hoa.","vi":"Nếu bị muộn thì gọi điện cho tôi.","hl":["如果","就"],"tokens":["如果","迟到","了","就","给","我","打电话"]},{"t":"如果有时间的话，我想去上海。","ph":"Rúguǒ yǒu shíjiān dehuà, wǒ xiǎng qù Shànghǎi.","vph":"Rú của dẩu sứ chiên tơ hoa, ủa xẻng chuy Sang hải.","vi":"Nếu có thời gian thì tôi muốn đi Thượng Hải.","hl":["如果"],"tokens":["如果","有","时间","的话","我","想","去","上海"]}]},{"id":30,"vi":"này / kia","note":"这 (này) và 那 (kia/đó) đứng trước lượng từ + danh từ: 这个菜, 那件衣服. Hỏi 'cái nào' dùng 哪.","pivot":{"t":"这 / 那","ph":"zhè / nà","vph":"chưa / na"},"branches":[{"steps":[{"t":"菜","ph":"cài","vph":"chai","vi":"món ăn","hl":[]},{"t":"这个菜","ph":"zhège cài","vph":"chưa cưa chai","vi":"món này","hl":["这个"]},{"t":"这个菜多少钱？","ph":"Zhège cài duōshao qián?","vph":"Chưa cưa chai tua sảo chién?","vi":"Món này bao nhiêu tiền?","hl":["这个"],"tokens":["这个","菜","多少","钱"]}]},{"steps":[{"t":"人","ph":"rén","vph":"rấn","vi":"người","hl":[]},{"t":"那个人","ph":"nàge rén","vph":"na cưa rấn","vi":"người kia","hl":["那个"]},{"t":"那个人是谁？","ph":"Nàge rén shì shéi?","vph":"Na cưa rấn sư suấy?","vi":"Người kia là ai?","hl":["那个"],"tokens":["那个","人","是","谁"]}]},{"steps":[{"t":"衣服","ph":"yīfu","vph":"i phu","vi":"quần áo","hl":[]},{"t":"那件衣服","ph":"nà jiàn yīfu","vph":"na chiên i phu","vi":"cái áo kia","hl":["那"]},{"t":"我想买那件衣服。","ph":"Wǒ xiǎng mǎi nà jiàn yīfu.","vph":"Ủa xẻng mải na chiên i phu.","vi":"Tôi muốn mua cái áo kia.","hl":["那"],"tokens":["我","想","买","那","件","衣服"]}]}],"formula":[{"k":"P","t":"这 / 那"},{"k":"X","t":"Lượng từ"},{"k":"O","t":"Danh từ"}],"points":["这 = này (gần), 那 = kia / đó (xa); đứng TRƯỚC lượng từ + danh từ: \"这个人\", \"那本书\".","Giữa 这/那 và danh từ thường có lượng từ (个, 件, 杯, 本...): \"这杯咖啡\", \"那件衣服\"; không chắc thì dùng 个.","这 / 那 đứng một mình làm chủ ngữ: \"这是我的\" = Cái này là của tôi, \"那是什么？\" = Kia là gì?","Hỏi \"cái nào\" dùng 哪 + lượng từ: \"哪个？\"; nơi chốn: 这里 (đây), 那里 (đó)."],"mistakes":[{"wrong":"人那个是谁？","right":"那个人是谁？","why":"Tiếng Việt nói \"người kia\" (kia đứng sau), tiếng Trung 那个 phải đứng trước danh từ."},{"wrong":"我要菜这个。","right":"我要这个菜。","why":"这个 đứng trước danh từ 菜, ngược với \"món này\" của tiếng Việt."}],"compare":"Tiếng Việt: danh từ + này/kia (\"cái áo này\"); tiếng Trung: 这/那 + lượng từ + danh từ (这件衣服) — thứ tự đảo ngược.","tip":"Chỉ tay trước rồi mới gọi tên: 这 / 那 luôn đi trước danh từ!","how":["Đặt 这个 trước danh từ 菜 → 这个菜 (món này), rồi thêm 多少钱 (bao nhiêu tiền) phía sau → 这个菜多少钱？","Đặt 那个 trước 人 → 那个人 (người kia), rồi thêm 是谁 (là ai) phía sau → 那个人是谁？","Đặt 那 + lượng từ 件 trước 衣服 → 那件衣服 (cái áo kia), rồi thêm 我想买 (tôi muốn mua) phía trước → 我想买那件衣服。"],"dialog":[{"who":"A","t":"这个多少钱？","ph":"Zhège duōshao qián?","vph":"Chưa cưa tua sảo chién?","vi":"Cái này bao nhiêu tiền?","hl":["这个"]},{"who":"B","t":"这个三十块。","ph":"Zhège sānshí kuài.","vph":"Chưa cưa san sứ khoai.","vi":"Cái này ba mươi tệ.","hl":["这个"]},{"who":"A","t":"那个呢？","ph":"Nàge ne?","vph":"Na cưa nơ?","vi":"Còn cái kia?","hl":["那个"]},{"who":"B","t":"那个便宜一点，二十块。","ph":"Nàge piányi yìdiǎn, èrshí kuài.","vph":"Na cưa p'ién i i tẻn, ơ sứ khoai.","vi":"Cái kia rẻ hơn chút, hai mươi tệ.","hl":["那个"]}],"more":[{"t":"那是什么？","ph":"Nà shì shénme?","vph":"Na sư sấn mơ?","vi":"Kia là gì?","hl":["那"],"tokens":["那","是","什么"]},{"t":"这是我朋友。","ph":"Zhè shì wǒ péngyou.","vph":"Chưa sư ủa p'ấng dâu.","vi":"Đây là bạn tôi.","hl":["这"],"tokens":["这","是","我","朋友"]},{"t":"我要这本书。","ph":"Wǒ yào zhè běn shū.","vph":"Ủa dao chưa pẩn su.","vi":"Tôi lấy quyển sách này.","hl":["这"],"tokens":["我","要","这","本","书"]},{"t":"那家饭店很有名。","ph":"Nà jiā fàndiàn hěn yǒumíng.","vph":"Na cha phan tiên hẩn dẩu mính.","vi":"Nhà hàng kia rất nổi tiếng.","hl":["那"],"tokens":["那","家","饭店","很","有名"]},{"t":"这杯咖啡是你的吗？","ph":"Zhè bēi kāfēi shì nǐ de ma?","vph":"Chưa pây kha phây sư nỉ tơ ma?","vi":"Ly cà phê này là của bạn à?","hl":["这"],"tokens":["这","杯","咖啡","是","你","的","吗"]},{"t":"这个房间比那个大。","ph":"Zhège fángjiān bǐ nàge dà.","vph":"Chưa cưa pháng chiên pỉ na cưa ta.","vi":"Phòng này rộng hơn phòng kia.","hl":["这个","那个"],"tokens":["这个","房间","比","那个","大"]}]},{"id":31,"vi":"của","note":"Sở hữu: người sở hữu + 的 + vật (ngược thứ tự tiếng Việt): 我的手机 = điện thoại của tôi. Với người thân thiết có thể bỏ 的: 我妈妈.","pivot":{"t":"的","ph":"de","vph":"tơ"},"branches":[{"steps":[{"t":"朋友","ph":"péngyou","vph":"p'ấng dâu","vi":"bạn bè","hl":[]},{"t":"我的朋友","ph":"wǒ de péngyou","vph":"ủa tơ p'ấng dâu","vi":"bạn của tôi","hl":["的"]},{"t":"他是我的朋友。","ph":"Tā shì wǒ de péngyou.","vph":"Tha sư ủa tơ p'ấng dâu.","vi":"Anh ấy là bạn của tôi.","hl":["的"],"tokens":["他","是","我","的","朋友"]}]},{"steps":[{"t":"护照","ph":"hùzhào","vph":"hu chao","vi":"hộ chiếu","hl":[]},{"t":"我的护照","ph":"wǒ de hùzhào","vph":"ủa tơ hu chao","vi":"hộ chiếu của tôi","hl":["的"]},{"t":"我的护照不见了。","ph":"Wǒ de hùzhào bú jiàn le.","vph":"Ủa tơ hu chao pú chiên lơ.","vi":"Hộ chiếu của tôi bị mất rồi.","hl":["的"],"tokens":["我","的","护照","不见","了"]}]},{"steps":[{"t":"包","ph":"bāo","vph":"pao","vi":"túi","hl":[]},{"t":"谁的包","ph":"shéi de bāo","vph":"suấy tơ pao","vi":"túi của ai","hl":["的"]},{"t":"这是谁的包？","ph":"Zhè shì shéi de bāo?","vph":"Chưa sư suấy tơ pao?","vi":"Đây là túi của ai?","hl":["的"],"tokens":["这","是","谁","的","包"]}]}],"formula":[{"k":"S","t":"Người sở hữu"},{"k":"P","t":"的"},{"k":"O","t":"Vật được sở hữu"}],"points":["Người sở hữu + 的 + vật: \"我的手机\" = điện thoại của tôi (ngược thứ tự tiếng Việt).","Với người thân, bạn bè, tập thể gần gũi có thể bỏ 的: \"我妈妈\", \"我们公司\".","的 cũng nối tính từ với danh từ: \"漂亮的衣服\" = quần áo đẹp.","Hỏi \"của ai\" dùng 谁的: \"这是谁的？\"; trả lời gọn: \"我的\"."],"mistakes":[{"wrong":"手机的我。","right":"我的手机。","why":"Dịch từng chữ \"điện thoại của tôi\" sẽ sai; tiếng Trung đặt người sở hữu lên trước 的."},{"wrong":"这是的我。","right":"这是我的。","why":"的 đứng SAU người sở hữu: 我的 = của tôi."}],"compare":"Tiếng Việt: vật + của + người (\"xe của tôi\"); tiếng Trung: người + 的 + vật (我的车) — đảo ngược hoàn toàn.","tip":"Chủ nhân luôn đi trước: \"tôi 的 xe\" — ai sở hữu thì người đó đứng đầu!","how":["Đặt 我的 trước 朋友 → 我的朋友 (bạn của tôi), rồi thêm 他是 (anh ấy là) phía trước → 他是我的朋友。","Đặt 我的 trước 护照 → 我的护照 (hộ chiếu của tôi), rồi thêm 不见了 (biến mất rồi) phía sau → 我的护照不见了。","Đặt 谁的 (của ai) trước 包 → 谁的包, rồi thêm 这是 phía trước để hỏi → 这是谁的包？"],"dialog":[{"who":"A","t":"这是你的行李吗？","ph":"Zhè shì nǐ de xíngli ma?","vph":"Chưa sư nỉ tơ xính li ma?","vi":"Đây là hành lý của bạn à?","hl":["的"]},{"who":"B","t":"不是，我的是红色的。","ph":"Bú shì, wǒ de shì hóngsè de.","vph":"Pú sư, ủa tơ sư húng xưa tơ.","vi":"Không phải, của tôi màu đỏ.","hl":["的"]},{"who":"A","t":"那个红色的箱子吗？","ph":"Nàge hóngsè de xiāngzi ma?","vph":"Na cưa húng xưa tơ xeng chư ma?","vi":"Cái vali màu đỏ kia à?","hl":["的"]},{"who":"B","t":"对，那是我的。谢谢！","ph":"Duì, nà shì wǒ de. Xièxie!","vph":"Tuây, na sư ủa tơ. Xiê xiê!","vi":"Đúng, đó là của tôi. Cảm ơn!","hl":["的"]}],"more":[{"t":"这是我的。","ph":"Zhè shì wǒ de.","vph":"Chưa sư ủa tơ.","vi":"Cái này là của tôi.","hl":["的"],"tokens":["这","是","我","的"]},{"t":"你的房间很大。","ph":"Nǐ de fángjiān hěn dà.","vph":"Nỉ tơ pháng chiên hẩn ta.","vi":"Phòng của bạn rất rộng.","hl":["的"],"tokens":["你","的","房间","很","大"]},{"t":"那是老师的书。","ph":"Nà shì lǎoshī de shū.","vph":"Na sư lảo sư tơ su.","vi":"Kia là sách của thầy giáo.","hl":["的"],"tokens":["那","是","老师","的","书"]},{"t":"我的手机没电了。","ph":"Wǒ de shǒujī méi diàn le.","vph":"Ủa tơ sẩu chi mấy tiên lơ.","vi":"Điện thoại của tôi hết pin rồi.","hl":["的"],"tokens":["我","的","手机","没","电","了"]},{"t":"我喜欢中国的茶。","ph":"Wǒ xǐhuan Zhōngguó de chá.","vph":"Ủa xỉ hoan Chung cúa tơ chá.","vi":"Tôi thích trà của Trung Quốc.","hl":["的"],"tokens":["我","喜欢","中国","的","茶"]},{"t":"他是我公司的同事。","ph":"Tā shì wǒ gōngsī de tóngshì.","vph":"Tha sư ủa cung xư tơ thúng sư.","vi":"Anh ấy là đồng nghiệp ở công ty tôi.","hl":["的"],"tokens":["他","是","我","公司","的","同事"]}]},{"id":32,"vi":"ở / tại","note":"Cụm 在 + nơi chốn đứng TRƯỚC động từ: Chủ ngữ + 在 + nơi chốn + động từ (khác tiếng Việt). Hỏi 'ở đâu' dùng 在哪儿 / 在哪里.","pivot":{"t":"在","ph":"zài","vph":"chai"},"branches":[{"steps":[{"t":"家","ph":"jiā","vph":"cha","vi":"nhà","hl":[]},{"t":"在家","ph":"zài jiā","vph":"chai cha","vi":"ở nhà","hl":["在"]},{"t":"我在家休息。","ph":"Wǒ zài jiā xiūxi.","vph":"Ủa chai cha xiêu xi.","vi":"Tôi nghỉ ngơi ở nhà.","hl":["在"],"tokens":["我","在","家","休息"]}]},{"steps":[{"t":"酒店","ph":"jiǔdiàn","vph":"chiểu tiên","vi":"khách sạn","hl":[]},{"t":"在酒店","ph":"zài jiǔdiàn","vph":"chai chiểu tiên","vi":"ở khách sạn","hl":["在"]},{"t":"我在酒店等你。","ph":"Wǒ zài jiǔdiàn děng nǐ.","vph":"Ủa chai chiểu tiên tẩng nỉ.","vi":"Tôi đợi bạn ở khách sạn.","hl":["在"],"tokens":["我","在","酒店","等","你"]}]},{"steps":[{"t":"哪儿","ph":"nǎr","vph":"nả","vi":"đâu","hl":[]},{"t":"在哪儿","ph":"zài nǎr","vph":"chai nả","vi":"ở đâu","hl":["在"]},{"t":"洗手间在哪儿？","ph":"Xǐshǒujiān zài nǎr?","vph":"Xỉ sẩu chiên chai nả?","vi":"Nhà vệ sinh ở đâu?","hl":["在"],"tokens":["洗手间","在","哪儿"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"在"},{"k":"O","t":"Nơi chốn"},{"k":"V","t":"Động từ"}],"points":["在 + nơi chốn đứng TRƯỚC động từ: \"我在家吃饭\" = Tôi ăn cơm ở nhà.","在 cũng làm động từ chính \"ở\": \"他在酒店\" = Anh ấy ở khách sạn.","Hỏi \"ở đâu\" dùng 在哪儿 / 在哪里: \"你在哪儿？\".","Phủ định \"không ở\" dùng 不在: \"他不在家\" = Anh ấy không có nhà."],"mistakes":[{"wrong":"我吃饭在家。","right":"我在家吃饭。","why":"Tiếng Việt đặt \"ở nhà\" cuối câu, tiếng Trung phải đưa 在家 lên trước động từ."},{"wrong":"我工作在银行。","right":"我在银行工作。","why":"Nơi làm việc 在银行 phải đứng trước động từ 工作."}],"compare":"Tiếng Việt: động từ + ở + nơi chốn (\"làm việc ở ngân hàng\"); tiếng Trung: 在 + nơi chốn + động từ (在银行工作) — nơi chốn đi trước hành động.","tip":"Phải \"đến chỗ\" rồi mới \"làm việc\": 在 + nơi chốn luôn xếp hàng trước động từ!","how":["Đặt 在 trước nơi chốn 家 → 在家 (ở nhà), rồi thêm chủ ngữ 我 ở đầu và động từ 休息 ở sau → 我在家休息。","Đặt 在 trước 酒店 → 在酒店 (ở khách sạn), rồi thêm 我 ở đầu và 等你 (đợi bạn) ở sau → 我在酒店等你。","Đặt 在 trước từ hỏi 哪儿 → 在哪儿 (ở đâu), rồi đặt 洗手间 (nhà vệ sinh) lên đầu → 洗手间在哪儿？"],"dialog":[{"who":"A","t":"你在哪儿？","ph":"Nǐ zài nǎr?","vph":"Nỉ chai nả?","vi":"Bạn đang ở đâu?","hl":["在"]},{"who":"B","t":"我在地铁站。","ph":"Wǒ zài dìtiězhàn.","vph":"Ủa chai ti thiể chan.","vi":"Tôi ở ga tàu điện ngầm.","hl":["在"]},{"who":"A","t":"好，我在门口等你。","ph":"Hǎo, wǒ zài ménkǒu děng nǐ.","vph":"Hảo, ủa chai mấn khẩu tẩng nỉ.","vi":"Được, tôi đợi bạn ở cổng.","hl":["在"]}],"more":[{"t":"他不在家。","ph":"Tā bú zài jiā.","vph":"Tha pú chai cha.","vi":"Anh ấy không có ở nhà.","hl":["在"],"tokens":["他","不","在","家"]},{"t":"你住在哪儿？","ph":"Nǐ zhù zài nǎr?","vph":"Nỉ chu chai nả?","vi":"Bạn sống ở đâu?","hl":["在"],"tokens":["你","住","在","哪儿"]},{"t":"我在银行工作。","ph":"Wǒ zài yínháng gōngzuò.","vph":"Ủa chai ín háng cung chua.","vi":"Tôi làm việc ở ngân hàng.","hl":["在"],"tokens":["我","在","银行","工作"]},{"t":"我们在车站见吧。","ph":"Wǒmen zài chēzhàn jiàn ba.","vph":"Ủa mân chai chưa chan chiên pa.","vi":"Chúng ta gặp nhau ở bến xe nhé.","hl":["在"],"tokens":["我们","在","车站","见","吧"]},{"t":"我想在这里拍照。","ph":"Wǒ xiǎng zài zhèlǐ pāizhào.","vph":"Ủa xẻng chai chưa lỉ p'ai chao.","vi":"Tôi muốn chụp ảnh ở đây.","hl":["在"],"tokens":["我","想","在","这里","拍照"]},{"t":"我每天在公司吃午饭。","ph":"Wǒ měitiān zài gōngsī chī wǔfàn.","vph":"Ủa mẩy thiên chai cung xư chư ủ phan.","vi":"Hằng ngày tôi ăn trưa ở công ty.","hl":["在"],"tokens":["我","每天","在","公司","吃","午饭"]}]},{"id":33,"vi":"với","note":"跟 + người + động từ = làm gì cùng với ai; cụm 跟... đứng trước động từ, thường thêm 一起 (cùng nhau). Có thể dùng 和 thay cho 跟.","pivot":{"t":"跟","ph":"gēn","vph":"cân"},"branches":[{"steps":[{"t":"朋友","ph":"péngyou","vph":"p'ấng dâu","vi":"bạn bè","hl":[]},{"t":"跟朋友","ph":"gēn péngyou","vph":"cân p'ấng dâu","vi":"với bạn bè","hl":["跟"]},{"t":"我跟朋友去吃饭。","ph":"Wǒ gēn péngyou qù chīfàn.","vph":"Ủa cân p'ấng dâu chuy chư phan.","vi":"Tôi đi ăn với bạn.","hl":["跟"],"tokens":["我","跟","朋友","去","吃饭"]}]},{"steps":[{"t":"我","ph":"wǒ","vph":"ủa","vi":"tôi","hl":[]},{"t":"跟我","ph":"gēn wǒ","vph":"cân ủa","vi":"theo tôi","hl":["跟"]},{"t":"请跟我来。","ph":"Qǐng gēn wǒ lái.","vph":"Chỉnh cân ủa lái.","vi":"Mời đi theo tôi.","hl":["跟"],"tokens":["请","跟","我","来"]}]},{"steps":[{"t":"你","ph":"nǐ","vph":"nỉ","vi":"bạn","hl":[]},{"t":"跟你","ph":"gēn nǐ","vph":"cân nỉ","vi":"với bạn","hl":["跟"]},{"t":"我想跟你一起去。","ph":"Wǒ xiǎng gēn nǐ yìqǐ qù.","vph":"Ủa xẻng cân nỉ i chỉ chuy.","vi":"Tôi muốn đi cùng với bạn.","hl":["跟"],"tokens":["我","想","跟","你","一起","去"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"跟"},{"k":"O","t":"Người"},{"k":"A","t":"(Cùng nhau)"},{"k":"V","t":"Động từ"}],"points":["跟 + người đứng TRƯỚC động từ: \"我跟朋友去\" = Tôi đi với bạn.","Hay thêm 一起 (cùng nhau) sau người: \"跟你一起去\" = đi cùng bạn.","跟 + người + 说 = nói với ai: \"我跟他说了\" = Tôi nói với anh ấy rồi.","Có thể dùng 和 thay cho 跟: \"我和朋友去\"; 跟 nghe khẩu ngữ hơn."],"mistakes":[{"wrong":"我去跟朋友。","right":"我跟朋友去。","why":"Tiếng Việt nói \"đi với bạn\" (với đứng sau động từ), tiếng Trung đưa 跟朋友 lên trước động từ."},{"wrong":"我一起跟你去。","right":"我跟你一起去。","why":"Thứ tự đúng là 跟 + người + 一起 + động từ."}],"compare":"Tiếng Việt: động từ + với + người (\"ăn với bạn\"); tiếng Trung: 跟 + người + động từ (跟朋友吃饭) — \"với ai\" đi trước hành động.","tip":"Chọn bạn đồng hành trước rồi mới lên đường: 跟 + người luôn đứng trước động từ!","how":["Đặt 跟 trước 朋友 → 跟朋友 (với bạn), rồi thêm 我 ở đầu và 去吃饭 (đi ăn) ở sau → 我跟朋友去吃饭。","Đặt 跟 trước 我 → 跟我 (theo tôi), rồi thêm 请 ở đầu và 来 ở sau → 请跟我来。","Đặt 跟 trước 你 → 跟你 (với bạn), thêm 一起去 (cùng đi) phía sau và 我想 phía trước → 我想跟你一起去。"],"dialog":[{"who":"A","t":"周末你跟谁去旅行？","ph":"Zhōumò nǐ gēn shéi qù lǚxíng?","vph":"Châu mua nỉ cân suấy chuy lủy xính?","vi":"Cuối tuần bạn đi du lịch với ai?","hl":["跟"]},{"who":"B","t":"我跟家人一起去。","ph":"Wǒ gēn jiārén yìqǐ qù.","vph":"Ủa cân cha rấn i chỉ chuy.","vi":"Tôi đi cùng gia đình.","hl":["跟"]},{"who":"A","t":"我可以跟你们一起去吗？","ph":"Wǒ kěyǐ gēn nǐmen yìqǐ qù ma?","vph":"Ủa khứa ỷ cân nỉ mân i chỉ chuy ma?","vi":"Tôi đi cùng mọi người được không?","hl":["跟"]},{"who":"B","t":"当然可以！","ph":"Dāngrán kěyǐ!","vph":"Tang rán khứa ỷ!","vi":"Tất nhiên là được!","hl":[]}],"more":[{"t":"我跟他说了。","ph":"Wǒ gēn tā shuō le.","vph":"Ủa cân tha sua lơ.","vi":"Tôi nói với anh ấy rồi.","hl":["跟"],"tokens":["我","跟","他","说","了"]},{"t":"你跟谁一起住？","ph":"Nǐ gēn shéi yìqǐ zhù?","vph":"Nỉ cân suấy i chỉ chu?","vi":"Bạn sống cùng ai?","hl":["跟"],"tokens":["你","跟","谁","一起","住"]},{"t":"我想跟你聊聊。","ph":"Wǒ xiǎng gēn nǐ liáoliao.","vph":"Ủa xẻng cân nỉ léo leo.","vi":"Tôi muốn nói chuyện với bạn một chút.","hl":["跟"],"tokens":["我","想","跟","你","聊聊"]},{"t":"她跟妈妈去买菜。","ph":"Tā gēn māma qù mǎi cài.","vph":"Tha cân ma ma chuy mải chai.","vi":"Cô ấy đi chợ với mẹ.","hl":["跟"],"tokens":["她","跟","妈妈","去","买","菜"]},{"t":"明天我要跟客户开会。","ph":"Míngtiān wǒ yào gēn kèhù kāihuì.","vph":"Mính thiên ủa dao cân khưa hu khai huây.","vi":"Ngày mai tôi phải họp với khách hàng.","hl":["跟"],"tokens":["明天","我","要","跟","客户","开会"]},{"t":"我们跟导游一起去长城。","ph":"Wǒmen gēn dǎoyóu yìqǐ qù Chángchéng.","vph":"Ủa mân cân tảo dấu i chỉ chuy Cháng chấng.","vi":"Chúng tôi cùng hướng dẫn viên đi Vạn Lý Trường Thành.","hl":["跟"],"tokens":["我们","跟","导游","一起","去","长城"]}]},{"id":34,"vi":"cho","note":"给 + người: làm động từ nghĩa là 'đưa cho' (给我一杯水), hoặc làm giới từ đứng trước động từ: 给 + người + động từ (给他打电话 = gọi điện cho anh ấy).","pivot":{"t":"给","ph":"gěi","vph":"cẩy"},"branches":[{"steps":[{"t":"我","ph":"wǒ","vph":"ủa","vi":"tôi","hl":[]},{"t":"给我","ph":"gěi wǒ","vph":"cẩy ủa","vi":"cho tôi","hl":["给"]},{"t":"请给我一杯水。","ph":"Qǐng gěi wǒ yì bēi shuǐ.","vph":"Chỉnh cẩy ủa i pây suẩy.","vi":"Cho tôi một cốc nước.","hl":["给"],"tokens":["请","给","我","一","杯","水"]}]},{"steps":[{"t":"你","ph":"nǐ","vph":"nỉ","vi":"bạn","hl":[]},{"t":"给你","ph":"gěi nǐ","vph":"cẩy nỉ","vi":"cho bạn","hl":["给"]},{"t":"这个给你。","ph":"Zhège gěi nǐ.","vph":"Chưa cưa cẩy nỉ.","vi":"Cái này cho bạn.","hl":["给"],"tokens":["这个","给","你"]}]},{"steps":[{"t":"打电话","ph":"dǎ diànhuà","vph":"tả tiên hoa","vi":"gọi điện thoại","hl":[]},{"t":"给他打电话","ph":"gěi tā dǎ diànhuà","vph":"cẩy tha tả tiên hoa","vi":"gọi điện cho anh ấy","hl":["给"]},{"t":"我明天给他打电话。","ph":"Wǒ míngtiān gěi tā dǎ diànhuà.","vph":"Ủa mính thiên cẩy tha tả tiên hoa.","vi":"Ngày mai tôi gọi điện cho anh ấy.","hl":["给"],"tokens":["我","明天","给","他","打电话"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"给"},{"k":"O","t":"Người nhận"},{"k":"V","t":"(Động từ)"},{"k":"O","t":"(Vật)"}],"points":["给 làm động từ \"đưa cho\": 给 + người + vật: \"给我一杯水\" = Đưa tôi một ly nước.","给 làm giới từ \"cho\" đứng TRƯỚC động từ: 给 + người + động từ: \"给他打电话\" = gọi điện cho anh ấy.","Nhờ ai làm gì cho mình: \"请给我看看\" = Cho tôi xem với.","Khi đưa đồ cho ai, nói ngắn \"给你。\" = Của bạn đây."],"mistakes":[{"wrong":"请给一杯水我。","right":"请给我一杯水。","why":"Người nhận (我) đứng ngay sau 给, vật đứng sau cùng."},{"wrong":"我买给妈妈一个礼物。","right":"我给妈妈买了一个礼物。","why":"Tiếng Việt nói \"mua cho mẹ\", tiếng Trung đưa 给妈妈 lên trước động từ 买."}],"compare":"Tiếng Việt: \"gọi điện cho anh ấy\" (cho + người đứng sau động từ); tiếng Trung: 给他打电话 (给 + người đứng trước động từ). Khi nghĩa là \"đưa\", 给我一杯水 lại giống \"đưa tôi một ly nước\".","tip":"Muốn làm gì \"cho\" ai thì gọi tên người đó trước: 给 + người, rồi mới đến việc làm!","how":["Đặt 给 trước 我 → 给我 (cho tôi), rồi thêm 请 ở đầu và vật 一杯水 ở cuối → 请给我一杯水。","Đặt 给 trước 你 → 给你 (đưa bạn), rồi đặt vật 这个 lên đầu → 这个给你。","Đặt 给他 (cho anh ấy) trước động từ 打电话 → 给他打电话, rồi thêm 我 và thời gian 明天 phía trước → 我明天给他打电话。"],"dialog":[{"who":"A","t":"服务员，请给我菜单。","ph":"Fúwùyuán, qǐng gěi wǒ càidān.","vph":"Phú u doén, chỉnh cẩy ủa chai tan.","vi":"Phục vụ ơi, cho tôi xem thực đơn.","hl":["给"]},{"who":"B","t":"好的，给您。","ph":"Hǎo de, gěi nín.","vph":"Hảo tơ, cẩy nín.","vi":"Vâng, gửi anh.","hl":["给"]},{"who":"A","t":"能给我们拍张照吗？","ph":"Néng gěi wǒmen pāi zhāng zhào ma?","vph":"Nấng cẩy ủa mân p'ai chang chao ma?","vi":"Chụp giúp chúng tôi một tấm ảnh được không?","hl":["给"]},{"who":"B","t":"没问题！","ph":"Méi wèntí!","vph":"Mấy uân thí!","vi":"Không vấn đề gì!","hl":[]}],"more":[{"t":"给你钱。","ph":"Gěi nǐ qián.","vph":"Cẩy nỉ chién.","vi":"Tiền đây, gửi bạn.","hl":["给"],"tokens":["给","你","钱"]},{"t":"请给我看看。","ph":"Qǐng gěi wǒ kànkan.","vph":"Chỉnh cẩy ủa khan khan.","vi":"Cho tôi xem với.","hl":["给"],"tokens":["请","给","我","看看"]},{"t":"我给你发微信。","ph":"Wǒ gěi nǐ fā Wēixìn.","vph":"Ủa cẩy nỉ pha Uây xin.","vi":"Tôi nhắn WeChat cho bạn.","hl":["给"],"tokens":["我","给","你","发","微信"]},{"t":"妈妈给我做饭。","ph":"Māma gěi wǒ zuò fàn.","vph":"Ma ma cẩy ủa chua phan.","vi":"Mẹ nấu cơm cho tôi.","hl":["给"],"tokens":["妈妈","给","我","做","饭"]},{"t":"我给朋友买了一个礼物。","ph":"Wǒ gěi péngyou mǎi le yí ge lǐwù.","vph":"Ủa cẩy p'ấng dâu mải lơ í cưa lỉ u.","vi":"Tôi mua cho bạn một món quà.","hl":["给"],"tokens":["我","给","朋友","买","了","一","个","礼物"]},{"t":"你能给我介绍一下吗？","ph":"Nǐ néng gěi wǒ jièshào yíxià ma?","vph":"Nỉ nấng cẩy ủa chiê sao í xa ma?","vi":"Bạn giới thiệu cho tôi một chút được không?","hl":["给"],"tokens":["你","能","给","我","介绍","一下","吗"]}]},{"id":35,"vi":"phải","note":"得 (đọc děi) + động từ = phải làm gì, hay dùng trong văn nói; 必须 trang trọng và mạnh hơn. Ngoài ra còn có 要 / 应该 (nên).","pivot":{"t":"得","ph":"děi","vph":"tẩy"},"branches":[{"steps":[{"t":"走","ph":"zǒu","vph":"chẩu","vi":"đi","hl":[]},{"t":"得走","ph":"děi zǒu","vph":"tẩy chẩu","vi":"phải đi","hl":["得"]},{"t":"我得走了。","ph":"Wǒ děi zǒu le.","vph":"Ủa tẩy chẩu lơ.","vi":"Tôi phải đi rồi.","hl":["得"],"tokens":["我","得","走","了"]}]},{"steps":[{"t":"早起","ph":"zǎoqǐ","vph":"chảo chỉ","vi":"dậy sớm","hl":[]},{"t":"得早起","ph":"děi zǎoqǐ","vph":"tẩy chảo chỉ","vi":"phải dậy sớm","hl":["得"]},{"t":"明天我得早起。","ph":"Míngtiān wǒ děi zǎoqǐ.","vph":"Mính thiên ủa tẩy chảo chỉ.","vi":"Ngày mai tôi phải dậy sớm.","hl":["得"],"tokens":["明天","我","得","早起"]}]},{"steps":[{"t":"护照","ph":"hùzhào","vph":"hu chao","vi":"hộ chiếu","hl":[]},{"t":"必须带护照","ph":"bìxū dài hùzhào","vph":"pi xuy tai hu chao","vi":"phải mang hộ chiếu","hl":["必须"]},{"t":"你必须带护照。","ph":"Nǐ bìxū dài hùzhào.","vph":"Nỉ pi xuy tai hu chao.","vi":"Bạn phải mang theo hộ chiếu.","hl":["必须"],"tokens":["你","必须","带","护照"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"得"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["得 (đọc děi) + động từ = phải làm gì, dùng nhiều trong văn nói: \"我得走了\" = Tôi phải đi rồi.","必须 trang trọng và mang tính bắt buộc mạnh hơn: \"你必须带护照\".","Phủ định \"không phải\" KHÔNG nói 不得, mà dùng 不用 hoặc 不必: \"你不用去\" = Bạn không cần đi.","Đừng nhầm với 得 (đọc de) đứng sau động từ chỉ mức độ: \"说得很好\" — cùng chữ nhưng khác cách đọc và nghĩa."],"mistakes":[{"wrong":"你不得去。","right":"你不用去。","why":"\"Không phải đi\" dùng 不用; 不得 nghĩa là \"không được phép\" (rất trang trọng)."},{"wrong":"我走得了。","right":"我得走了。","why":"得 (phải) đứng TRƯỚC động từ, giống chữ \"phải\" trong tiếng Việt."}],"compare":"Giống tiếng Việt: 得 đứng trước động từ như chữ \"phải\" (\"tôi phải đi\" = 我得走). Khác: \"không phải\" là 不用, không ghép 不 với 得.","tip":"得 đọc \"tẩy\" khi nghĩa là \"phải\" — \"tẩy\" xong là PHẢI đi ngay!","how":["Đặt 得 trước động từ 走 → 得走 (phải đi), rồi thêm chủ ngữ 我 ở đầu và 了 ở cuối (đến lúc rồi) → 我得走了。","Đặt 得 trước 早起 → 得早起 (phải dậy sớm), rồi thêm 明天 và chủ ngữ 我 phía trước → 明天我得早起。","Với việc bắt buộc thì dùng 必须 trước 带护照 → 必须带护照 (phải mang hộ chiếu), rồi đặt chủ ngữ 你 lên đầu → 你必须带护照。"],"dialog":[{"who":"A","t":"不早了，我得回酒店了。","ph":"Bù zǎo le, wǒ děi huí jiǔdiàn le.","vph":"Pu chảo lơ, ủa tẩy huấy chiểu tiên lơ.","vi":"Muộn rồi, tôi phải về khách sạn.","hl":["得"]},{"who":"B","t":"明天几点出发？","ph":"Míngtiān jǐ diǎn chūfā?","vph":"Mính thiên chỉ tẻn chu pha?","vi":"Mai mấy giờ xuất phát?","hl":[]},{"who":"A","t":"七点，我得六点起床。","ph":"Qī diǎn, wǒ děi liù diǎn qǐchuáng.","vph":"Chi tẻn, ủa tẩy liêu tẻn chỉ choáng.","vi":"Bảy giờ, tôi phải dậy lúc sáu giờ.","hl":["得"]},{"who":"B","t":"那你得早点儿睡。","ph":"Nà nǐ děi zǎo diǎnr shuì.","vph":"Na nỉ tẩy chảo tẻn suây.","vi":"Vậy bạn phải ngủ sớm một chút.","hl":["得"]}],"more":[{"t":"我得去银行。","ph":"Wǒ děi qù yínháng.","vph":"Ủa tẩy chuy ín háng.","vi":"Tôi phải đi ngân hàng.","hl":["得"],"tokens":["我","得","去","银行"]},{"t":"你得多喝水。","ph":"Nǐ děi duō hē shuǐ.","vph":"Nỉ tẩy tua hưa suẩy.","vi":"Bạn phải uống nhiều nước.","hl":["得"],"tokens":["你","得","多","喝","水"]},{"t":"今天我得加班。","ph":"Jīntiān wǒ děi jiābān.","vph":"Chin thiên ủa tẩy cha pan.","vi":"Hôm nay tôi phải tăng ca.","hl":["得"],"tokens":["今天","我","得","加班"]},{"t":"我们得快点儿走。","ph":"Wǒmen děi kuài diǎnr zǒu.","vph":"Ủa mân tẩy khoai tẻn chẩu.","vi":"Chúng ta phải đi nhanh lên.","hl":["得"],"tokens":["我们","得","快","点儿","走"]},{"t":"这件事我得问问老板。","ph":"Zhè jiàn shì wǒ děi wènwen lǎobǎn.","vph":"Chưa chiên sư ủa tẩy uân uân lảo pản.","vi":"Việc này tôi phải hỏi sếp đã.","hl":["得"],"tokens":["这","件","事","我","得","问问","老板"]},{"t":"上飞机前必须关手机。","ph":"Shàng fēijī qián bìxū guān shǒujī.","vph":"Sang phây chi chién pi xuy quan sẩu chi.","vi":"Trước khi lên máy bay phải tắt điện thoại.","hl":["必须"],"tokens":["上","飞机","前","必须","关","手机"]}]},{"id":36,"vi":"thử","note":"试试 + tân ngữ = thử cái gì; 试 + động từ (试穿, 试着说) = thử làm gì. Cũng có thể lặp động từ + 看: 尝尝看 (nếm thử xem).","pivot":{"t":"试试","ph":"shìshi","vph":"sư sư"},"branches":[{"steps":[{"t":"这个","ph":"zhège","vph":"chưa cưa","vi":"cái này","hl":[]},{"t":"试试这个","ph":"shìshi zhège","vph":"sư sư chưa cưa","vi":"thử cái này","hl":["试试"]},{"t":"你试试这个吧。","ph":"Nǐ shìshi zhège ba.","vph":"Nỉ sư sư chưa cưa pa.","vi":"Bạn thử cái này đi.","hl":["试试"],"tokens":["你","试试","这个","吧"]}]},{"steps":[{"t":"穿","ph":"chuān","vph":"choan","vi":"mặc","hl":[]},{"t":"试穿","ph":"shìchuān","vph":"sư choan","vi":"mặc thử","hl":["试"]},{"t":"我可以试穿吗？","ph":"Wǒ kěyǐ shìchuān ma?","vph":"Ủa khứa ỷ sư choan ma?","vi":"Tôi có thể mặc thử không?","hl":["试"],"tokens":["我","可以","试穿","吗"]}]},{"steps":[{"t":"说","ph":"shuō","vph":"sua","vi":"nói","hl":[]},{"t":"试着说","ph":"shìzhe shuō","vph":"sư chơ sua","vi":"thử nói","hl":["试着"]},{"t":"你试着说中文吧。","ph":"Nǐ shìzhe shuō Zhōngwén ba.","vph":"Nỉ sư chơ sua Chung uấn pa.","vi":"Bạn thử nói tiếng Trung đi.","hl":["试着"],"tokens":["你","试着","说","中文","吧"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"试试"},{"k":"O","t":"Tân ngữ / Việc muốn thử"}],"points":["试试 + tân ngữ = thử cái gì: \"试试这个\" = thử cái này.","试 ghép với động từ thành từ mới: 试穿 (mặc thử), 试吃 (ăn thử).","试着 + động từ = thử làm gì đó: \"试着说中文\" = thử nói tiếng Trung.","Lặp động từ + 看 = làm thử xem: \"尝尝看\" (nếm thử xem), \"问问看\" (hỏi thử xem)."],"mistakes":[{"wrong":"我可以穿试吗？","right":"我可以试穿吗？","why":"Tiếng Việt nói \"mặc thử\" (thử đứng sau), tiếng Trung đặt 试 lên trước: 试穿."},{"wrong":"你吃试一下。","right":"你尝尝看。","why":"\"Ăn thử\" không dịch từng chữ; dùng 尝尝看 (nếm thử xem) hoặc 试吃."}],"compare":"Tiếng Việt: động từ + thử (\"mặc thử\", \"ăn thử\"); tiếng Trung: 试 đứng trước (试穿, 试吃) hoặc lặp động từ + 看 (尝尝看).","tip":"Muốn thử gì thì \"thử\" đi trước: 试 dẫn đầu, việc làm theo sau!","how":["Đặt 试试 trước tân ngữ 这个 → 试试这个 (thử cái này), rồi thêm chủ ngữ 你 ở đầu và 吧 ở cuối để gợi ý → 你试试这个吧。","Ghép 试 với động từ 穿 → 试穿 (mặc thử), rồi thêm 我可以 phía trước và 吗 cuối câu để xin phép → 我可以试穿吗？","Ghép 试着 với 说 → 试着说 (thử nói), rồi thêm 你 ở đầu, 中文 sau động từ và 吧 ở cuối → 你试着说中文吧。"],"dialog":[{"who":"A","t":"这件衬衫可以试试吗？","ph":"Zhè jiàn chènshān kěyǐ shìshi ma?","vph":"Chưa chiên chân san khứa ỷ sư sư ma?","vi":"Áo sơ mi này thử được không?","hl":["试试"]},{"who":"B","t":"可以，试衣间在那边。","ph":"Kěyǐ, shìyījiān zài nàbiān.","vph":"Khứa ỷ, sư i chiên chai na piên.","vi":"Được, phòng thử đồ ở bên kia.","hl":["试"]},{"who":"A","t":"有点儿小。","ph":"Yǒudiǎnr xiǎo.","vph":"Dẩu tẻn xẻo.","vi":"Hơi chật.","hl":[]},{"who":"B","t":"那你试试大号的吧。","ph":"Nà nǐ shìshi dà hào de ba.","vph":"Na nỉ sư sư ta hao tơ pa.","vi":"Vậy bạn thử cỡ lớn nhé.","hl":["试试"]}],"more":[{"t":"我试试看。","ph":"Wǒ shìshi kàn.","vph":"Ủa sư sư khan.","vi":"Để tôi thử xem.","hl":["试试"],"tokens":["我","试试","看"]},{"t":"我能试吃吗？","ph":"Wǒ néng shìchī ma?","vph":"Ủa nấng sư chư ma?","vi":"Tôi ăn thử được không?","hl":["试"],"tokens":["我","能","试吃","吗"]},{"t":"你试试这双鞋。","ph":"Nǐ shìshi zhè shuāng xié.","vph":"Nỉ sư sư chưa soang xía.","vi":"Bạn thử đôi giày này xem.","hl":["试试"],"tokens":["你","试试","这","双","鞋"]},{"t":"我试了很多次。","ph":"Wǒ shì le hěn duō cì.","vph":"Ủa sư lơ hẩn tua chư.","vi":"Tôi đã thử rất nhiều lần.","hl":["试"],"tokens":["我","试","了","很","多","次"]},{"t":"我想试试这家的咖啡。","ph":"Wǒ xiǎng shìshi zhè jiā de kāfēi.","vph":"Ủa xẻng sư sư chưa cha tơ kha phây.","vi":"Tôi muốn thử cà phê của quán này.","hl":["试试"],"tokens":["我","想","试试","这","家","的","咖啡"]},{"t":"你可以试着问问服务员。","ph":"Nǐ kěyǐ shìzhe wènwen fúwùyuán.","vph":"Nỉ khứa ỷ sư chơ uân uân phú u doén.","vi":"Bạn có thể thử hỏi nhân viên phục vụ.","hl":["试着"],"tokens":["你","可以","试着","问问","服务员"]}]}];
